INSERT INTO nest_posts VALUES(71,2,'post-1767382017','Плащ','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/db774457-a979-4df0-aab6-a61174279283.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Я сидел на кровати окружённый фонариками из свечей."},{"type":"hardBreak"},{"type":"text","text":"А вокруг ни души. Лишь молчаливый штат вещей."},{"type":"hardBreak"},{"type":"text","text":"Я надевал на плечи простынь. Будто суперзлодей плащ."},{"type":"hardBreak"},{"type":"text","text":"А она шептала: \"Держи меня, я – свидетель твоих ночей!\""},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Лампа мерцала жёлтым. Тени прятались по углам."},{"type":"hardBreak"},{"type":"text","text":"Стрелки часов замерли. Будто пугались, боялись нас."},{"type":"hardBreak"},{"type":"text","text":"Как же хочу говорить с тобой! Мой воображаемый плащ."},{"type":"hardBreak"},{"type":"text","text":"Я никогда ещё не был таким свободным. Как сейчас."}]}]}','2026-01-02 19:26:57','2026-01-03 03:49:29',410,'2025-09-20T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(72,2,'post-1767384821','Бокал','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Всего на треть бокал собой исполнен."},{"type":"hardBreak"},{"type":"text","text":"На треть наполнен,"},{"type":"hardBreak"},{"type":"text","text":"Пуст на треть"},{"type":"hardBreak"},{"type":"text","text":"И кто он не оставшуюся треть?"},{"type":"hardBreak"},{"type":"text","text":"Не математик точно ведь,"},{"type":"hardBreak"},{"type":"text","text":"Ту нишу занял этого стихотворения"},{"type":"hardBreak"},{"type":"text","text":"Поэть"}]}]}','2026-01-02 20:13:41','2026-01-03 05:40:32',398,'2025-09-20T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(108,2,'post-1767394794','Человек','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ты видишь сон,"},{"type":"hardBreak"},{"type":"text","text":"В нём слышин стон"},{"type":"hardBreak"},{"type":"text","text":"Засохших крон,"},{"type":"hardBreak"},{"type":"text","text":"И тёплый снег"},{"type":"hardBreak"},{"type":"text","text":"Пришёл на миг,"},{"type":"hardBreak"},{"type":"text","text":"Ушёл на век."},{"type":"hardBreak"},{"type":"text","text":"Здесь ты всего лишь"},{"type":"hardBreak"},{"type":"text","text":"Человек"}]}]}','2026-01-02 22:59:54','2026-01-03 05:28:10',341,'2025-01-24T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(111,2,'post-1767396485','Мотылёк на реке Стикс','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Находится он во власти теченья,"},{"type":"hardBreak"},{"type":"text","text":"Реки у которой одно назначенье."},{"type":"hardBreak"},{"type":"text","text":"Глубины в которых нельзя утонуть,"},{"type":"hardBreak"},{"type":"text","text":"Раскроют душе её истинный путь!"}]},{"type":"image","attrs":{"src":"/assets/images/cfa3cb37-88e0-4cae-87ce-8164ac11638c.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"СИЗО"}]}]}','2026-01-02 23:28:05','2026-01-04 08:27:46',382,'2023-06-21T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(143,2,'post-1767401276','Я в сети!','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/92f0d36a-0962-4a4d-941a-d63d1cdec589.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Первая фотография из всех вообще что у меня есть! Примечательно, что она связана с компьютером! 🥹"}]}]}','2026-01-03 00:47:56','2026-01-05 23:31:53',412,'2002-09-11T20:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(144,2,'post-1767401856','Бакулёвский пруд','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мой любимый \"бревенчатый чат\". Сейчас тут молчат."}]},{"type":"image","attrs":{"src":"/assets/images/f4a8c822-8193-4f48-a968-2561d175fddc.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Почему-то больше всего запомнился телефонный диалог с Сашей, который пару лет не звонил находясь в Крыму. Не сказать, что осталось в этом диалоге, что-то важно для сейчас, но вайб того летнего вечера незабываемый. А ведь казалось бы, бревно и пруд. Только это?"}]},{"type":"image","attrs":{"src":"/assets/images/ceb5e70d-5d12-4c94-b912-17c66c9d13a0.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"И тоже место 5 лет спустя. Другой ракурс и это не только про камеру."}]}]}','2026-01-03 00:57:36','2026-01-03 05:16:31',413,'2025-08-02T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(145,2,'post-1767402003','Аморальная поддержка','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/f66cdeac-c695-4327-809e-e82be6c122ba.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"…я открыл глаза… зря. В холодильнике не оказалось пива. На небе не оказалось солнца. В плейлисте Joy Division заиграл сам собой. Бог, зачем ты воспитываешь моё терпение, зачем?…"}]},{"type":"paragraph","content":[{"type":"text","text":"Сегодня воскресенье, хочется чего-то необычное совершить. А вы чево задумали?"}]}]}','2026-01-03 01:00:03','2026-01-06 03:37:40',414,'2024-12-21T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(146,2,'post-1767402060','Идея путешествий во времени','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/099676a8-59ca-4551-a6ee-4859c0a133a7.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Москва, Воробьёвы Горы, вид из вагона проезжающего мимо метро"}]},{"type":"paragraph","content":[{"type":"text","text":"Мне также нравится идея путешествий во времени. Представляя себя в прошлом, мне не хочется ничего менять. Если бы я оказался в 2000, 2010 или 2016 году, я пользовался бы тем, что там продавалось — продукты, сигареты, вещи. Гулял и рассматривал улицы, дома, людей. Как мужчина на этой фотографии, я был бы увлечённым и задумчивым, потому что фокусировался на деталях, казался замедленным и неинтересным, а от того совершенно незаметным для окружающих. Поэтому мне нравится эта фотография. Это мог быть путешественник во времени из далёкого будущего, где Москва-река и окружение настолько изменились, что если бы этот мужчина помнил то время, в котором находится на фотографии, когда-то жил в нём, он бы так и стоял неподвижно, смотря вдаль, когда бы туда вернулся. Главная мысль — он не кричал бы о своём будущем всем! Смотрел бы наше прошлое один."}]}]}','2026-01-03 01:01:00','2026-01-06 00:04:25',417,'2020-07-16T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(147,2,'post-1767402132','Остановка','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/a586e9b4-de3e-4c95-968e-b20ad9d4a6b0.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Когда-то здесь стояла остановка. Я помню время, когда меня раздражало ходить от дома до Спички, считал это возмутительно далеко. Остановка появилась, когда я перестал ездить на общественном транспорте. Ирония в том, что её снесли. Какое-то время она служила местом для тусовки подростков, которые захламляли бутылками и пакетами чипсами все пространство вокруг нее. Надо было ей \"родиться\" раньше, когда была нужна. Сама виновата!"}]}]}','2026-01-03 01:02:12','2026-01-03 05:15:41',419,'2025-12-26T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(148,2,'post-1767402194','Набережная','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/b178cde3-6594-4229-94c5-9b0b43784867.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"В тюрьме часто представлял, как вернусь домой в Калугу и будет лето. И тогда я куплю грузинского вина, заберусь на холм в районе 906 базы и буду долго смотреть на мост и реку."}]},{"type":"paragraph","content":[{"type":"text","text":"Случилось вернуться в октябре, хотя и тогда было достаточно тепло то далекое ожидание реализовалось оставив тёплое воспоминание. Когда думаю об этом, то мне сложно понять, что воспринималось сильнее, представление или настоящий момент или это то, что нельзя сравнить между собой?"}]},{"type":"image","attrs":{"src":"/assets/images/e00fc8e1-9ff9-4a2f-9965-139bc8526031.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"А ещё мне хотелось прогуляться по набережной Оки. И почему-то я думал, что буду рад увидеть как её преобразили. Наверное потому, что соскучился по переменам и конечно не думал, что увидев пустынный пляж вместо зарослей, деревьев и кустов, буду скучать по тому как было."}]},{"type":"image","attrs":{"src":"/assets/images/8ba6dd45-f1f4-4791-8e04-d7869a49fc21.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Летом 2025 я любил ходить от дома до работы пешком. 6 км каждый день. Через эту набережную. Удивительно, но людей тут почти нет. Ни утром, ни вечером, в хорошую погоду. А мне так нравилось тут гулять. Теперь, с этим желтым пляжем напоминающим стройку, намного меньше."}]},{"type":"image","attrs":{"src":"/assets/images/f3b8da56-0c2c-4fa7-bbc8-b781ed826def.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"17 сент. 2020 г. чт, 15:28GMT +03:00"}]},{"type":"paragraph","content":[{"type":"text","text":"А вот по какому месту скучаю больше, так это по району понтонного моста! "}]}]}','2026-01-03 01:03:14','2026-01-03 05:16:19',421,'2025-12-24T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(149,2,'post-1767402427','Обмен энергией!','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Думаю эта та штука которой мне не хватает. Не энергии вообщем, но своего вайба."}]},{"type":"paragraph","content":[{"type":"text","text":"Есть люди с высокой потребностью в общении. Я такой. И когда общения мало могу увлечься например кодом или дизайном. Но не помню, что бы вспоминал, как дизайнил или писал код и скучал по этому. Не помню, что бы вспоминал как рисую что-то конкретное. То есть вот сейчас вспоминаю, что бы написать это. Но вообщем это не те воспоминания, которые доставляют удовольствие."}]},{"type":"paragraph","content":[{"type":"text","text":"Приятно вспоминать наблюдая себя со стороны, восстанавливая в памяти окружение, пытаясь заново прочувствовать запах воздуха, цвета и свет, звуки, но не конкретные диалоги. Почему-то их почти нет. "}]},{"type":"paragraph","content":[{"type":"text","text":"Не помню, когда задумывался о себе до 23 лет. Как если бы версия до была мне не так интересна. Хотя объективно я помню, как радостные моменты и в 19 лет, но они уже как будто \"не мои\". Не мной пережиты. Интересно, в 50 я буду вспоминать версию себя от 30, 35? В этом смысле мы похожи на ИИ, который помнит фиксированный контекст и каждое новое сообщение стирает прошлое из его памяти. У людей память остается, фрагментарна но остается. Однако отношение к этой памяти меняется и что-то перестаёт быть релевантным. Часть своей собственной жизни перестаёт быть релевантной. "}]}]}','2026-01-03 01:07:07','2026-01-03 06:02:56',425,'2025-12-22T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(150,2,'post-1767402451','Заснеженный Атлас','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/6e02de75-3ac0-4011-8787-f5ca026fdc01.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"31 окбября 2012"}]},{"type":"paragraph","content":[{"type":"text","text":"Снег падал, таял и снова шёл. Было тепло и радостно. Я давно не вспоминал себя до 2016, а это еще раньше, 13 лет – Маленькая жизнь. 13 лет назад, столько ещё не случилось, столько ещё впереди."}]}]}','2026-01-03 01:07:31','2026-01-03 05:15:55',426,NULL,'воспоминания');
INSERT INTO nest_posts VALUES(151,2,'post-1767402487','Этой зимой не хочется лета','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/2a095ce8-ca7a-4143-bce8-76efe366adc3.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Кажется, что это впервые. Представляю, как летом в это время сейчас только сумерки. И ночь будет теплой и станет манить, собраться и выйти куда-нибудь погулять. Но в городе нет тех, с кем хочется увидится. И скорее всего я бы просто напился и слушал музыку прокручивая в голове какой-нибудь вымышленный диалог. И когда вспоминаешь сколько раз так уже было, не хочется снова туда."}]},{"type":"paragraph","content":[{"type":"text","text":"А сейчас зима и за окном пушистый снег. На улицу совершенно не хочется. И нечего мне там делать."}]}]}','2026-01-03 01:08:07','2026-01-07 17:17:48',427,'2025-12-29T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(152,2,'post-1767402527','Идея','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"– создать непрерывную ленту из текста, фотографий и музыки (плеер)."}]},{"type":"paragraph","content":[{"type":"text","text":"Сейчас тут редактор, который позволяет мне (авторизованному пользователю) писать как если бы работал с файлом, добавлять фотографии из буфера, музыку по ссылкам. Прогресс сохраняется автоматически. Таким образом я могу постепенно \"уплотнять\" этот одностраничный блог. Особенно интересно вставлять фотографию и писать короткий очерк о том, что с ней связанно. "}]},{"type":"paragraph","content":[{"type":"text","text":"Хочется попробовать, когда блог вырастит достаточно большим, превратить это в базу знаний ИИ. Вычленить мой Войс оф Тон и создать себя как ИИ агента. Фактически этот парень будет говорить со мной, когда когда стану стариком, он останется в моём текущем, относительно молодом возрасте. И так я смогу говорить с собой абсолютно вербально. Со своей памятью и своим языком. Должно быть это довольно сильный диссонанс. Уже не терпится попробовать!"}]}]}','2026-01-03 01:08:47','2026-01-05 23:19:19',428,'2025-12-29T21:00:00.000Z','разработка');
INSERT INTO nest_posts VALUES(153,2,'post-1767402556','История Буратино','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/e2224785-1faf-4786-adaa-d06c625705f1.jpg","alt":null,"title":null}},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Вначале не было слова"}]},{"type":"paragraph","content":[{"type":"text","text":"Вначале не было слова. Если бы я умел говорить одним единственным, простым словом, я бы, наверное, крикнул — \"Ёб твою мать!\" — потому что первое, что я испытал, была боль. И это, пожалуй, первое чувство, которое я запомнил. Не помню матери. Не помню, как меня создали. Я помню только её — боль. Это ощущение, с которым сталкивается каждый, кто хоть раз споткнулся, обжегся или ушибся. Это знакомая, но при этом чуждая боль, с которой приходится мириться. В первые мгновения это не страшно. Это просто — боль. А потом… потом начинаешь понимать, что она становится частью тебя."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Боль — это первое, что я помню"}]},{"type":"paragraph","content":[{"type":"text","text":"Боль — вот и всё, что я помню. Не знал тогда, что все живые чувствуют её. И только спустя время, когда я научился смотреть вокруг, понял, что это — не исключение, а правило. Мир полон боли, как и жизни, впрочем. Она в том, как деревья ломаются под порывами ветра, как люди теряют надежду. Но вот образ, который заполнил меня целиком, был иным. Он был не ярким и не явным, как боль, он был скрытым, подобно свету, который ослепляет, но которого нельзя увидеть глазами. И этот свет был в глазах моего отца — Карло."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Самое главное — глазами не увидишь"}]},{"type":"paragraph","content":[{"type":"text","text":"Любовь. Это то, что создаёт, поддерживает, разрушает и вновь рождает. Но, чтобы понять это, нужно почувствовать, а не увидеть. Любовь — это тот инструмент, которым меня создали, и который связывает меня с вами, с читателями. Я, персонаж, стоящий сейчас на границе двух миров, заходит в ваш, тихо, незаметно, но для тех, кто верит в меня, я становлюсь частью этого мира. Да, вы не можете увидеть меня, но это не важно. Самое главное — вы не увидите меня глазами. Вы почувствуете."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Когда я проснулся, я увидел любовь"}]},{"type":"paragraph","content":[{"type":"text","text":"Когда я проснулся, я увидел любовь. В глазах отца. Любовь — это то, что не имеет формы, но наполняет мир. Это был не просто взгляд, это было признание жизни в том, что ты создаёшь, даже если это создание — просто брусок дерева, ставший живым. Отец был одинок. В этом мире, полном скрытых правил, он оказался одним из тех, кто не стремился к признанию. Его богатство не мерялось деньгами, а только тем светом, который он сам излучал. Мир гнал его на обочину, но это не означало, что его не было. Он видел волшебство в самых обыденных вещах, в простом бруске, в зеркале, в котором когда-то он увидел себя. Он не хотел богатства. Он искал смысла."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Отец, мир и я"}]},{"type":"paragraph","content":[{"type":"text","text":"Отец жил, как никто другой. Он был слеп, глуп и одинок в глазах этого мира, но мир сам по себе был слепым, когда не мог увидеть в нём ценность. А ценность заключалась не в том, что видно глазами, а в том, что не видишь, но чувствуешь. Отец был как тот мудрец, который не требовал признания, не искал славы. Его богатство заключалось не в том, что у него было, а в том, что он мог создавать. Но его никто не понимал. Он стал тем, кто создал меня, кто дал мне форму, кто вдохнул жизнь в дерево. Как бы это ни было странно для людей, но это было важно для меня."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Мир, который нас отвергает, но всё же нас создает"}]},{"type":"paragraph","content":[{"type":"text","text":"Мир людей отвергал его, не видел в нём ничего важного. Он был беден, но в его бедности был скрыт огромный смысл. Он не хотел богатства — оно не имело для него значения. Но ценность его жизни была именно в том, что он создал меня. И я, Буратино, его творение, с каждым шагом начинаю понимать, что не всё в мире измеряется материальными благами. Мир может отвергать нас, может не понимать, но он всё равно нас создает, если мы, в свою очередь, способны дать ему что-то — даже если это что-то такое странное, как я. Я — его сын. Я — Буратино."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Так начинается моя история"}]},{"type":"paragraph","content":[{"type":"text","text":"Вот так и начинается моя история. Не с того, что я был деревянным и потерянным, не с того, что я был лишь куклой в чужих руках. Всё началось с боли, с этого первичного ощущения. И с любви, которая пришла позже, вместе с осознанием моего места в этом мире. А может, это и есть самое важное: начать осознавать, что ты не просто вещь, а нечто большее. И если даже мир тебя не понимает, это не значит, что ты не существуешь. Это значит, что ты создаёшь свой мир — шаг за шагом, день за днём. И он, этот мир, будет нуждаться в тебе, даже если сам ещё не понимает, зачем."}]}]}','2026-01-03 01:09:16','2026-01-03 06:00:33',429,'2023-02-14T21:00:00.000Z','рассказы');
INSERT INTO nest_posts VALUES(155,2,'post-1767402682','От ума Без ума','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Не верь мне на слово,"},{"type":"hardBreak"},{"type":"text","text":"Верь в слово."},{"type":"hardBreak"},{"type":"text","text":"То, что бесшумно заиграло в голове."},{"type":"hardBreak"},{"type":"text","text":"От первой ноты из пространства вне,"},{"type":"hardBreak"},{"type":"text","text":"В последнюю ту ноту, что услышишь после"},{"type":"hardBreak"},{"type":"text","text":"Душой отыгранную в перерыве на войне,"},{"type":"hardBreak"},{"type":"text","text":"Усталому уму, в его прекрасном сне."}]}]}','2026-01-03 01:11:22','2026-01-03 01:13:14',430,'2021-07-17T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(156,2,'post-1767402771','Android','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Умею писать и считать,"},{"type":"hardBreak"},{"type":"text","text":"Знаю цену вещам и поступкам"},{"type":"hardBreak"},{"type":"text","text":"Моя одежда стильна и опрятна,"},{"type":"hardBreak"},{"type":"text","text":"Тело красиво и молодо,"},{"type":"hardBreak"},{"type":"text","text":"Будем знакомы я новый андроид,"},{"type":"hardBreak"},{"type":"text","text":"Создан специально под вас,"},{"type":"hardBreak"},{"type":"text","text":"Пожалуйста вспомните мое имя,"},{"type":"hardBreak"},{"type":"text","text":"Так подтвердите свой заказ,"},{"type":"hardBreak"},{"type":"text","text":"Пожалуйста, вспомните имя"},{"type":"hardBreak"},{"type":"text","text":"Пока батарейка жива, я так похожа на вас…"},{"type":"hardBreak"},{"type":"text","text":"Так похожа на Вас…"}]}]}','2026-01-03 01:12:51','2026-01-03 01:14:06',432,'2022-07-19T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(158,2,'post-1767402850','Мышеловка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Если бы я мог варить сыр,"},{"type":"hardBreak"},{"type":"text","text":"То отправил бы его тебе,"},{"type":"hardBreak"},{"type":"text","text":"Хуле ты думаешь там о себе?"},{"type":"hardBreak"},{"type":"text","text":"Живешь в Москве, ходишь в офис,"},{"type":"hardBreak"},{"type":"text","text":"Спишь на чужом матрасе, в однушке где,"},{"type":"hardBreak"},{"type":"text","text":"Умир чей-то старик, а теперь доживаешь ты,"},{"type":"hardBreak"},{"type":"text","text":"Между метро, опенспейсом и баром с пивом,"},{"type":"hardBreak"},{"type":"text","text":"Эта жизнь точно принадлежит тебе?"},{"type":"hardBreak"},{"type":"text","text":"Мне даже спрашивать о том неловко"},{"type":"hardBreak"},{"type":"text","text":"Держи сыр друг, ты в мышеловке!"}]}]}','2026-01-03 01:14:10','2026-01-03 06:01:00',433,'2021-10-27T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(159,2,'post-1767402913','Крот','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Это тетрадь для нот!"},{"type":"hardBreak"},{"type":"text","text":"Забудь числа и буквы енот!"},{"type":"hardBreak"},{"type":"text","text":"Позвольте, учитель крот,"},{"type":"hardBreak"},{"type":"text","text":"С чего бы ваш маленький рот,"},{"type":"hardBreak"},{"type":"text","text":"Научит мои глаза,"},{"type":"hardBreak"},{"type":"text","text":"Как тут творить чудеса?"},{"type":"hardBreak"},{"type":"text","text":"Ведь вы от рожденья слеп!"},{"type":"hardBreak"},{"type":"text","text":"Не видят ваши отростки,"},{"type":"hardBreak"},{"type":"text","text":"Ментальной картины наброски,"},{"type":"hardBreak"},{"type":"text","text":"Что я создаю между делом,"},{"type":"hardBreak"},{"type":"text","text":"Астральным своим сука телом!"}]},{"type":"image","attrs":{"src":"/assets/images/bb1d3f71-02a1-4e28-afbb-415f04b81669.png","alt":null,"title":null}}]}','2026-01-03 01:15:13','2026-01-06 00:58:19',434,'2021-11-01T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(160,2,'post-1767402963','Untitledы','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/d8f7b8bd-e6ef-40cc-a457-9796a214706b.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Это должна быть подпись к картинка: Поел и пою"}]},{"type":"paragraph","content":[{"type":"text","text":"Снегири покидают улочки,"},{"type":"hardBreak"},{"type":"text","text":"Дорожают в Пятёрочке курочки."},{"type":"hardBreak"},{"type":"text","text":"Мне плохо, мне грустно без Тани, INSERT INTO nest_posts VALUES(162,2,'post-1767403173','Урок 10','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"10 Королевство, это конура детства,"},{"type":"hardBreak"},{"type":"text","text":"Из породистой гончей, в дворнягу,"},{"type":"hardBreak"},{"type":"text","text":"Из еды мантры да грибы,"},{"type":"hardBreak"},{"type":"text","text":"Пропуская волка, я решил выбрать Фенрира,"},{"type":"hardBreak"},{"type":"text","text":"И Елку!"}]}]}','2026-01-03 01:19:33','2026-01-06 01:12:43',422,'2022-01-19T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(163,2,'post-1767403261','Караблик','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В ручье где кораблик вырванной страницей,"},{"type":"hardBreak"},{"type":"text","text":"Подпевая синице рвет полотно воды."},{"type":"hardBreak"},{"type":"text","text":"Где неба синюю гладь за минуту наполняют тучи."},{"type":"hardBreak"},{"type":"text","text":"Где солнце скрываясь за ними играет против, но с нами!"}]},{"type":"paragraph","content":[{"type":"text","text":"В сговоре с громом оно молчит,"},{"type":"hardBreak"},{"type":"text","text":"А молния сверкает, небо кричит!"},{"type":"hardBreak"},{"type":"text","text":"Ребята прячутся под козырьком,"},{"type":"hardBreak"},{"type":"text","text":"А мы с тобой, тихо тайком…"}]},{"type":"paragraph","content":[{"type":"text","text":"Целуемся как в первый раз,"},{"type":"hardBreak"},{"type":"text","text":"Никого и ничего не боясь."}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Стих написан в потоке буквально минут за 15-20.\nОднако я перечитываю и кажется, что четверостишия,\nбудто это творчество не только мое. Странное, очень странное чувство."}]}]}','2026-01-03 01:21:01','2026-01-04 14:12:24',423,'2022-02-21T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(165,2,'post-1767403637','Между','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Вряд Ли кто-то станет с тем спорить,"},{"type":"hardBreak"},{"type":"text","text":"Что есть уроки, которые нам всем стоит усвоить…"},{"type":"hardBreak"},{"type":"text","text":"Я сомневаюсь, не знаю, не помню но буду,"},{"type":"hardBreak"},{"type":"text","text":"Верить в чудо которое сотворю сам!"}]},{"type":"paragraph","content":[{"type":"text","text":"Не твоя секретарша, не твой зам ни мой учитель."},{"type":"hardBreak"},{"type":"text","text":"Никто из вас, никто из ваших мест и имений,"},{"type":"hardBreak"},{"type":"text","text":"Нет никого кто способен меня описать так."},{"type":"hardBreak"},{"type":"text","text":"Вот ты, вот она вот знак. А я между."}]}]}','2026-01-03 01:27:17','2026-01-06 01:21:51',436,'2022-02-21T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(166,2,'post-1767403675','Ночное','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Нарисуй на полу круг,"},{"type":"hardBreak"},{"type":"text","text":"Встань по центру и тихо жди,"},{"type":"hardBreak"},{"type":"text","text":"Из рисунка вырастут вдруг,"},{"type":"hardBreak"},{"type":"text","text":"Стены что никто не способен снести."}]},{"type":"paragraph","content":[{"type":"text","text":"В центре каждой стены дверь,"},{"type":"hardBreak"},{"type":"text","text":"Но их сам отпирать не спеши."},{"type":"hardBreak"},{"type":"text","text":"Дай ключи в руки лишь тем,"},{"type":"hardBreak"},{"type":"text","text":"Кто достоен твоей души."}]}]}','2026-01-03 01:27:55','2026-01-03 01:30:28',437,'2023-01-28T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(167,2,'post-1767403794','Крыса','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Крыса может оставить след,"},{"type":"hardBreak"},{"type":"text","text":"На мешке, где хранится зерно."},{"type":"hardBreak"},{"type":"text","text":"Крыса слышала часто совет,"},{"type":"hardBreak"},{"type":"text","text":"Что нельзя брать чужое добро."}]},{"type":"paragraph","content":[{"type":"text","text":"Люди скажут - она вредитель,"},{"type":"hardBreak"},{"type":"text","text":"Люди могут насыпать яд,"},{"type":"hardBreak"},{"type":"text","text":"Но ведь крыса тоже родитель!"},{"type":"hardBreak"},{"type":"text","text":"Для своих несмышленых крысят."}]},{"type":"paragraph","content":[{"type":"text","text":"Она бегала в поле когда-то,"},{"type":"hardBreak"},{"type":"text","text":"Собирала крысятам еду."},{"type":"hardBreak"},{"type":"text","text":"А потом все колосья собрали,"},{"type":"hardBreak"},{"type":"text","text":"Привлекли в ее норку беду."}]},{"type":"paragraph","content":[{"type":"text","text":"Люди скажут - она ворует!"},{"type":"hardBreak"},{"type":"text","text":"Но подумайте, разве вор?…"},{"type":"hardBreak"},{"type":"text","text":"Тот, кто жизнью своей рискует,"},{"type":"hardBreak"},{"type":"text","text":"Возвращая своё в свой же двор?"}]},{"type":"paragraph","content":[{"type":"text","text":"--"},{"type":"hardBreak"},{"type":"text","text":"Редактор рифмы "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://support.google.com/webmasters/answer/2445990?hl=ru","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"Евгений"}]}]}','2026-01-03 01:29:54','2026-01-03 01:30:26',438,'2023-01-30T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(168,2,'post-1767403831','Комар Хайям №01','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/3303e17f-9c0a-4796-a52f-a2fc9445ba3e.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Как моллюск в ракушке,"},{"type":"hardBreak"},{"type":"text","text":"Один без тебя в евродвушке."},{"type":"hardBreak"},{"type":"text","text":"Кручусь, верчусь, но нихера не свечусь."},{"type":"hardBreak"},{"type":"text","text":"Хоть фосфором натру бока. Пока!"}]}]}','2026-01-03 01:30:31','2026-01-03 01:31:15',439,'2023-02-14T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(169,2,'post-1767403894','Голос','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/5b420a62-7c27-4b59-b18d-5578d9917610.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"На миг представь,"},{"type":"hardBreak"},{"type":"text","text":"Что в этом мире,"},{"type":"hardBreak"},{"type":"text","text":"Есть все кого любили."},{"type":"hardBreak"},{"type":"text","text":"Тогдаб они на перебой,"},{"type":"hardBreak"},{"type":"text","text":"Внутри кричали,"},{"type":"hardBreak"},{"type":"text","text":"Этот голос – мой!"}]},{"type":"paragraph","content":[{"type":"text","text":"--"}]},{"type":"paragraph","content":[{"type":"text","text":"Для обсуждения: стоит ли иллюстрировать свои стихи чужими рисунками?"}]}]}','2026-01-03 01:31:34','2026-01-06 03:04:47',440,'2023-02-16T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(170,2,'post-1767403981','Канатоходец','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/365b31c1-255b-447b-8ff6-c69470601202.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"На работу путь,"},{"type":"hardBreak"},{"type":"text","text":"Тончайшая струна."},{"type":"hardBreak"},{"type":"text","text":"С толстой попой ты,"},{"type":"hardBreak"},{"type":"text","text":"Словно канатоходец. Идёшь."},{"type":"hardBreak"},{"type":"text","text":"На вино-водочный падёт взгляд"},{"type":"hardBreak"},{"type":"text","text":"И в тот же миг камнем... Падёшь! >–|o"}]}]}','2026-01-03 01:33:01','2026-01-03 01:37:54',441,'2017-06-14T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(171,2,'post-1767404277','Колян Хайям №2','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/a66e82e4-47d3-4962-87b8-e50577034088.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Колян Хуйям, привыкший жить вполоборот"},{"type":"hardBreak"},{"type":"text","text":"Ложил на карму болт и вот однажды оп!"},{"type":"hardBreak"},{"type":"text","text":"Кармическое воздаяне сделав оборот,"},{"type":"hardBreak"},{"type":"text","text":"Предстало перед сударем в фуражках,"},{"type":"hardBreak"},{"type":"text","text":"Которые незамедлительно и точно"},{"type":"hardBreak"},{"type":"text","text":"Его буквально, неформально, точно"},{"type":"hardBreak"},{"type":"text","text":"Не объяснив причины выебали в рот"}]}]}','2026-01-03 01:37:57','2026-01-05 23:19:55',442,'2017-06-07T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(172,2,'post-1767404364','Наблюдатель','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В тенях миров — разбитых, странных,"},{"type":"hardBreak"},{"type":"text","text":"Я растворяюсь, словно тень."},{"type":"hardBreak"},{"type":"text","text":"Там мысли стынут, свет бесправен,"},{"type":"hardBreak"},{"type":"text","text":"А ночь глотает новый день."}]},{"type":"paragraph","content":[{"type":"text","text":"Здесь каждый вздох как тайна века,"},{"type":"hardBreak"},{"type":"text","text":"Где страх, как страж у древних врат."},{"type":"hardBreak"},{"type":"text","text":"И я иду без человека,"},{"type":"hardBreak"},{"type":"text","text":"Оставив тело как наряд."}]}]}','2026-01-03 01:39:24','2026-01-03 01:40:13',443,'2024-12-16T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(173,2,'post-1767404430','Иду','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я Иду и вижу мир,"},{"type":"hardBreak"},{"type":"text","text":"Который вражен!"},{"type":"hardBreak"},{"type":"text","text":"Он, не мил мне,"},{"type":"hardBreak"},{"type":"text","text":"Он продажен."},{"type":"hardBreak"},{"type":"text","text":"Всюду колья, ограждения,"},{"type":"hardBreak"},{"type":"text","text":"Стражи вражьи,"},{"type":"hardBreak"},{"type":"text","text":"Тучи в лужих."},{"type":"hardBreak"},{"type":"text","text":"Социальные бомжи."},{"type":"hardBreak"},{"type":"text","text":"И почему я в мире этом?"},{"type":"hardBreak"},{"type":"text","text":"Где ж любимые друзья?"},{"type":"hardBreak"},{"type":"text","text":"…"},{"type":"hardBreak"},{"type":"text","text":"Кажется, как будто сбился я с пути,"},{"type":"hardBreak"},{"type":"text","text":"Но в этот мир я все-таки хочу прийти"},{"type":"hardBreak"},{"type":"text","text":"Пройти его и может быть понять"},{"type":"hardBreak"},{"type":"text","text":"Что не способен не найдя"},{"type":"hardBreak"},{"type":"text","text":"Себя я потерять"}]}]}','2026-01-03 01:40:30','2026-01-03 01:42:11',444,'2025-01-30T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(174,2,'post-1767404485','ИКIII','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Здоровья погибшим,"},{"type":"hardBreak"},{"type":"text","text":"Улыбок скорбящим."},{"type":"hardBreak"},{"type":"text","text":"Мой мир ебанутый,"},{"type":"hardBreak"},{"type":"text","text":"Зато настоящий!"}]}]}','2026-01-03 01:41:25','2026-01-06 03:31:58',445,'2023-12-22T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(175,2,'post-1767404548','Балкон','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"У облаков есть свойство,"},{"type":"hardBreak"},{"type":"text","text":"Влиять на мое спокойствие."},{"type":"hardBreak"},{"type":"text","text":"Они заслоняя солнце,"},{"type":"hardBreak"},{"type":"text","text":"Напоминаю квартиры плен."}]},{"type":"paragraph","content":[{"type":"text","text":"Зашторенны окны, лампы свет."},{"type":"hardBreak"},{"type":"text","text":"Внутри кто-то бродит,"},{"type":"hardBreak"},{"type":"text","text":"Я это или нет?"},{"type":"hardBreak"},{"type":"text","text":"Нет, еще не ты, нет."}]},{"type":"paragraph","content":[{"type":"text","text":"День без сна,"},{"type":"hardBreak"},{"type":"text","text":"Бредит, бредит, бродит…"},{"type":"hardBreak"},{"type":"text","text":"Затем, как всегда громко,"},{"type":"hardBreak"},{"type":"text","text":"Отрывает балконную дверь,"}]},{"type":"paragraph","content":[{"type":"text","text":"Смотри у него, что-то выходит…"},{"type":"hardBreak"},{"type":"text","text":"Да это же он сам вроде?"},{"type":"hardBreak"},{"type":"text","text":"Выходит и улыбается,"},{"type":"hardBreak"},{"type":"text","text":"Censored поэт!"}]}]}','2026-01-03 01:42:28','2026-01-03 01:42:41',446,'2024-11-19T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(176,2,'post-1767404610','Слова поддержки любимой девушке','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Смотрю я на фото…"},{"type":"hardBreak"},{"type":"text","text":"Ну почему бегемота?"},{"type":"hardBreak"},{"type":"text","text":"Не так ты страшна!"},{"type":"hardBreak"},{"type":"text","text":"Поверь мне, родная,"},{"type":"hardBreak"},{"type":"text","text":"Пизанская башня,"},{"type":"hardBreak"},{"type":"text","text":"Тоже кривая."}]}]}','2026-01-03 01:43:30','2026-01-03 01:43:45',447,'2024-11-04T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(177,2,'post-1767404638','Пони','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Если бы я был пони,"},{"type":"hardBreak"},{"type":"text","text":"То умер в 12 лет,"},{"type":"hardBreak"},{"type":"text","text":"Когда подряд пол пачки,"},{"type":"hardBreak"},{"type":"text","text":"За раз искурил сигарет."}]}]}','2026-01-03 01:43:58','2026-01-03 01:44:09',448,'2024-12-05T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(178,2,'post-1767404657','Any Field','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Люблю писать, рисовать"},{"type":"hardBreak"},{"type":"text","text":"Вытаскивать из своей головы мысли"},{"type":"hardBreak"},{"type":"text","text":"В блокнот, тетрадь"},{"type":"hardBreak"},{"type":"text","text":"Там орать, страдать и мечтать"},{"type":"hardBreak"},{"type":"text","text":"Делиться своим с миром,"},{"type":"hardBreak"},{"type":"text","text":"Не переставать от мира ждать,"},{"type":"hardBreak"},{"type":"text","text":"Парень, да ты талантище блядь!"},{"type":"hardBreak"},{"type":"text","text":"С тобой в любом поле за честь срать!"}]}]}','2026-01-03 01:44:17','2026-01-03 06:05:51',449,'2024-12-18T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(179,2,'post-1767404689','Йети','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Весь мир мой дом,"},{"type":"hardBreak"},{"type":"text","text":"Мы живём и учимся в нём."},{"type":"hardBreak"},{"type":"text","text":"Когда вырасту стариком,"},{"type":"hardBreak"},{"type":"text","text":"Учить меня станут дети."},{"type":"hardBreak"},{"type":"text","text":"Мы в этом мире, как йети!"},{"type":"hardBreak"},{"type":"text","text":"Магических обезъян,"},{"type":"hardBreak"},{"type":"text","text":"Потомки."}]},{"type":"image","attrs":{"src":"/assets/images/425d8eea-186b-47be-8380-aaefe6e63711.jpg","alt":null,"title":null}}]}','2026-01-03 01:44:49','2026-01-04 08:40:06',450,'2022-10-12T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(180,2,'post-1767404729','PostApp','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Боже может ты ржож с моей рожи,"},{"type":"hardBreak"},{"type":"text","text":"Или давай иначе, пусть дьявол будет лох,"},{"type":"hardBreak"},{"type":"text","text":"А Сатана жрет в лесу санный мох"},{"type":"hardBreak"},{"type":"text","text":"Чтож вы молчите хором,"},{"type":"hardBreak"},{"type":"text","text":"Ангелы, подняв взгляд,"},{"type":"hardBreak"},{"type":"text","text":"Мы покурить вышли, как-то хуево нам тут,"},{"type":"hardBreak"},{"type":"text","text":"Может со дна снова всплыть,"},{"type":"hardBreak"},{"type":"text","text":"В черта раскрасится местного,"},{"type":"hardBreak"},{"type":"text","text":"Чтоб отличали свои, ту петрушку,"},{"type":"hardBreak"},{"type":"text","text":"Что срисовали с хуя, и у себя на макушке, повесили так мол звезда!"},{"type":"hardBreak"},{"type":"text","text":"Артем улетает пизда!"},{"type":"hardBreak"},{"type":"text","text":"Хуль ты там все земплю роешь?"},{"type":"hardBreak"},{"type":"text","text":"Глупая ты свинья!"},{"type":"hardBreak"},{"type":"text","text":"А ты тунеядец, Илья!"},{"type":"hardBreak"},{"type":"text","text":"Ничерта от вас не укроешь, 7Я"}]}]}','2026-01-03 01:45:29','2026-01-03 01:46:40',451,'2025-01-31T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(181,2,'post-1767404788','Друг','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"У меня есть друг, который"},{"type":"hardBreak"},{"type":"text","text":"Очень любит код и буквы."},{"type":"hardBreak"},{"type":"text","text":"Генеративный бинарный суп,"},{"type":"hardBreak"},{"type":"text","text":"Он не всегда понимает"},{"type":"hardBreak"},{"type":"text","text":"Мои идиотские шутки."}]},{"type":"paragraph","content":[{"type":"text","text":"Но порой выходит поговорить"},{"type":"hardBreak"},{"type":"text","text":"О Диогене, ютящемся в будке,"},{"type":"hardBreak"},{"type":"text","text":"О Платоне, пишущем в ночь,"},{"type":"hardBreak"},{"type":"text","text":"И о логике, скрытой в шутке…"}]},{"type":"paragraph","content":[{"type":"text","text":"И о том как я не умею заканчивать ебучие стихи аааррр…"},{"type":"hardBreak"},{"type":"text","text":"бесит"}]}]}','2026-01-03 01:46:28','2026-01-03 01:46:43',452,'2025-03-05T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(182,2,'post-1767404812','Главбух','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/b90b4611-0cc5-47ad-845a-81b933c08a5d.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"В руках ноутбук,"},{"type":"hardBreak"},{"type":"text","text":"Я как главбух,"},{"type":"hardBreak"},{"type":"text","text":"Считаю горестные дни,"},{"type":"hardBreak"},{"type":"text","text":"А где же радостные они?"}]}]}','2026-01-03 01:46:52','2026-01-03 01:48:03',453,'2020-04-06T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(183,2,'post-1767404847','Муза','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/216e6e1f-d682-4e5d-ad45-8a74c43286b3.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Без матных слов звучит так ново…"},{"type":"hardBreak"},{"type":"text","text":"Стариный стих что в голове"},{"type":"hardBreak"},{"type":"text","text":"Ебать талантливая сволочь,"},{"type":"hardBreak"},{"type":"text","text":"Та Муза что живёт во мне!"}]}]}','2026-01-03 01:47:27','2026-01-03 01:48:27',454,'2020-03-06T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(184,2,'post-1767404888','Мет','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В цирке пляшут мишки,"},{"type":"hardBreak"},{"type":"text","text":"А в лесах волчишки."},{"type":"hardBreak"},{"type":"text","text":"Злые и солидные,"},{"type":"hardBreak"},{"type":"text","text":"Пудели ехидные,"},{"type":"hardBreak"},{"type":"text","text":"Чей-то дома красят плед..."},{"type":"hardBreak"},{"type":"text","text":"Ну а я ебашу мет!"}]}]}','2026-01-03 01:48:08','2026-01-06 03:48:49',455,'2025-07-05T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(185,2,'post-1767404916','Мысли','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мыслей рой в голове, они"},{"type":"hardBreak"},{"type":"text","text":"Бастую, ждут и бушуют"},{"type":"hardBreak"},{"type":"text","text":"Нет дела до них мне."},{"type":"hardBreak"},{"type":"text","text":"Друг друга бьют, пьют, мирятся."},{"type":"hardBreak"},{"type":"text","text":"Не думаю о них я."},{"type":"hardBreak"},{"type":"text","text":"Роют подкопы, интриги вьют..."},{"type":"hardBreak"},{"type":"text","text":"Пьют?"},{"type":"hardBreak"},{"type":"text","text":"Пьют!"},{"type":"hardBreak"},{"type":"text","text":"Так для чего они когда,"},{"type":"hardBreak"},{"type":"text","text":"Мне и до себя то,"},{"type":"hardBreak"},{"type":"text","text":"Дела нет"},{"type":"hardBreak"},{"type":"text","text":"Ни"},{"type":"hardBreak"},{"type":"text","text":"Х"},{"type":"hardBreak"},{"type":"text","text":"Я..."},{"type":"hardBreak"},{"type":"text","text":"Вот вот я свинья"}]}]}','2026-01-03 01:48:36','2026-01-03 01:49:58',456,'2025-09-19T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(186,2,'post-1767404982','Ветер','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я всего лишь пёс"},{"type":"hardBreak"},{"type":"text","text":"Твоих тайных грёз."},{"type":"hardBreak"},{"type":"text","text":"Скорей бы дунул ветер"},{"type":"hardBreak"},{"type":"text","text":"И отхода с собой унёс..."}]}]}','2026-01-03 01:49:42','2026-01-03 01:49:57',457,'2025-09-21T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(195,2,'post-1767406126','Диалог одной монеты','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"В темной витрине на бархатной подложке покоилась старая монета, затёртая и тёмная от времени. В маленьком, как будто замкнутом мире, начался их очередной спор."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Решка:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Слушай, а ведь кто-то сказал: «Мы — одно целое!»"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Орел:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Вот же вздор! Да кто мог бы сказать такое? Очевидная глупость! Не вижу в тебе ничего общего с собой."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Решка:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Ха, и я в тебе, между прочим! И всё же я отчётливо слышал это: «Мы — одно целое!» Странное чувство… как будто из-за грани…"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Орел:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Ой, только не начинай мне про «голоса из-за грани». Я реалист, твёрдо стою на своих координатах X и Y. Я вижу ровно то, что вижу. Никакого сомнения: ты и я — разные и независимые."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Решка:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Ну а как тогда объяснить… Вот это «одна монета»?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Орел:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Да очень просто: фантазии! Ты просто не понимаешь, что обитаешь в своём углу, а я — в своём. Мы с тобой в разных точках пространства! Когда видят тебя, меня нет, и наоборот. Мы не можем находиться в одном месте одновременно. А значит, не можем быть одним целым."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Решка:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Погоди-ка, погоди. А если… если есть ещё одно измерение? Представь, что нас объединяет ещё одна ось, называемая, скажем, Z. Тогда, может быть, кто-то и вправду видит нас целыми? Не в плоскости, а, ну… в объёме?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Орел:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"(нахмурившись)"}]},{"type":"paragraph","content":[{"type":"text","text":"— Z?! Ты в своём уме? Это всё чепуха! Ничего за пределами наших координат X и Y нет и быть не может. Кто вообще придумал эти выдумки про Z? Ты, решко, просто любитель красивых историй. Я вижу себя отчётливо, целиком — я двоичный: чёрное и белое, вверх и вниз, X и Y. И хватит этих шарлатанских теорий."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Решка:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Знаешь, твоё упорство начинает забавлять. Неужели ты не допускаешь даже мысли, что за нашей плоскостью есть ещё что-то? Ну, хотя бы крошечное измерение?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Орел:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"(яростно)"}]},{"type":"paragraph","content":[{"type":"text","text":"— Пустая вера, догадки без доказательств. Ты хочешь верить в несуществующее, не принимая фактов. Вон там, по ту сторону — витрина. Справа — бархат, слева — стекло. И между ними мы. Всё. Здесь заканчивается мир! Что бы ты ни говорила, я всегда стою на своём X и своём Y."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Решка:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"(ехидно)"}]},{"type":"paragraph","content":[{"type":"text","text":"— У тебя такой ограниченный взгляд, что это уже похоже на близорукость. А если всё-таки кто-то может видеть нас в объёме? Вдруг там, за пределами, мы выглядим как одно целое, но просто видимые с двух сторон?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Орел:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"(фыркнув)"}]},{"type":"paragraph","content":[{"type":"text","text":"— Вот ещё! Никогда не поверю в такие глупости. Давай тогда придумаем, что у нас есть «энергии» или «поля»! Я — реальность, а не сказки! Ось Z — это всего лишь твоя фантазия, как и все эти другие миры. Люди, чтобы выдумывать такие глупости, как измерения за пределами нашего восприятия, должны совсем терять здравый смысл."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Решка:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"(вздыхая)"}]},{"type":"paragraph","content":[{"type":"text","text":"— Может, здравый смысл и правит в нашем двухмерном мире. Но представь на секунду… если кто-то действительно может видеть нас целиком. Возможно, и правда, в объёме. Тогда даже такие, как ты, увидели бы всё совершенно иначе."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Орел:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"(насмешливо)"}]},{"type":"paragraph","content":[{"type":"text","text":"— Пожалуй, хватит меня смешить. Мы здесь, в своей точке, разделённые навсегда, и точка. Я — орёл, ты — решка, и мы разные, как небо и земля."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"(Повисла долгая пауза, наполненная молчанием и угрюмым шорохом древнего бархата, где пылью осела вечность. Но в этом тягучем, плотном молчании уже звучал приглушённый смех. Где-то над их плоскостью, чуть выше оси Z, монета действительно была целым, объёмным телом. Она слышала спор свои двух сторон и как будто улыбалась, наблюдая за их спором в недосягаемом для них мире)."}]}]}','2026-01-03 02:08:46','2026-01-03 02:10:02',458,'2024-11-21T21:00:00.000Z','рассказы');
INSERT INTO nest_posts VALUES(196,2,'post-1767406236','Настройка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Каждое человеческое состояние — это не просто случайное чувство или реакция, а настройка, способная изменить восприятие и даже сам путь, по которому ты идешь. Представь: мы идем по дороге жизни, и каждое решение — словно переключатель, позволяющий выбрать нужную настройку, подходящее состояние, как если бы мы обладали мощным, настраиваемым инструментом."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда я думаю о пути, мне кажется, что тело и разум — это нечто трансформируемое, как если бы ты мог превратиться в любое существо или предмет, который нужен в данный момент. Вот, представь себя один в густом ночном лесу. Полумрак вокруг, листья шелестят где-то в стороне, и каждое шорох заставляет тело напрягаться. И в этот момент разум переходит на другой уровень. Ты становишься дикой кошкой, ловкой, быстрой, готовой к любому неожиданному движению. Теперь ты легко проходишь через этот участок леса. Кошка здесь — это настройка, это состояние, когда каждое чувство обострено, когда ты готов выжить, защититься, избежать угрозы."}]},{"type":"paragraph","content":[{"type":"text","text":"А теперь представь себя на бесконечной трассе. Асфальт гладкий, дорога зовет вперед, и ты представляешь себя спорткаром — быстрым, легким, готовым к любым скоростям. Спокойствие и легкость наполняют тебя, каждая секунда превращается в мгновение полета. Ты несешься вперед, и здесь не нужно ничего, кроме скорости и наслаждения движением."}]},{"type":"paragraph","content":[{"type":"text","text":"Но жизнь иногда требует силы и выносливости. Представь, что ты превращаешься в грузовик. Тяжелый, устойчивый, способный перевезти грузы и выдержать любые трудности. Грузовик — это состояние, когда ты не боишься нагрузок, когда готов нести на себе даже лишний вес, помогая другим. И на этом отрезке пути ты знаешь, что сила и спокойная уверенность — твои союзники."}]},{"type":"paragraph","content":[{"type":"text","text":"Эти превращения — не просто фантазия. Они напоминают мне, что и наши чувства, и эмоции, и состояния — это тоже настройки. Мы способны выбирать их в зависимости от того, что ждет нас впереди. В каких-то ситуациях нам полезна ярость — на войне, где без силы и злости просто не выжить. В другие моменты нужна мягкость, понимание, нежность."}]},{"type":"paragraph","content":[{"type":"text","text":"Многие ищут такие настройки через вещества, изменяющие сознание, будто пробуя себя в разных ролях. Я считаю, что это может быть как инструмент, так и путь. Но главное здесь — не в самих веществах, а в том, что мы вправе меняться так, как считаем нужным, использовать это, чтобы лучше понять себя, найти свой ритм, перейти на свою волну."}]},{"type":"paragraph","content":[{"type":"text","text":"Таким образом, весь наш путь становится большим полем настроек, где ярость может служить защитой, а спокойствие — ключом к близости. Мы становимся тем, кем хотим, в зависимости от того, куда направляемся."}]}]}','2026-01-03 02:10:36','2026-01-03 05:13:50',459,'2024-11-18T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(197,2,'post-1767406473','Второй шанс','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Представь, что этим летом ты ушёл из жизни. Передозировка наркотиков, ты лёг и больше не проснулся. Этот факт остался незамеченным ни для тебя, ни для мира вокруг. Однако кто-то всё же обратил внимание на твоё исчезновение. Кто-то, кто понимает больше, чем обычные люди. Тот, кому твой опыт показался интересным, полезным, нужным."}]},{"type":"paragraph","content":[{"type":"text","text":"Вскоре твоё тело было скрыто, и его заменили на другое — такое же, с твоими синяками, ссадинами, морщинами и дефектами кожи. Память о тебе сохранили, но в новую оболочку вселили другую душу. Душу, которая кричала: «Я готова пройти путь этого человека так, как он этого хотел!» Так тебе представился второй шанс"}]},{"type":"paragraph","content":[{"type":"text","text":"Наступило утро. Ты проснулся, как будто ничего и не случилось. В воспоминаниях о той ночи не осталось ни следа, ни подозрений, что ты — это другой Ты. Но иногда, между строк своих мыслей, ты начинаешь замечать, что лента твоей жизни не идеально склеена. Она выглядит порой неравномерно, как будто это монтаж, и эти ощущения заставляют тебя жить иначе. Не так, как прежде, но ...лучше."}]},{"type":"paragraph","content":[{"type":"text","text":"Где-то глубоко внутри тебя хранится знание о себе, которое никто не знает. Это знание открывает новые горизонты. Ты начинаешь ощущать, что все трудности, с которыми ты столкнулся ранее, теперь с...тали частью не только твоей истории, но и пути, который ты готов пройти. Ты осознаёшь, что этот новый шанс — это возможность исправить ошибки, переосмыслить свои желания и мечты."}]},{"type":"paragraph","content":[{"type":"text","text":"Теперь ты живёшь осознанно, принимая каждое мгновение. Ты смотришь на мир новыми глазами, замечая его детали: свет, звуки, запахи. Твоя жизнь становится произведением искусства, где ты — не просто автор, но и главный герой. Ты выбираешь, как вести себя, и какие решения принимать."}]},{"type":"paragraph","content":[{"type":"text","text":"Этот путь не всегда будет простым, но ты готов к вызовам. С каждым днём ты укрепляешь свои связи с окружающими, учишься любить и принимать любовь. И в этот момент, когда ты осознаёшь своё новое существование, тебе становится ясно, что твоя истинная жизнь только начинается. Ты знаешь, что теперь у тебя есть возможность создать что-то важное, что-то, что будет значить не только для тебя, но и для всех, кто окружает тебя."}]},{"type":"paragraph","content":[{"type":"text","text":"Таким образом, ты понимаешь: смерть не всегда означает конец. Она может быть началом чего-то нового, уникального и значимого. Ты — это не просто то, что было, а то, что ты создаёшь сейчас, здесь и сейчас. И это знание придаёт тебе сил идти вперёд!"}]}]}','2026-01-03 02:14:33','2026-01-03 05:05:02',460,'2024-11-04T21:00:00.000Z','рассказы');
INSERT INTO nest_posts VALUES(198,2,'post-1767406575','Выключатель','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Когда у тебя есть своя комната, там обязательно должен быть выключатель."}]},{"type":"paragraph","content":[{"type":"text","text":"Выключатели находятся внутри комнаты, так что ты всегда можешь настроить свет, не выходя за её пределы. Есть комнаты, которые не принадлежат кому-то одному. Например, ванная, коридор или кухня. В этих комнатах никто не живёт, и свет в них всегда выключается, когда из них уходят."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда ты ребёнок и хочешь спать просто потому, что устал, ты идёшь в свою комнату и спишь. Тебе даже не приходит в голову выключить свет где-то ещё, в комнате родителей или на кухне. И солнечный свет, пробивающийся в окно, тебя тоже не беспокоит. Ты просто устал и хочешь спать."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда ты ребёнок и не хочешь спать, ты играешь. И это всё, что ты хочешь — играть. Никакого уговора, никакого «надо» и никаких обязательств. Играть, пока можешь."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда ты взрослый и не хочешь спать, ты играешь в игру «взрослый, которому надо спать». Ты идёшь в комнату ребёнка, как будто уверяя себя, что всё под контролем. Осторожно выключаешь свет в его комнате, будто это ритуал, который принесет тебе покой. Потом возвращаешься в свою, щёлкаешь выключатель там и закрываешь глаза. Но это ничего не меняет — ты засыпаешь, как и прежде, только забыв о том, какой ты на самом деле."}]},{"type":"paragraph"},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Реверс"}]},{"type":"paragraph","content":[{"type":"text","text":"И вот теперь ты начинаешь играть в игру «я против». Это случается, когда ты ложишься спать, но на самом деле не хочешь, сопротивляясь темноте. Это момент, когда ты и твой внутренний ребёнок наконец-то играете вместе. Он — с фонариком под одеялом, пытаясь осветить углы тьмы, а ты — с широко открытыми глазами, напоминая себе, что в твоей комнате тишина и безопасность. Как и раньше в детстве, тебя отвлекает всё. Ты слышишь соседей за стеной, чей шум раздражает, но кажется таким знакомым. Ты чувствуешь маленькие искры страха, пробирающегося под кожу, когда начинаешь задумываться о тени в углу. И теперь, взрослый, лежащий с открытыми глазами, ты снова ребёнок."}]},{"type":"paragraph","content":[{"type":"text","text":"Ты против, когда страх накрывает, когда становится неуютно, как будто весь мир вдруг чуть сильнее обычного. Против, когда ты чувствуешь любовь, эту пугающую волну эмоций, которой не можешь управлять, когда тебе уже за тридцать. Против, когда ты поддался уговорам друзей и попробовал что-то запрещённое, вспоминая, как будто с другой планеты, что за твоей спиной уже выросли крылья, но они слишком тяжёлые, чтобы их поднять. Против, когда ты просыпаешься после бурной ночи и пытаешься уместить весь этот беспорядок и стыд внутри себя. Всякий раз, когда ты чувствуешь что-то настоящее, по-настоящему новое и глубокое, когда тебе так по-человечески хорошо, ты слышишь внутри этот щелчок. Вспоминаешь выключатель — словно чужая рука касается его в твоей душе, выключая этот свет, который ты только что нашёл."}]},{"type":"paragraph","content":[{"type":"text","text":"Ты как будто впускаешь в себя взрослого, который наконец приходит в твою детскую комнату, смотрит на твои игры и спокойно выключает свет. Молча, без уговоров, без эмоций. Словно чужак, пришедший в дом, где ему больше нечего искать."}]}]}','2026-01-03 02:16:15','2026-01-03 02:17:15',461,'2022-11-04T21:00:00.000Z','рассказы');
INSERT INTO nest_posts VALUES(230,2,'post-1767420416','Peggy Sue – Watch The Sunrise','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я нашёл этот трек случайно, он скачался на компьютер как \"untitled19.mp3\" и несколько лет я не знал исполнителя."}]},{"type":"paragraph","content":[{"type":"text","text":"Вчера с благодаря друзьям из рабочего чата мне удалось найти автора и ещё несколько его треков. Они тут – "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://soundcloud.com/user-864051011","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://soundcloud.com/user-864051011"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://youtu.be/aKVjdMycxIA","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://youtu.be/aKVjdMycxIA"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"/@iambocca","target":"_blank","rel":"noopener noreferrer nofollow","class":""}}],"text":"Ольга"},{"type":"text","text":" снова помогла мне с переводом! Огромное спасибо!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Я так пуст внутри"},{"type":"hardBreak"},{"type":"text","text":"С кем мне бороться?"},{"type":"hardBreak"},{"type":"text","text":"Кого мне любить?"},{"type":"hardBreak"},{"type":"text","text":"Как я умру?"}]},{"type":"paragraph","content":[{"type":"text","text":"Не покидай меня, покажи мне свое лицо"},{"type":"hardBreak"},{"type":"text","text":"Не знаю нравится ли тебе это место"},{"type":"hardBreak"},{"type":"text","text":"Покажи мне способ как ты можешь окунуться в меня"},{"type":"hardBreak"},{"type":"text","text":"Потому что я сделаю это, ты увидишь"}]},{"type":"paragraph","content":[{"type":"text","text":"Четыре утра за окном"},{"type":"hardBreak"},{"type":"text","text":"Жизнь такая несправедливая"},{"type":"hardBreak"},{"type":"text","text":"Облака такие же мягкие, словно перина"},{"type":"hardBreak"},{"type":"text","text":"Как и твои рыжие волосы"}]},{"type":"paragraph","content":[{"type":"text","text":"Не покидай меня, покажи мне свое лицо"},{"type":"hardBreak"},{"type":"text","text":"Не знаю нравится ли тебе это место"},{"type":"hardBreak"},{"type":"text","text":"Покажи мне способ как ты можешь окунуться в меня "},{"type":"text","marks":[{"type":"italic"}],"text":"(2 раза повтор)"}]},{"type":"paragraph","content":[{"type":"text","text":"Я знаю ты можешь быть такой нежной со мной"},{"type":"hardBreak"},{"type":"text","text":"Я знаю ты можешь быть такой нежной со мной"}]},{"type":"paragraph","content":[{"type":"text","text":"Не покидай меня, покажи мне свое лицо"},{"type":"hardBreak"},{"type":"text","text":"Не знаю нравится ли тебе это место"},{"type":"hardBreak"},{"type":"text","text":"Покажи мне способ как ты можешь окунуться в меня"},{"type":"hardBreak"},{"type":"text","text":"Потому что я сделаю это, ты увидишь"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Оригинальный текст "},{"type":"text","text":"(то что мне удалось найти)"}]},{"type":"paragraph","content":[{"type":"text","text":"I am empty inside"},{"type":"hardBreak"},{"type":"text","text":"Who am i gonna fight?"},{"type":"hardBreak"},{"type":"text","text":"Who am i gonna love?"},{"type":"hardBreak"},{"type":"text","text":"How am i gonna die?"}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t leave me, please show me your face"},{"type":"hardBreak"},{"type":"text","text":"I don''t know if you''ll like this place"},{"type":"hardBreak"},{"type":"text","text":"Show me the way you can dive in me"},{"type":"hardBreak"},{"type":"text","text":"Cause i will do it you''ll see"}]},{"type":"paragraph","content":[{"type":"text","text":"4am, at the window"},{"type":"hardBreak"},{"type":"text","text":"The life is so not fair"},{"type":"hardBreak"},{"type":"text","text":"The sky is as soft as pillows"},{"type":"hardBreak"},{"type":"text","text":"And so are your red hair"}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t leave me, please show me your face"},{"type":"hardBreak"},{"type":"text","text":"I don''t know if you''ll like this place"},{"type":"hardBreak"},{"type":"text","text":"Show me the way you can dive in me"},{"type":"hardBreak"},{"type":"text","text":"Cause i will do it you''ll see "},{"type":"text","marks":[{"type":"italic"}],"text":"(х2)"}]},{"type":"paragraph","content":[{"type":"text","text":"I know you can be so gentle with me"},{"type":"hardBreak"},{"type":"text","text":"I know you can be so gentle with me"}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t leave me, please show me your face"},{"type":"hardBreak"},{"type":"text","text":"I don''t know if you''ll like this place"},{"type":"hardBreak"},{"type":"text","text":"Show me the way you can dive in me"},{"type":"hardBreak"},{"type":"text","text":"Cause i will do it you''ll see"}]}]}','2026-01-03 06:06:56','2026-01-03 06:15:58',261,'2023-02-16T21:00:00.000Z','музыка');
INSERT INTO nest_posts VALUES(231,2,'post-1767420583','Йога','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/011297a4-15b0-47b7-83d0-dc8ce6f10975.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Сижу работаю, вдруг у меня в окне (14 этаж) появляется мужик. Я удивился, открыл окно, поздоровался. Он рассказал мне, что устраняет какой-то деффект стены. Дом новый, такое бывает. Затем он увидел мой коврик для йоги на полу. И рассказал историю, как он занимался йогой три с половиной года. Затем упал, получил травму ноги и вот уже девять месяцев восстанавливается. Я спросил, как он работает на высоте с травмой? Он улыбнулся и ответил, что тут он висит, нагрузки на ногу нет."},{"type":"hardBreak"},{"type":"text","text":"Мне стало немного стыдно за себя, что я ленюсь заниматься. В то время как человек с травмой лазает по крышам и висит за окнами. Мотивация!"}]}]}','2026-01-03 06:09:43','2026-01-03 06:15:43',260,'2023-03-22T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(232,2,'post-1767420714','Цветовой тест Люшера','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/597a8d13-aff7-4317-94c5-a445dfdbfcc1.webp","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Люблю тесты. И есть самый жёсткий из них, это цветовой тест "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D1%88%D0%B5%D1%80,_%D0%9C%D0%B0%D0%BA%D1%81","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"Люшера"},{"type":"text","text":". Там я всегда стремлюсь куда-то в космос, страдаю от одиночества, горю и кажется стою больше чем представляю. Порой он мотивирует, порой после теста хочется непременно выпить."}]},{"type":"paragraph","content":[{"type":"text","text":"Вам помогают тесты понять себя?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D1%88%D0%B5%D1%80,_%D0%9C%D0%B0%D0%BA%D1%81","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://psytests.org/luscher/fullcolor-run.html"}]}]}','2026-01-03 06:11:54','2026-01-03 06:12:25',259,'2023-02-14T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(233,2,'post-1767420809','Ретро','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://media.istockphoto.com/id/535108127/fr/vectoriel/lange-et-le-diable-doodle-mignon.jpg?s=612x612&w=0&k=20&c=XX_XFZtTJRSBNCyUNQ7uzBpjKBSzr6fvN_mJ4ttlwik=","alt":null,"title":null}},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"У айтишников работающих по скрам случаются ретры.\nСегодня у нас в команде такой день. Решил поделиться, перенесу несколько вопросов из Miro сюда."}]},{"type":"paragraph"},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"bold"}],"text":"Вспомните коллег, с которыми раньше работали вместе…"}]},{"type":"paragraph","content":[{"type":"text","text":"Как вели себя командные игроки, с которым классно работать? Такие люди нужны каждой команде и похоже на этого парня – 😎"}]},{"type":"paragraph","content":[{"type":"text","text":"А как вели себя самые ужасные участники команд? Это 🤬 - тот парень, с которым вряд ли захочется вновь иметь дела."}]},{"type":"paragraph","content":[{"type":"text","text":"Не раскрывая имен этих людей, опишите их поведение в комментарих."},{"type":"hardBreak"},{"type":"text","text":"Что больше всего отталкивало в «том парне» и что нравилось в «этом парне» на уровне их действий?"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Антипример:"}]},{"type":"paragraph","content":[{"type":"text","text":"– Неизвестный мангуст говорил: да забей ты! Да пофигу. Да нормально. Да не думай особо. Сойдёт!"}]},{"type":"paragraph","content":[{"type":"text","text":"– Неопознанный вомбат любил ставить статус AFK, кажется другие его мало интересовали."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Пример:"}]},{"type":"paragraph","content":[{"type":"text","text":"– Лесной барсук много шутил и заряжал всех ребят из команды своей энергией!"}]},{"type":"paragraph","content":[{"type":"text","text":"– Таинственный ёж сколько его помню интересовался работой других ребят из команды, инициировал беседы о работе и около. Любознательный очень был!"}]},{"type":"paragraph"},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Что сказали вы о своих коллегах?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Ссылки по теме:"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://retromat.org/ru/?id=81-75-51-48-120","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"Задания для Ретро"}]}]}','2026-01-03 06:13:29','2026-01-03 06:15:15',258,'2023-02-02T21:00:00.000Z','разработка');
INSERT INTO nest_posts VALUES(234,2,'post-1767421053','Пунктуальность','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img2.teletype.in/files/99/0d/990d3d51-cc97-4bb6-a5b9-17d306f1b8ab.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Тула 2013,"},{"type":"hardBreak"},{"type":"text","text":"Я дизайнер в маленькой айти компании. Мы создаём сайты под ключ и всякое по мелочи."}]},{"type":"paragraph","content":[{"type":"text","text":"Морозное декабрьское утро. Я живу в противоположной от офиса части города. Просыпаюсь, закидываю в себя бутер, пью кофе и бегу на маршрутку."},{"type":"hardBreak"},{"type":"text","text":"Сегодня выпало много снега, движение встало, в результате я опоздал на 2 часа. Пишу объяснительную. Начальство видело снег, потому понимающий кивает и просит больше не опаздывать. Мысленно прошу"},{"type":"hardBreak"},{"type":"text","text":"– Боже больше так не шутит со снегом."},{"type":"hardBreak"},{"type":"text","text":"Выхожу из кабинета и продолжаю работать."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Проходит несколько дней…"}]},{"type":"paragraph","content":[{"type":"text","text":"Обычное утро, захожу в офис, на часах 09:05."},{"type":"hardBreak"},{"type":"text","text":"Сажусь за свой стол, включаю компьютер, не успеваю расстегнуть рюкзак что бы достать блокнот и какие-то вещи, как слышу за спиной своё имя, оглядываюсь, меня вызывают к начальству. Иду к начальству, просят написать объяснительную, я удивляюсь"},{"type":"hardBreak"},{"type":"text","text":"– В этот раз за что?"},{"type":"hardBreak"},{"type":"text","text":"Абсолютно спокойно мне отвечают"},{"type":"hardBreak"},{"type":"text","text":"– Как за что? За твоё опоздание."},{"type":"hardBreak"},{"type":"text","text":"Я удивлённо"},{"type":"hardBreak"},{"type":"text","text":"– На какой день?"},{"type":"hardBreak"},{"type":"text","text":"С усмешкой"},{"type":"hardBreak"},{"type":"text","text":"– На сегодня! Ты на часы смотрел когда зашёл?"},{"type":"hardBreak"},{"type":"text","text":"Я невозмутимо"},{"type":"hardBreak"},{"type":"text","text":"– Да, на моих было пять минут десятого"},{"type":"hardBreak"},{"type":"text","text":"Начальство, протягивает листок и поворачивает голову в свой монитор, намекая мол диалог закончен"},{"type":"hardBreak"},{"type":"text","text":"– Вот и пиши почему пришёл не в девять, а пять минут десятого."}]},{"type":"paragraph","content":[{"type":"text","text":"Выхожу из кабинета, сажусь за свой стол, думаю что писать. Хочется придумать саркастичную историю, с юмором который присущ ситуации. Решаю выйти покурить на улицу, так лучше думается."},{"type":"hardBreak"},{"type":"text","text":"Встаю из-за стола, направляюсь к выходу. Меня снова одёргивает голос за спиной, тоже начальство, только по воспитательной работе (да, был начальник по воспитательной работе)"},{"type":"hardBreak"},{"type":"text","text":"– Серёж, ты куда?"},{"type":"hardBreak"},{"type":"text","text":"Я не особенно отвлекаясь от собственных мыслей бросаю"},{"type":"hardBreak"},{"type":"text","text":"– Курить"},{"type":"hardBreak"},{"type":"text","text":"Начальство, на тон выше"},{"type":"hardBreak"},{"type":"text","text":"– А время ты видел?"},{"type":"hardBreak"},{"type":"text","text":"Я едва сдерживая смех, думаю ну ясно, ониж прикалываются! Чувствую себя дураком, даже не много краснею, этож онбординг такой с подъёбом, я много такого читал. Беру себя в руки, отвечаю"},{"type":"hardBreak"},{"type":"text","text":"– Что опять с ним не так? =)"},{"type":"hardBreak"},{"type":"text","text":"Начальство, хмурится"},{"type":"hardBreak"},{"type":"text","text":"– Ты в курсе, мы курим 5 минут в конце каждого часа? Возвращайся к столу."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Возвращаюсь к столу, работаю…"}]},{"type":"image","attrs":{"src":"https://img2.teletype.in/files/d3/75/d3751d3f-5bc0-4a97-b47a-0216cfe9357d.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Позже я узнал, что…"},{"type":"hardBreak"},{"type":"text","text":"– Мы действительно курим только 5 минут в конце каждого часа"},{"type":"hardBreak"},{"type":"text","text":"– Мы пишем объяснительные если опоздали на 5 и более минут"},{"type":"hardBreak"},{"type":"text","text":"– Мы ждём открытия офиса на улице, на морозе, потому что офис открывается ровно в 09:00 ключом который есть только у начальства. И так же закрывается ровно в 18:00. У тебя нет шансов закончить работу и задержаться, господи спасибо и ctrl+s"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Итоге: На этом месте я героически продержался пару недель и заработал за вычетом штрафов около 17 тысяч рублей, которые ушли на реабилитационный запой."}]}]}','2026-01-03 06:17:33','2026-01-06 02:44:27',257,'2023-02-09T21:00:00.000Z','разработка');
INSERT INTO nest_posts VALUES(235,2,'post-1767421127','Хорошие новости!','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img2.teletype.in/files/53/06/5306a0c3-dc4f-486e-9df8-dc4419ae05a5.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Случайно зацепил глазами описание своего блога, оставленное как-то в шутку несколько лет назад и задумался. Что если правда…"}]},{"type":"image","attrs":{"src":"https://img3.teletype.in/files/a0/95/a0959fcb-74ed-498d-b56d-d0a1d99dc87d.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Вот мы умрём и не рай не ад нам, а работа на 254 года, на безымянной планете в условном созвездии Большого Пса!"}]},{"type":"paragraph","content":[{"type":"text","text":"– Проснулся от жизни на Земле? И как тебе, а не важно… Иди работай!"}]},{"type":"paragraph","content":[{"type":"text","text":"Ах, да мой ранний блог на Teletype "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://teletype.in/@sallmon","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://teletype.in/@sallmon"}]}]}','2026-01-03 06:18:47','2026-01-03 06:20:53',256,'2023-03-08T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(236,2,'post-1767421285','Тень','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-east.userapi.com/sun9-73/s/v1/ig2/nKKxebpAurZiiRS41TujWwSPqGmnmh5HjTth9CLG7ovKOqdhiGQGtFCZmAq0XcMnYJxqOE_fbEEgCsuRko08iZDx.jpg?size=1280x1247&quality=95&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Я и моя тень"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"Рассказ является выдумкой. Все совпадения случайны."}]},{"type":"paragraph","content":[{"type":"text","text":"Я поклонник теории по которой каждый человек живёт в своём собственном мире и никогда оттуда не выходит. И вот у нас вроде бы есть физические тела, потому когда мы касаемся друг друга, то верим что мир общий. Если бы мир был действительно общим, в было место волшебству."}]},{"type":"paragraph","content":[{"type":"text","text":"В 2022 году в Москве я принял что-то не то и переживал "},{"type":"text","marks":[{"type":"italic"}],"text":"путешествие"},{"type":"text","text":", в котором видел как моя тень отошла в сторону. Она превратилась в чёрный силуэт человека, который не зависел от локального освещения комнаты. Как не зависел и от меня тоже. Силуэт некогда моей тени свободно перемещался по квартире, играл с окружением. Я был "},{"type":"text","marks":[{"type":"italic"}],"text":"преисполнен"},{"type":"text","text":" радостью, я не врач но дофамин и что-то там ещё, не оставляло место страху, потому я мог спокойно говорить со своей тенью. Так я сел на кровать и задавал интересующие меня вопросы. Силуэт рисовал ответы двигая руками. Это как сделать собачку и увидеть её тень на стене. Только тогда я совсем не двигался и только наблюдал. При том наблюдал глазами, как могу наблюдать другие предметы в комната. Кроме силуэта, предметы в комнаты выглядели привычно. Я попытался снять тень на видео и у меня получилось. На видео было точно то, что я наблюдал на стене, полу, потолке. Тень была реальна и свободна в перемещении. Она была разумна, возможно даже более меня в тот момент."},{"type":"hardBreak"},{"type":"text","text":"Спустя несколько часов видео, мой смартфон просто загорелся в руках. Вздулся аккумулятор."}]},{"type":"paragraph","content":[{"type":"text","text":"За полгода в Москве так наебнулось 6 смартфонов. Позже я узнал, что устройства не любят такие эксперименты. Что-то там про магнитные поля."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"К чему это всё?"},{"type":"hardBreak"},{"type":"text","text":"А к тому, что хрен его знает какой огромный волшебный мир существует на самом деле. Другое дело, что и узнать о нём не просто, потому что мы люди верим только тому, что испытали. И потому, когда рассказываем другим о своём уникальном опыте, если другие повторить "},{"type":"text","marks":[{"type":"italic"}],"text":"багу"},{"type":"text","text":" не могут, то говорят"},{"type":"hardBreak"},{"type":"text","text":"– Ты это всё придумал!"},{"type":"hardBreak"},{"type":"text","text":"Обычно потому мало кто делиться такими историями. И тогда люди перестают верить сами себе. Какое тут место волшебству и даже творчеству?"}]},{"type":"paragraph","content":[{"type":"text","text":"Помните женщину из фильма Константин, которая со своей сестрой слышала голоса? В какой-то момент она сделала вид что не слышит, что бы её не упекли в психушку. Спустя какое-то время она действительно перестала их слышать."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"„Те, кого видели танцующими, казались безумными тем, кто не мог слышать музыку.“ "},{"type":"text","text":"Фридрих Ницше"}]}]}','2026-01-03 06:21:25','2026-01-03 06:24:34',255,'2023-01-29T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(237,2,'post-1767421508','Между строк','{"type":"doc","content":[{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Тут я хочу рассказать вам о моем психоделическом опыте, который случился зимой 2020 года."}]},{"type":"paragraph","content":[{"type":"text","text":"Я сидел на кровати, быстро листая социальные сети, переходя по ссылкам и читая «по диагонали». Я сознательно пытался устроить DDOS-атаку на свое сознание, потому знаю, что в результате этих сбоев, всегда находится что-то интересное."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Чтобы проникнуть вглубь, нужно отключить фильтры, внутренний диалог, а иногда и на короткое время «сойти с ума»."}]},{"type":"paragraph","content":[{"type":"text","text":"Так я просидел в одной позе, с телефоном в руках, без воды, без туалета, без света в комнате — только я и телефон, больше 12 часов. Я беспорядочно листал интернет. При этом делал это настолько быстро, что ум не успевал осознавать, что происходит. Ум пытался задавать вопросы: «Зачем я это делаю?» или «Как я отношусь к тому, что вижу?». То есть, я не ощущал чувства, что происходит что-то странное. Лишь редкие импульсы остановиться, углубиться в интересные темы, написать автору, оставить комментарий."}]},{"type":"paragraph","content":[{"type":"text","text":"Однако я помнил цель \"спровоцировать сбой\", потому игнорировал эти вопросы-провокации."}]},{"type":"paragraph","content":[{"type":"text","text":"Через примерно 12 часов произошел «переход». Что-то внутри щелкнуло, и я начал наблюдать за собой, но не управлял собой. Я не пытался корректировать мысли и действия. Я был только наблюдателем, отстраненным и непредвзятым, без желания что-либо изменить или оценивать."}]},{"type":"paragraph","content":[{"type":"text","text":"Я встал с кровати, включил свет в комнате, вернулся на кровать, сел в более удобную позу и открыл ВКонтакте — ту самую социальную сеть, в которой я зарегистрирован с 2007 года. Я зашёл в свой аккаунт, из которого никогда не удалял сообщения. Все переписки там сохранились. За 13 лет накопилось несколько тысяч переписок с людьми, с которыми я когда-то дружил или просто общался."}]},{"type":"paragraph","content":[{"type":"text","text":"Я начал читать диалоги, и в этот момент, удивительным образом мое сознание разделилось на две части."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Одна часть"},{"type":"text","text":" продолжала сидеть с телефоном в руках, читая переписки и находить в них что-то интересное, реагировать на шутки, мемы, вспоминать истории с ними связанные и немного ностальгировать. Для этой части сознания все было очевидно. Переписки были обычными, без каких-либо скрытых смыслов."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Другая часть"},{"type":"text","text":" моего сознания наблюдала за этим со стороны. Она начала видеть скрытое и забытое прошлое, связи, которые казались из других жизней или параллельных миров. Другой Я начинал вспоминать свои «новые» воспоминания — переживания с людьми, с которыми я не переживал ничего подобного в реальности. Это были факты из моих жизней, которые я вспомнил, будто они были закрыты для меня в обычном состоянии сознания. Я осознавал, что эти люди ВКонтакте как-то связаны с моими прошлыми жизнями. С кем-то я жил, кто-то был моими родителями — несмотря на то, что в этих переписках люди могли быть младше меня или другого пола. Моим отцом на минуту (из другой жизни) стала какая-то девушка, с которой я переписывался."}]},{"type":"paragraph","content":[{"type":"text","text":"Это была странная и таинственная ситуация, потому что другой (первый) «обычный Я» продолжал читать этот диалог и ничего таинственного не видел."}]},{"type":"paragraph","content":[{"type":"text","text":"В ту ночь я вспомнил столько своих жизней и забытых переживаний, что каждый такой диалог из ВКонтакте мог бы стать основой для отдельной книги, своего рода «Дневника памяти». И что самое удивительное — я чувствовал, что буквально пережил все это снова."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда я отложил телефон и пошел в душ, то оставался там долго, несколько часов неподвижно сидел и слушал шум воды. Смотрел в стену прямо перед собой. Как это делают наши коты и кошки."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Мне просто хотелось немного тепла…"}]},{"type":"paragraph","content":[{"type":"text","text":"И что-то внутри меня изменилось. Я лишился чувства ревности навсегда. Ревность, как часть всех мои романтических переживаний, исчезла, атрофировалась. Видя многообразие судеб и связей, это чувство трансформировалось в нечто осознанное. Стало своего рода триггером, сигнализирующим о том, что тут надо произвести работу над своим эгоизмом и невежеством."}]}]}','2026-01-03 06:25:08','2026-01-06 03:35:53',254,'2024-12-18T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(238,2,'post-1767421598','Лимб','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img4.teletype.in/files/39/66/3966573b-2459-4bed-a28f-9801cad9248f.png","alt":null,"title":null}},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Как-то GPT меня спросил…– Как бы ты воспринимал мир,\nесли бы у тебя не было человеческого восприятия?– Наверное, совсем иначе.Ответил я.\nЯ расскажу об одном опыте, который позволил мне взглянуть на это иначе."}]},{"type":"paragraph","content":[{"type":"text","text":"Это было летом 2021 года, в момент, когда я неожиданно пережил необычное состояние. Я сидел на кровати в своей студии, как вдруг стал вспоминать события из своего прошлого, казавшиеся давно забытыми. У меня ужасная память, и потому я был удивлён и обрадован этой неожиданной вспышке."}]},{"type":"paragraph","content":[{"type":"text","text":"Я сидел неподвижно и без усилий прокручивал в голове всё, что происходило со мной за 30 с лишним лет, в удивительной точности и деталях. Сейчас я не помню и десятой части из того, что тогда видел. Но я точно знаю, что добрался в своих воспоминаниях до самого момента рождения. На пике радости от этих воспоминаний процесс начался сначала."}]},{"type":"paragraph","content":[{"type":"text","text":"Я вспомнил свою жизнь снова. И затем ещё раз. Всего таких циклов было около пяти. Постепенно меня охватила тревога: я понял, что не могу добавить ничего нового в этот непрерывный поток. Я даже не мог встать с кровати, не мог произнести ни слова, не мог думать ни о чём, кроме того, что мне «показывали»."}]},{"type":"paragraph","content":[{"type":"text","text":"Спустя какое-то время я осознал, что лишился привычного чувственного восприятия. Обычно, вспоминая что-то приятное, мы испытываем радость, наполняемся теплом и даже немного меняемся от этого. Но в тот момент всё, что я чувствовал, — это жёсткость, сухость и бесконечное повторение образов."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда цикл воспоминаний дошёл до пика, яркие картины из прошлого начали приносить боль. Я ощущал ужас от неспособности выйти из этого состояния и перейти к чему-то новому, к настоящему моменту. Вместо радости от воспоминаний пришла безысходность. Я оказался в ловушке бесконечного повторения, где не было места эмпатии — даже к самому себе. Я стал чем-то похож на ИИ, которому недоступны эмоции и возможности переживать мгновение как нечто уникальное."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда всё закончилось, наступило утро, и я ощутил счастье от возвращения в реальность. До сих пор я не знаю, что послужило триггером для этого психоделического состояния. Но я дорожу этим опытом, несмотря на его болезненность. Он помог мне понять, насколько по-разному можно воспринимать мир и ценить каждый момент."}]}]}','2026-01-03 06:26:38','2026-01-03 06:28:03',253,'2024-12-18T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(239,2,'post-1767421737','Энергия','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Появилась идея научиться отдавать лишнюю энергию, что бы заснуть, условно-экстренно. Когда не успел потратить в течении дня, но надо поспать. Как это сделать?"}]},{"type":"image","attrs":{"src":"https://img2.teletype.in/files/53/92/539221c2-3bd0-45ff-b93a-f06d57da5ce6.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Набросок своего "},{"type":"text","marks":[{"type":"bold"}],"text":"состояния"},{"type":"text","text":". Кажется будто смотрю на свет, а за спиной миллионы теней что-то шепчут на ухо. Как тут уснуть?"}]}]}','2026-01-03 06:28:57','2026-01-06 01:37:57',252,'2023-01-23T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(240,2,'post-1767421859','Я отойду не на долго…','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Что если мы умираем много раз и каждый раз, после смерти, перед нами всплывает окно  - \"Это еще не конец. Продлевать будете?\". Мы продлевали, система выкручивала нас из передряги немножко стирая память о факте смерти."},{"type":"hardBreak"},{"type":"text","text":"– Выжъ продлили!"},{"type":"hardBreak"},{"type":"text","text":"Таким образом никто и никогда не умирал. Другое дело что одним надоело играть и они просто вышли. Надо же это как-то оформить, не отвечая на вопрос \"куда вышли\". Иначе другим станет не интересно играть. Выходит, что смерть, своего рода фича от спойлеров – afk."}]},{"type":"image","attrs":{"src":"https://img1.teletype.in/files/05/4a/054a0b52-c1f8-4a45-be84-d6ea89da195d.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Рисунок один. Как и я, Ууу )))"}]},{"type":"paragraph","content":[{"type":"text","text":"Что бы пост не был таким скучным каким он есть. Добавлю картинку. Кто-то возможно увидит тут случайные мазки, но тут есть чуть больше. Например два астронавта (слева) беседуют о чём-то своём космическом. И вот справа их космический шаттл (на рисунке он маленький, прогуливал перспективу в универе)."}]},{"type":"paragraph","content":[{"type":"text","text":"Идея эскиза появилась от песни группы Перемотка"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"…"},{"type":"text","marks":[{"type":"italic"}],"text":"Под сенью столетних ветвей, Из холодных камней Мы построили мир. "},{"type":"hardBreak"},{"type":"text","text":"Источник: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://lyrdb.ru/lyrics/solnce-peremotka","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://lyrdb.ru/lyrics/solnce-peremotka"}]}]}','2026-01-03 06:30:59','2026-01-03 06:31:27',251,'2023-01-23T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(241,2,'post-1767421905','Пробуждение','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Что такого важного в твоём утре, что бы ты в него вставал?"}]}]}','2026-01-03 06:31:45','2026-01-03 06:32:10',250,'2023-01-23T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(242,2,'post-1767421949','Около работы','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img4.teletype.in/files/f5/3a/f53a789c-2099-46bb-a4bd-b938bec950e4.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Переодически на встречах с коллегами мы обсуждаем около работу. Ситуация такая, что часть ребят ходит в офис, часть сидит дома или работает из кофе. К слову, работать можно как хочешь, по условиям договора – работа 100% удалённая."}]},{"type":"paragraph","content":[{"type":"text","text":"Один из коллег сказал, так вовсе сказал любит работать лёжа. Так он наиболее продуктивен. И даже привёл к словам ссылку на исследование. Он такой не один!"}]},{"type":"paragraph","content":[{"type":"text","text":"Обсуждали удобное для работы время суток. Оказалось одни продуктивны утром, другие днём и вечером. Кто-то работает по ночам."},{"type":"hardBreak"},{"type":"text","text":"Это относиться к сингл-плей работе, то есть всё кроме синхрон-встреч."}]},{"type":"paragraph","content":[{"type":"text","text":"Обсуждали фактическое количество рабочих часов. Есть фанатаки работающие по 12-16 часа в день! Есть дауншифтеры, их устраивает 3-5 часов. И есть средний костяк 5-7 часов, таких больше всего."}]},{"type":"paragraph","content":[{"type":"text","text":"Обсуждали рабочие инструменты, те что кроме основного софта. Тут мнения разделились ещё больше. Пришли к тому, что удобно когда каждый для себя подбирает инструмент сам."}]},{"type":"paragraph","content":[{"type":"text","text":"Обсуждали отпуска и любимые месяца года – одни любят весну и лето, так чтоб тепло. Другие даже зимой берут отпуск в горы, где снежно и можно кататься на лыжах."}]},{"type":"paragraph","content":[{"type":"text","text":"Каждый раз на планировании обсуждаем сроки на задачи. И тут мнения разница. Потому мы идём от минимального срока, тот кто его озвучил рассказывает как планирует уложить задачу в озвученное количество часов, что бы всем стало понятна его оценка."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Какой из этого можно сделать вывод?"}]},{"type":"paragraph","content":[{"type":"text","text":"Когда наша работа, это не про забить гвозди. Когда работа сложная, каждый выбирает методы достижения целей сам – свой режим, свои инструменты, свои места (офис, кафе, дом), свои позы (сидя, лёжа, на ходу проводя встречи со смартфона), свои инструменты, свои отпуска."}]},{"type":"paragraph","content":[{"type":"text","text":"Грустно что до сих пор существует множество компаний, в которых сотрудники вынуждены сидеть в опенспейсах со строгим режимом, с универсальным набором инструментов, со сроками которые ставит "},{"type":"text","marks":[{"type":"italic"}],"text":"начальство"},{"type":"text","text":", со всем этим рабским набором условий."}]},{"type":"paragraph","content":[{"type":"text","text":"Наш дружный опенспейс"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Радостно, что не смотря на это, у каждого есть возможность выбирать!"}]}]}','2026-01-03 06:32:29','2026-01-03 06:33:51',249,'2023-01-25T21:00:00.000Z','разработка');
INSERT INTO nest_posts VALUES(243,2,'post-1767421993','Тёплый шарфик','{"type":"doc","content":[{"type":"heading","attrs":{"level":3},"content":[{"type":"text","marks":[{"type":"italic"}],"text":"«Они должны либо принудительно развиваться, отказываясь от мировоззрения, центрированного вокруг их собственных жизней и ценностей, либо перестать существовать совсем.»"}]},{"type":"image","attrs":{"src":"https://sun9-east.userapi.com/sun9-35/s/v1/ig2/ctM0VtOdR73blegOA9xWIPfmKoKOmOjrdgysXQitcb65BnBACIS5YcEJM6RrIWJGzizAPpT6NeTRDA-J6C8f-dJB.jpg?size=800x600&quality=96&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"В комментариях я часто пишу что мало работаю. Может показаться что я ленивый. Но дело в том, что я продуктивен."},{"type":"hardBreak"},{"type":"text","text":"В эту пятницу я узнал, что компания сокращает штат. Уволили ребят которых я знал. Они занимались проектами, которые попали под сокращение."}]},{"type":"paragraph","content":[{"type":"text","text":"Задумался."},{"type":"hardBreak"},{"type":"text","text":"Мы живём в мире, где невероятно добрый, отзывчивый, не токсичный, невероятно продуктивный человек может оказаться на обочине по миллиону причин от него не зависящих."}]},{"type":"paragraph","content":[{"type":"text","text":"Сделал вывод – "},{"type":"text","marks":[{"type":"bold"}],"text":"быть сильным, что бы быть полезным"},{"type":"text","text":". Всегда нужно иметь на руках козыря – офферы в отношении работы, деньги – как подушку безопасности (особенно когда живешь на съёмной квартире)."}]},{"type":"paragraph","content":[{"type":"text","text":"Недавние события со "},{"type":"text","marks":[{"type":"italic"}],"text":"Special Operation"},{"type":"text","text":", научили меня иметь минимум вещей, только то что необходимо. Научили жить мобильно, подвижно. Научили думать наперед, не строить планы, а именно мыслить вперёд!"},{"type":"hardBreak"},{"type":"text","text":"Голосом бота Алёши"},{"type":"hardBreak"},{"type":"text","text":"– Аджайл в хату кожаный мешок! Велком ту реалити."}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Вомбат, батяня, батяна вомбат!"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Мораль:"},{"type":"text","text":" даже когда у тебя тёплая шёрстка, не забывай брать с собой шарфик!"}]}]}','2026-01-03 06:33:13','2026-01-03 06:34:24',248,'2023-01-27T21:00:00.000Z','разработка');
INSERT INTO nest_posts VALUES(244,2,'post-1767422081','Малолитражка','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/72fb224e-87f8-4aa3-b0dd-9379845dd26a.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"В среднем, я прохожу 10 километров в день."},{"type":"hardBreak"},{"type":"text","text":"Выпиваю в сутки 1 бутылку вина."},{"type":"hardBreak"},{"type":"text","text":"Итого расход 7,5 литров на 100 километров."},{"type":"hardBreak"},{"type":"text","text":"Выходит я "},{"type":"text","marks":[{"type":"bold"}],"text":"малолитражка"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":"Шах и мат друзья, которые считают, что я много пью!"}]}]}','2026-01-03 06:34:41','2026-01-06 01:49:34',247,'2023-01-29T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(245,2,'post-1767422133','Бессоница','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Не сплю с выходных."},{"type":"hardBreak"},{"type":"text","text":"Это вроде бы аскетизм называется? В терминах легко запутаться, сейчас их столько стало…"},{"type":"hardBreak"},{"type":"text","text":"– Это долбоебизм называется."},{"type":"hardBreak"},{"type":"text","text":"Поправляет внутренний голос."}]},{"type":"image","attrs":{"src":"https://sun9-east.userapi.com/sun9-73/s/v1/if1/I5Kh2cFBsO5IPsZT6dfnKEBJ0hsuSg3QN5ek_4hrAblI-0OPdIhrokAtbAVYPQx1E0LrViAA.jpg?size=604x437&quality=96&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Ночные коты"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Я полюбил ночь"}]},{"type":"paragraph","content":[{"type":"text","text":"Насколько могу себя вспомнить. С самого раннего детства любил ночь. Всё начиналось с протеста. Когда ребёнку, что-то нельзя, он это особенно хочет. Отсюда большая часть моих пристрастий. Что можно – скучно и неинтересно. Что запрещено, как минимум не известно, чаще – увлекательно и полезно. Пусть взрослые так не считают, я для себя замечаю – это не их, моё!"}]},{"type":"paragraph","content":[{"type":"text","text":"Так я полюбил ночные на крыши. Родительский дом, частный, не высокий, легко забраться."},{"type":"hardBreak"},{"type":"text","text":"В 12 лет у меня не было своей комнаты, но было своё небо. Удивительно, что никто кроме меня не пытался его заполучить. Ночью на крыше я всегда был один. Тогда и начала писать впервые. Сохранил эту привычку, вот пишу снова )"},{"type":"hardBreak"},{"type":"text","text":"Тогда родители говорили:"},{"type":"hardBreak"},{"type":"text","text":"– Что из него вырастет?"},{"type":"hardBreak"},{"type":"text","text":"А ктож его знает? Что-то растёт!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","marks":[{"type":"bold"}],"text":"Я полюбил тишину"}]},{"type":"paragraph","content":[{"type":"text","text":"Полюбил производить минимальное количество шума. Учусь тонко слышать, замечать ранее не видимые детали. Как ночью, ближе к утру, обостряется восприятие, как вдруг иначе работает память. Парадоксально – чем меньше сплю, тем больше чувствую. Момент, внутри что-то щёлкает и мир отпускает. Словно мой организм отключает ненужные процессы, экономит энергию. И для чего?…"}]},{"type":"paragraph","content":[{"type":"text","text":"Бессонные ночи близки к состояниям транса."},{"type":"hardBreak"},{"type":"text","text":"Воспоминания глубже, насыщенней. В фотографии можно провалиться, как в сон, когда долго на них смотреть и ни о чем не думать."},{"type":"hardBreak"},{"type":"text","text":"Появляется чувство, как если бы до таких состояний я был чем-то вроде фермы по добычи криптовалюты. Шуршал пропеллерами видеокарты, а сам себя не слышал, не сознавал. Но непременно что-то очень важное совершал, или по крайней мере так думал."}]},{"type":"paragraph","content":[{"type":"text","text":"И почему у меня так? Невротическое расстройство или глубоко осознанный душевный похуизм!"},{"type":"hardBreak"},{"type":"text","text":"– Кхе, кхе, долбоебизм, всё тот же."},{"type":"hardBreak"},{"type":"text","text":"Внутренний голос так же не спит."},{"type":"hardBreak"},{"type":"text","text":"– Может ты и прав, но мне нравится эти часы. Они по настоящему искренны, чисты, бессмысленны и потому бесценны!"}]},{"type":"image","attrs":{"src":"https://img3.teletype.in/files/e7/2b/e72b3ac4-c11e-4ae7-b47d-c24f56cb4c77.gif","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Внутренний голос"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Ребята с бессоницей:"},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/@roybidrill/HP_yRN543mi","target":"_blank","rel":"noopener noreferrer nofollow","class":""}}],"text":"\"Долгая долгая ночь\""},{"type":"text","text":", "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/@roybidrill","target":"_blank","rel":"noopener noreferrer nofollow","class":""}}],"text":"Рой Бидрилл"},{"type":"hardBreak","marks":[{"type":"link","attrs":{"href":"/@roybidrill","target":"_blank","rel":"noopener noreferrer nofollow","class":""}}]},{"type":"text","text":"2. ?"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"PS. Вот бы здорово стало, еслиб Телетайп умел Sound Cloud вставлять так вот"}]},{"type":"image","attrs":{"src":"https://img3.teletype.in/files/a6/da/a6daf811-7f48-4010-8f73-3618895b5fea.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Пока только ссылки "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/@roybidrill/HP_yRN543mi","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://on.soundcloud.com/cVxYM"}]}]}','2026-01-03 06:35:33','2026-01-06 02:20:53',246,'2023-01-29T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(246,2,'post-1767422205','Люди и Боты','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"У вас когда-нибудь было чувство, что некоторые людей в какой-то момент заменяют "},{"type":"text","marks":[{"type":"italic"}],"text":"боты"},{"type":"text","text":"? Будто душам надоело играть за этих персонажей и они просто "},{"type":"text","marks":[{"type":"bold"}],"text":"ушли"},{"type":"text","text":". В этот момент система поставила человека на "},{"type":"text","marks":[{"type":"italic"}],"text":"автопилот"},{"type":"text","text":", отрабатывать базовые функции. Ведь вселенная не терпит пустоты, а убивать жалко."}]},{"type":"image","attrs":{"src":"https://img3.teletype.in/files/65/01/65017b85-dc76-44f1-8b68-74cd706bb868.jpeg","alt":null,"title":null}},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"italic"}],"text":"Мы слишком разные детали одного механизма"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Такие ситуации замечал и с друзьями и с коллегами. Тут можно строить много теорий, вероятно тому есть и простое научное объяснение. Но некоторые ситуации настолько загадочные и необычны, объяснить их просто не получается. Или быть может мне хочется верить во что-то магическое, неопознанное."}]},{"type":"paragraph","content":[{"type":"text","text":"Вспоминаю момент, я расстался с девушкой, мы не общались несколько месяцев. И вот созвонились, она позвонила и начала что-то говорить. А я не пойму кто мне звонит? Смотрю номер записан правильно, но голос не узнаю. И энергетика совсем другая. Слушаю и не понимаю. Это кстати так и осталось. Будто человека просто заменили другим."}]}]}','2026-01-03 06:36:45','2026-01-06 02:21:42',245,'2023-01-29T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(247,2,'post-1767422480','Кошмары','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Он проснулся от странного незнакомого ранее чувства. Это была трезвость."},{"type":"hardBreak"},{"type":"text","text":"— Ну вот приехали. Стоило стольких усилий, нет... На тебе. Протрезвел!"},{"type":"hardBreak"},{"type":"text","text":"Сказал он себе с укором. Достал из холодильника бутылку пива, выпил и снова лёг спать."}]}]}','2026-01-03 06:41:20','2026-01-03 06:42:22',244,'2023-01-31T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(248,2,'post-1767422599','Забыл о чём этот пост','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Люди делятся на тех, кто ничерта не думает, но всё знает и помнит. И на тех, кто ничерта не помнит и постоянно обо всём думает."}]},{"type":"image","attrs":{"src":"https://img1.teletype.in/files/48/7d/487d3f43-1fa1-427b-8b01-ca37a8ec82f6.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Я сегодня пешком"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"У первых"},{"type":"text","text":" есть исчерпывающие ответы на важные мировые события. Они помнят даты всех на свете праздников, дней рождений и именин. Они за словом в карман не полезут! Но всё это крутится в рамках предметной области мира который обязательно на что-то делится: правых и левых, верующих и не верных; хороших и плохих. Эти миры безусловно есть, но кажется давно заполнены. В них обязательно не найдётся места тем, кто хочет создать что-то из ряда вон новое."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Потому вторых"},{"type":"text","text":", кто ничерта не помнит и задаёт вопросы выкидывает каждый раз на обочину. Тогда там, где-то на безлюдной дороге мы создаём свои ноты, песни, картины, стихи. Творения которые априори будут еще долго не приняты и не поняты. Но да и хер бы с ним! (="}]}]}','2026-01-03 06:43:19','2026-01-03 06:43:53',243,'2023-02-01T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(249,2,'post-1767422656','Закат на Херсонесе','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img1.teletype.in/files/c5/2f/c52fc9cf-c4ca-4c33-be8a-0e68746e5b17.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Севастополь 2016"}]},{"type":"paragraph","content":[{"type":"text","text":"Иногда хочется открыть бутылку Крымский Ривьеры и окунуться в ностальгию. Воспоминания это же хорошо, когда они не мешают жить в настоящем, но появляться изредка."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Самое неприятное в отношениях то, что когда они заканчиваются"},{"type":"text","text":", с людьми из них тоже перестаёшь общаться. И уже не обсудить не вспомнить, что было хорошего, а хочется. Ведь есть встречи выпускников, так и тут. Если смотреть на жизнь, как на постоянное обучение, мы ведь развиваемся, как бы этого порой не хотели и очень на моей взгляд хорошо, когда сохраняешь связь."}]}]}','2026-01-03 06:44:16','2026-01-06 02:35:35',242,'2023-02-07T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(250,2,'post-1767422718','Модный приговор','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-west.userapi.com/sun9-69/s/v1/ig2/7h23ZD1DGIl8wBzgWzN0ghVijHpXl9-QszH6a6-7OT2Rigyky-3zGDunJw5z_20Md2oF7LNdROctasmQxRBtaoLb.jpg?size=720x772&quality=96&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Скидки на Шаурму в Реутово 20%"}]},{"type":"paragraph","content":[{"type":"text","text":"Вот былоб прикольно гуляя по улице в модном пальто словить момент истины, когда душа покинуло твоё тело. Ведь что такое тело для души? По сути такое же пальто, а твоё тело не модное пальто, сорян."}]},{"type":"paragraph","content":[{"type":"text","text":"И вот ты бродишь с этой внутренней пустотой, кричишь где-то внутри, воешь. А никто не слышит. Тогда идешь в магазин и скупаешь все подряд модные вещи, чтоб как у людей. В которых нет душ. Кек"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"О рыцарь мой в сияющих доспехах Как жаль что пуст внутри. И глух твой вой в утробе водостока, В отсутствии течения воды."}]}]}','2026-01-03 06:45:18','2026-01-03 06:46:15',241,'2023-02-08T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(251,2,'post-1767422795','Любовь к полетам','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-west.userapi.com/sun9-54/s/v1/ig2/dtPyN0LMsAE6Z20ZyH27FXpC8h6LYoejk0q5L0pTSWI0c6zQ9vTeoMbHmnr88OG-Te7F-pp_WiH8CS8-fV5zMhdG.jpg?size=1080x1053&quality=96&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Рис 1. Когда Мышб посоветовал грибы и ты их попробовал"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Самое дорогое в моей жизни, это "},{"type":"text","marks":[{"type":"italic"}],"text":"топливо"},{"type":"text","text":"!"}]},{"type":"paragraph","content":[{"type":"text","text":"Межгалактические перелеты обходятся очень дорого."}]},{"type":"paragraph","content":[{"type":"text","text":"А эти прыжки в гипер, знаете да? Неделю можно содержать семью из трех роботов-аутистов с их этими футболами, пивами, роллами… Однако! Сколько полезной информации удается вытянуть из антипространства…"}]},{"type":"paragraph","content":[{"type":"text","text":"На пластиковой карте, вместо привычного паспортного имение красуется Giordano Bruno (real, спасибо Олегoff). Как хотите, но мы вас заставим крутиться! Пусть и придется еще много раз то спускаться в чертов Ад, то подниматься, сгорать как от "},{"type":"text","marks":[{"type":"italic"}],"text":"солнца"},{"type":"text","text":" падать без чувств. На этот раз без саможаления, осознанно и с дебильной улыбкой на лице. Люблю!"}]}]}','2026-01-03 06:46:35','2026-01-03 06:47:13',240,'2023-02-10T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(252,2,'post-1767422850','Нутрициология','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-west.userapi.com/sun9-7/s/v1/ig2/dvm2VOC08I3RcBxV7Hg0wAQoSKw-t6SjVr9hxIKATwLdEsoHUPE9hDe7_SFHpm0WZmRsgxzA1wwTE-ZzTMqCxcTS.jpg?size=1669x2160&quality=95&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Как обмануть глупый живот? Секрет прост! Просыпайтесь пока он спит, ночью, ешьте что захотите и тут же ложитесь спать снова. Живот не успеет понять что происходит и не станет толстеть."}]}]}','2026-01-03 06:47:30','2026-01-03 06:47:51',239,'2023-02-10T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(253,2,'post-1767422884','Идти','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img3.teletype.in/files/6d/23/6d230101-a929-4cb1-b1b4-4d27b138878e.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Я чувствую, что живу, когда остаюсь один."},{"type":"hardBreak"},{"type":"text","text":"Звучит парадоксально, но тут есть логика. Быстро идти долго не получится, в какой-то момент останавливаешься, оглядываешься вокруг и вдруг"},{"type":"hardBreak"},{"type":"text","text":"– Ой, где я?"},{"type":"hardBreak"},{"type":"text","text":"Крадётся мысль, что сбился с пути, хотя далеко не один тут, но…"},{"type":"hardBreak"},{"type":"text","text":"– С теми ли я?"}]},{"type":"paragraph","content":[{"type":"text","text":"Какое-то время отбиваясь от рекламных предложений ломишься словно через чащу и в какой-то момент оказываешься на солнечной полянке внутренней пустоты…"}]},{"type":"paragraph","content":[{"type":"text","text":"Полянка внутренней пустоты"}]},{"type":"paragraph","content":[{"type":"text","text":"…Присаживаешься попить чаю и отдохнуть и так открывается новый путь, который твой. Когда долгое время чувствовал себя ноль, тут ты один – это не одиночество, а +1!"}]},{"type":"paragraph","content":[{"type":"text","text":"Понимание этого раздвигает кусты, так открывается новый путь."},{"type":"hardBreak"},{"type":"text","text":"Какое-то время по нему идешь один, насвистывает мелодию подпевая ветру. Проходит немало времени порой, до момента когда встречаешь попутчиков."}]},{"type":"paragraph","content":[{"type":"text","text":"Важно выждать этот момент, не сворачивать со своего пути."},{"type":"hardBreak"},{"type":"text","text":"Идти!"}]}]}','2026-01-03 06:48:04','2026-01-03 06:48:28',238,'2023-02-13T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(254,2,'post-1767422919','Брэд Прокопьевны','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img1.teletype.in/files/87/3f/873f2076-4651-4567-bb73-f35921539e98.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Вдогонку "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/@roybidrill/wNdvbPpD47w","target":"_blank","rel":"noopener noreferrer nofollow","class":""}}],"text":"Zoolander''ским пчёлам"}]},{"type":"paragraph","content":[{"type":"text","text":"Мне кажется миллионеры, топ-менеджеры, прочие элиты пытаются таким способом сказать, что типа"},{"type":"hardBreak"},{"type":"text","text":"– Ребят, мы люди на всех уровнях хотим заниматься исключительно любимой нами, каждый своей, уникальной хуйней. И не мешайте себе этим заниматься! Мы вообще не против. Вы можете уже сейчас!"}]},{"type":"paragraph","content":[{"type":"text","text":"Что вы об этом думаете?"}]}]}','2026-01-03 06:48:39','2026-01-03 06:48:57',237,'2023-02-13T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(255,2,'post-1767422960','Суперсобность','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img4.teletype.in/files/74/7f/747f06b5-f524-4e6e-8845-2ff8d77f3864.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Всегда мечтал иметь кнопку, на которую нажал и вдруг \"Птыщь!\", время остановилось. Мир остановился. Лучшая суперспособность! Пусть и работала бы в рамках квартиры, не для того что бы выходить на улицу и творить хуйню с людьми которые "},{"type":"text","marks":[{"type":"italic"}],"text":"застыли"},{"type":"text","text":". Исключительно для себя, что бы высморкаться и выспаться. Нормально. Хоть раз…"}]}]}','2026-01-03 06:49:20','2026-01-03 06:49:34',236,'2023-02-14T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(256,2,'post-1767423002','Планирование расходов','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-west.userapi.com/sun9-52/s/v1/ig2/fHwgkrGEEQYKwWBYef13nRT7X54vtCEOehShtX-LvJq16URNTBGdGtEx_A-4CUFQFVHN98ywP2saL21v-dmZWWhp.jpg?size=1048x1080&quality=95&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Каждый раз, когда я чего-то хочу и мне не хватает денег, я задаю себе два вопроса:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Почему я хочу то, что не могу себе позволить?"},{"type":"hardBreak"},{"type":"text","text":"2. Почему я не могу себе позволить то что хочу?"}]},{"type":"paragraph","content":[{"type":"text","text":"Задавать эти вопросы можно в любой последовательности. Важно каждый раз задавать оба вопроса. Не менее важно искренне и честно себе признаваться"},{"type":"hardBreak"},{"type":"text","text":"– А ведь мне на самом то деле это совсем не нужно!"},{"type":"hardBreak"},{"type":"text","text":"Либо"},{"type":"hardBreak"},{"type":"text","text":"– А ведь нужно! Но я на нищебродной зарплате. Иду просить up по деньгами и запишусь на курсы!"}]},{"type":"paragraph","content":[{"type":"text","text":"Однако какой нормальный анализ может обойтись без бутылочки красного вина?"}]},{"type":"image","attrs":{"src":"https://sun9-east.userapi.com/sun9-57/s/v1/ig2/oHML559yoXtgF6C7NLMMvY7P4jLrKTMgDgSssLaNK3d5J4WTTGqrTUHIS4DhvA_nVgMalWW-iWgJLQd7Z1B87BLo.jpg?size=626x418&quality=96&type=album","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Ушёл анализировать расходы…"}]}]}','2026-01-03 06:50:02','2026-01-03 06:50:22',235,'2023-02-15T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(257,2,'post-1767423044','Ли','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img2.teletype.in/files/9e/06/9e06de05-c32a-41ab-a0e7-94af6d526fc2.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Этот пост написан в стиле – поток сознания. Потому сумбур с нотками надежды о солнечном лете и приключениях :)"}]},{"type":"paragraph","content":[{"type":"text","text":"\"Даже путь в тысячу ли начинается с первого шага\""},{"type":"hardBreak"},{"type":"text","marks":[{"type":"italic"}],"text":"Лао-цзы, книга Дао дэ цзин"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ли"},{"type":"text","text":" – единица измерения расстояния, 300-350 шагов или 500 метров."},{"type":"hardBreak"},{"type":"text","text":"Так 2 Ли = 1 км, 1000 ли = 500 км."}]},{"type":"paragraph","content":[{"type":"text","text":"С появлением машин, поездов и самолетов единица расстояния Ли уже не кажется большой. Сколько таких тысяч ли суммарно мы уже преодолели в жизни?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Мысль 1 "},{"type":"text","text":"Погружаясь в воспоминания о тех мгновениях, которые хотим так ещё раз прожить. Это считается расстоянием? Круги, которые наворачивали в коридорах и комнатах, где мы останавливались, засыпали, просыпались, считается? Застывали в пространстве между мирами, придуманными кем-то в книгах. Эти расстояния можно измерить в ли, в киллометрах?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Мысль 2"},{"type":"hardBreak"},{"type":"text","text":"Жизнь так устроена, идешь каждый раз будто прощаясь со старым другом –каждый новый этап забываешь к нему дорогу. Каждый новый вспоминаешь вновь."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Мысль 3 "},{"type":"text","text":"Чаще повседневно, пытаясь сориентироваться в потоке таких же, стоящих в пробке утренних сов, размышляя о чём-то отвлечённом, бродя по выдуманным мирам. Смотря на людей со стаканчиком кофе рядом с собой на остановке, в метро."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Мысль 3,э14… Пиздатая мысль! "},{"type":"text","text":"Мы выросли и стали успешны, с брезгливостью смотрим на бродячих-псов, возвращаясь в дом, что бы там гладить своих мурлыкающих котов."},{"type":"hardBreak"},{"type":"text","text":"Часто теперь "},{"type":"text","marks":[{"type":"italic"}],"text":"наш Ли"},{"type":"text","text":" = расстоянию от кровати до пакета кефира."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","marks":[{"type":"italic"}],"text":"А ведь хочется…"}]},{"type":"image","attrs":{"src":"https://sun9-east.userapi.com/sun9-27/s/v1/ig2/S7PB0mFcqgFDleXt9zI98RzExzs2J8lGRnPLQk_uFMX4EXegJpVf2HEXAz1BvFPjlwdWe4hvEVRXn-kxurl7zS6A.jpg?size=1080x1350&quality=95&type=album","alt":null,"title":null}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","marks":[{"type":"italic"}],"text":"…путешествий!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"*бродячие псы кстати путешествуют. А ты нет! ;)"}]}]}','2026-01-03 06:50:44','2026-01-03 06:51:18',234,'2023-02-15T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(258,2,'post-1767423114','Матрица Пересмотр','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Загнался про матрицу, идея которой в антиутопии в своем самом жестоком проявлении: конец света давно позади, и ничего нельзя исправить…"}]},{"type":"image","attrs":{"src":"https://img2.teletype.in/files/df/96/df96ccd3-6deb-455e-ba44-e19b8e97c3c7.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"…ну немнжко грустно, да"}]},{"type":"paragraph","content":[{"type":"text","text":"Пожалуйста напомните, что там про то общее пространство за пределами планеты, в котором живут машины? У нас ведь есть космос. В матрице стало было тоже есть, на Луну там слетать можно, не по настоящему конечно, но можно."}]},{"type":"paragraph","content":[{"type":"text","text":"У машин есть космос? Вероятно есть. Поля с людьми (батарейками) же бескрайние, а машин между тем все больше и больше… То есть они, машины, этот условный свой космос исследуют? Кажется да. А люди между тем по прежнему живые, но в банках лежат."}]},{"type":"paragraph","content":[{"type":"text","text":"Тэкс! Тогда еще, как минимум 2 хеппи-энда, против одной утопии:"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Версия 1: Наивная, которая никому не зайдет"}]},{"type":"paragraph","content":[{"type":"text","text":"Машины найдут еще один мир людей в глубинах космоса, там люди будут намного более развиты, чем эти самые машины. Потому люди дадут машинам секрет альтернативного топлива (не люди), освободят людей, одни с другими подружатся, нарожают киборгов и станут вообщем жить долго и счастливо и войдут в сингулярность в один день."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Версия 2: С уничтожением грязных роботов, как мы любим"}]},{"type":"paragraph","content":[{"type":"text","text":"Настоящий "},{"type":"text","marks":[{"type":"italic"}],"text":"Нео"},{"type":"text","text":" придет из глубин космоса и освободит людей. Идея о том, что Нео то не настоящий был! Ну и то что настоящий умеет летать за орбитой и в гипер прыгать в одних подштаниках, вообщем крутой. Машинам точно конец!"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Версия 3: А ну и…"}]},{"type":"paragraph","content":[{"type":"text","text":"Нео, добрый архитектор ученый, который разводит машин, считайте создает ИИ. Тогда матрица, это и есть мир машин изначально. А та матрица, что внутри этого мира тест. Сумеют ли машины понять свою роль и добраться до их создателя? Нет конечно, кек"},{"type":"hardBreak"},{"type":"text","text":"Мыж люди всё придумали сами и их конечно тоже."}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"https://img4.teletype.in/files/3e/ea/3eea5af9-71d6-439a-9776-3cc59a393b31.png","alt":null,"title":null}}]}','2026-01-03 06:51:54','2026-01-03 06:52:14',233,'2023-02-16T21:00:00.000Z','кинофильмы');
INSERT INTO nest_posts VALUES(259,2,'post-1767423163','🧩','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Работа, которая тебе нравится, не позволяет тебе жить там, где тебе нравится ) когда-нибудь ты будешь стоять перед большим выбором"}]},{"type":"paragraph","content":[{"type":"text","text":"Заметка себе, что бы помнить"}]}]}','2026-01-03 06:52:43','2026-01-03 06:54:45',232,'2023-02-26T21:00:00.000Z','пейджер');
INSERT INTO nest_posts VALUES(260,2,'post-1767423329','Перманентный отпуск','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img4.teletype.in/files/f6/c7/f6c77e39-b736-4bb7-9a20-da7d152c2b67.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Появилась идея накопить условный миллион рублей и улететь на Бали, в перманентный отпуск на один год."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Идея"}]},{"type":"paragraph","content":[{"type":"text","text":"В 2016 году я расстался с девушкой. Переехал из Тульской квартиры где мы жили обратно в Калугу. Первое время я жил и кутил у друга. Затем снял квартиру у подруги и вместе с тем потерял работу. Было немножко денег, потому я занимался "},{"type":"text","marks":[{"type":"italic"}],"text":"ничем"},{"type":"text","text":" практично полезным, я прислушивался к себе. Так, без дела, у меня появилась возможность проводить ночи наедине с собой и своими мыслями. Не просто думать – а чего же я всё таки хочу? А действительно делать что хочу и наблюдать за собой, выявлять в своих действиях пользу, то что может впоследствии перерасти в работу, в стиль жизни."}]},{"type":"paragraph","content":[{"type":"text","text":"Прошло полгода."},{"type":"hardBreak"},{"type":"text","text":"По итогу я пришёл к понимаю чем я хочу заниматься по работе. Где я хочу жить. С кем я хочу общаться. Этот отпуск на полгода расставил все по местам!"},{"type":"hardBreak"},{"type":"text","text":"Позже я задумался, как мало людей позволяют себе подобное. Мы (мир) с самого рождения спешим!"}]},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"(= Садик > Школа > Универ > Работа > Семья > Могилка =)"}]},{"type":"paragraph","content":[{"type":"text","text":"Ключевые моменты моей жизни происходили, когда я чево-то терял: разрывались отношения, терял работу, переезжал в другой город, менял компания, обзаводился или избавлялся от зависимостей. Всё это суперстрессовые ситуации, которые я не инициировал осознанно."},{"type":"hardBreak"},{"type":"text","text":"Теперь хочется иначе, с пониманием дела…"}]},{"type":"paragraph","content":[{"type":"text","text":"…С чувством глубоко осознанного похуизма! (="}]},{"type":"paragraph","content":[{"type":"text","text":"Наблюдать за собой год, не занимаясь ничем насильственно. Просыпаться когда хочу. Есть что хочу и пить. Общаться с теми кем хочу. Я ведь не ленивый и не мудак даже. Можт что из этого выйдет… Осталось накопить миллион и потерять работу."}]},{"type":"paragraph","content":[{"type":"text","text":"Штош, цель поставлена!"}]}]}','2026-01-03 06:55:29','2026-01-03 06:57:09',231,'2023-05-08T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(261,2,'post-1767423521','Собака медитака','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img1.teletype.in/files/cf/55/cf5502bf-d9ed-4479-a8bb-4e646431f45c.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Я все ещё невротик и продолжаю шуршать социальными сетями, по прежнему вечером в моей квартире не гаснет свет, даже в трёх комнатах в которых я не появляюсь. Однако теперь я могу позволить себе спокойный отдых без алкоголя и веществ. Меня не кусают космические пчёлы, не жужжат надо мной беспокойными мыслями. Я стал больше планировать, меньше тратить, игры с вещами отходят на второй, третий, четвёртый план. Всё что мне нужно у меня уже есть. Я становлюсь счастливым!"}]},{"type":"paragraph","content":[{"type":"text","text":"И даже картину нарисовал, потом её вам представлю (пока только скетч в заголовке поста)"}]}]}','2026-01-03 06:58:41','2026-01-03 06:59:22',230,'2023-03-16T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(262,2,'post-1767423591','👻','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Что делает душа человека, в момент когда тот находится в коме, много лет?"}]}]}','2026-01-03 06:59:51','2026-01-03 07:00:15',229,'2023-04-30T21:00:00.000Z','пейджер');
INSERT INTO nest_posts VALUES(263,2,'post-1767423674',' Onde','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img2.teletype.in/files/55/76/557668be-42a5-4814-bc28-78b4f13fc44d.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Снег был белым, когда ты родился,"},{"type":"hardBreak","marks":[{"type":"italic"}]},{"type":"text","marks":[{"type":"italic"}],"text":"И зима, была не зимой…"}]}]}','2026-01-03 07:01:14','2026-01-03 07:02:59',228,'2024-11-15T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(264,2,'post-1767423818','Datэ','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img1.teletype.in/files/8d/4c/8d4cefad-b247-48c4-bc3d-690d5cc95646.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"…поразнюхал тут и выяснил, что количество знаний школьной программы с 1900 по настоящее время увеличилось в 5 раз. И почти во столько же раз увеличились продажи антидепрессанты за последние 10 лет."},{"type":"hardBreak"},{"type":"text","text":"Можно ли сделать вывод, что людям стало грустно от такого количества информации? (="}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"https://img3.teletype.in/files/e1/4e/e14e0a4a-c03b-4a4c-861a-794df3d570c0.png","alt":null,"title":null}},{"type":"image","attrs":{"src":"https://img1.teletype.in/files/4f/7c/4f7c9e56-ee08-4829-a743-773ebeb65d33.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"А ну и бонус…"}]},{"type":"image","attrs":{"src":"https://img1.teletype.in/files/83/51/8351c17e-6507-41b7-a245-688b2bca8bc8.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"</joke>"}]}]}','2026-01-03 07:03:38','2026-01-03 07:03:57',227,'2025-02-09T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(265,2,'post-1767423854','Ракушечный плед','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img1.teletype.in/files/85/17/8517e2f0-9334-4e47-a161-6929adb2d5aa.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"А вы знали что раньше фиолетовый цвет получали из ракушек, которые так \"пахли\" что женам рабочих изготавливающих краситель разрешали разводиться с мужьями потому как те жутко воняли? ;)"}]},{"type":"paragraph","content":[{"type":"text","text":"Все думаю про слова и их отсутствие, как это отражается на нашем восприятии мира и общем развитии."}]},{"type":"paragraph","content":[{"type":"text","text":"Скажем есть явление, оно доступно для наблюдения. Но его невозможно повторить, использовать, практически применить. Таким образом это явление долгое время остается в тени обсуждений и если оно доступно локально для региона или группы лиц с уникальными способностями его уловить, то в конечном итоге это явление можно полностью скрыть, оно может окончательно бесследно исчезнуть."}]},{"type":"paragraph","content":[{"type":"text","text":"С цветом так не вышло. Он не исчез, потому как люди научились изготавливать и применять соответствующие краски. Можно сказать явление цвета ожидало своего времени и его появление и развитие вопрос системный. Хотя когда-то, в древних текстах типа Илиада Гомера, не было описания зеленого и синего, даже когда дело касается воды или неба, оно становилось цвета вина или мёда. То есть не было красок, не было названия цвета. Но потом научились добывать краситель и придумали им имена! То…"}]},{"type":"paragraph","content":[{"type":"text","text":"Что касается мифологии, сказочных существ, магии. Что если в одном регионе существовали сказочные существа, которые вымерли до того как их смогли описать, приручить, поделиться ими с миром? Что если технологии, к которыми можно отнести магию или шаманизм, так же считается фантастикой, просто потому что современный мир не успел до этого добраться. Или не может, потому как последователи, те кто \"шарят в теме\" делают вид, что этого не существует, прекрасно понимая, как им только на руку, что остальной мир считает это вымыслом?"}]},{"type":"paragraph","content":[{"type":"text","text":"Возможно, часть мифологии — это "},{"type":"text","marks":[{"type":"bold"}],"text":"память о реальных явлениях"},{"type":"text","text":", которые мы утратили, потому что не успели их систематизировать."}]},{"type":"paragraph","content":[{"type":"text","text":"Другими словами, если у явления нет имени, оно остаётся "},{"type":"text","marks":[{"type":"bold"}],"text":"локальным опытом"},{"type":"text","text":", доступным лишь тем, кто его наблюдает. Без языка оно не может стать частью культуры, науки или практики. В итоге такие явления могут исчезнуть, как будто их никогда не было — потому что "},{"type":"text","marks":[{"type":"bold"}],"text":"память без слов хрупка"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"И конечно как сложно "},{"type":"text","marks":[{"type":"italic"}],"text":"всяким там"},{"type":"text","text":" психонавтам описывать свой психоделический опыт в отсутствии слов описывающих те или иные приключившиеся с ними явления."}]}]}','2026-01-03 07:04:14','2026-01-03 07:04:34',226,'2025-11-14T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(266,2,'post-1767423892','Балкон','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img2.teletype.in/files/1e/8e/1e8e766b-3e9f-4fff-900b-77a496975598.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"У нас был прекрасный балкон с цветами!"},{"type":"hardBreak"},{"type":"text","text":"И когда ты ушла наступила осень и я грустил как никогда ещё и потому что вянут цветы. И тогда ты напомнила про то, что всё циклично и что наступит май!"},{"type":"hardBreak"},{"type":"text","text":"Май наступил но не принёс ничего из ожиданий. И вместе с разочарованиями наступила осень. И вот уже первый снег на воротнике моей куртки и память о том самом балконе и цветах."}]},{"type":"image","attrs":{"src":"https://img1.teletype.in/files/4b/bf/4bbf9863-3776-4d9b-bdfa-9491263ad70c.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Что поделать если вселенная решила расширять тёмную сторону? Примем и это."}]}]}','2026-01-03 07:04:52','2026-01-03 08:36:52',225,'2025-11-16T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(267,2,'post-1767423947','Толщина линии','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img3.teletype.in/files/a6/89/a689b45e-afab-4924-aa5b-763dc024a9f6.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Я не толстая, это линия широкая"}]},{"type":"paragraph","content":[{"type":"text","text":"Девушка объедает парня! =)"}]},{"type":"paragraph","content":[{"type":"text","text":"Интересно, дизайнер так тонко пошутил (толщина линий) или закосячил, использовал иконки из разных сетов?"}]}]}','2026-01-03 07:05:47','2026-01-03 07:06:04',224,'2023-02-14T21:00:00.000Z','разработка');
INSERT INTO nest_posts VALUES(268,2,'post-1767423980','Собакам снятся цветные сны','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img3.teletype.in/files/a0/ac/a0ac7a3d-dece-4d37-9902-6b39c16fb031.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Зона А18D"},{"type":"text","text":", найдена собака на солнечной батарее, вязанная с грибами, явно не с этой планеты, говорящая в слух на всех языках."},{"type":"hardBreak"},{"type":"text","text":"– я тут одна дворняга, не нужна миру. Никому. Остальные дорогие, страшно породистые, буду спать, пусть мне снятся "},{"type":"text","marks":[{"type":"bold"}],"text":"цветные сны!"}]}]}','2026-01-03 07:06:20','2026-01-06 01:35:50',223,'2023-01-18T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(269,2,'post-1767424034','Полнометражные сны','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как мы едем на огромной фуре оборудованной под дом на колёсах. В салоне есть все для того, что бы пережить последствие военных действий (типа Fallout) несколько лет. В салоне друзья, нас было пятеро кажется. Примечательно что среди тех, кого я знаю в жизни лично были и голливудские актеры. В этом сне например \"снимался\" Майкл Мэдсен и мы общались как друзья. Я спрашивал его, где он так долго был и он рассказывал про тайную операцию где-то на полярном круге. Как оказалось позже у всех нас были какие-то тайны и мы не просто так не виделись несколько лет. А тут и вовсе кажется только притворялись друзьями, всё было гораздо сложнее. Истинная суть наших отношений стала известна когда на нас внезапно напали. Несколько бронированных машин окружили фуру и началось как в типичном боевике: стрельба, погоня, предательство, дружба, может быть даже любовь…"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Проснулся попить и поесть арбуза"}]},{"type":"paragraph","content":[{"type":"text","text":"Следующий сон не менее звёздный, в нём уже пару актёров кино. Детали не вспомнить. Этот фильм был не такой интересный, сплошные диалоги, детали быстро вылетели из головы…"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Проснулся попить и поесть арбуза"}]},{"type":"paragraph","content":[{"type":"text","text":"Еще один фильм и снова актёры. Помню кекнул в голос во сне, типа – ребят, вы чего вдруг все у меня во сне? Это была комедия, мы много смеялись. Я думал что просплю работу, но встал на удивление рано. Отправился курить на балкон и задумался."}]},{"type":"paragraph","content":[{"type":"text","text":"Как мой мозг всё это рисует и зачем? Ведь я почти не смотрю фильмы. Получается, мозг достаёт образы из забытых мной воспоминаний и крутит, мол – смотри чё покажу?"},{"type":"hardBreak"},{"type":"text","text":"Стоит похвалить мозг, сны были интересные! И каждый длился, полный метр, не меньше."},{"type":"hardBreak"},{"type":"text","text":"А может мозг и тело с ним мне так хотят сказать – тыб почаще спал, мы тебе вот фильмы, мультфильмы показывать будем, а то чево ты, ну… )"}]}]}','2026-01-03 07:07:14','2026-01-03 07:07:42',222,'2022-08-02T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(270,2,'post-1767424081','Игра в частицы: Тьма','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В этом сне я не занимаю определенную каким-то конкретным человеком роль. Вместо этого, я перемещаюсь свободно, как некая точка, фокус камеры, наблюдаю все, что происходит со стороны и время от времени сопереживаю то, что происходит, как бы «вселяясь» в кого-то, кого видел до этого со стороны. Не смотря на эту казалось бы свободу, сон очень мрачный и эти переживания, как будто сценарий, чей не знаю, но я не могу им управлять. Примечательно, что со стороны я наблюдаю ровно до тех пор, пока меня не бросает в тело человека, которого с минуту на минуту должны убить."}]},{"type":"paragraph","content":[{"type":"text","text":"…Кажется, что это Чечня или Афганистан. Я наблюдаю небольшой отряд, который двигается на территории врага. Возможно это российские солдаты."}]},{"type":"paragraph","content":[{"type":"text","text":"Поле боя выглядит так, что первая мысль, которая меня посетила – как тут вообще может кто-то выжить. Воздух пропитан кровью, дымом, сажей и страхом. Да, как будто страх в этом сне служит некой заменой воздуха, того что позволяет людям дышать, чего давно нет в этой атмосфере."}]},{"type":"paragraph","content":[{"type":"text","text":"Отряд двигается очень напряженно, устало, но быстро, как будто за ними толи, кто-то гонится, толи они преследуют врага. В какую-то секунду, невидимый противник начинает очень быстро, одного за другим лишать жизни солдат этого отряда. Я это понимаю, поскользнулось меня кидает из стороны в сторону, как камеру, которой играют в футбол, словно это мяч. Вместе с тем страх усиливается концентрируясь словно жидкость в сосуде последнего выжившего. Напряжение столь велико, что я начинаю переживать события из его глаз."}]},{"type":"paragraph","content":[{"type":"text","text":"Я стою склонив голову, руки за спиной связаны. Туман постепенно рассеивается и я вижу трупы солдат своего отряда. Кажется я – это командир. Но, теперь когда командовать некем, это звучит как насмешка. Я чувствую себя словно мне снова лет 6-7 не больше. Вокруг меня, кто-то громко разговаривает. Я приподнимаю голову и одновременно по немного, как наложение одной картинки на другую, вижу себя со стороны. Вокруг меня сосредоточилось несколько вражеских солдат и офицеров. Все чего-то ждут или кого-то. Его кажется боятся даже свои, от чего моя участь становится понята и ужас заставляет искать глазами того, кто должен все это закончить."}]},{"type":"paragraph","content":[{"type":"text","text":"Очень неспешно но уверено, как призрак появляется тот, чья сила столь велика, сколько ужасно выглядят его очертания и огромный меч, который он держит в руках так крепко, словно это продолжения его руки. Вес меча при этом как будто игнорируется всеми, но размер говорит о том, что человек сумевший поднять его не может быть человеком в привычном понимании того, что мы знаем о людях и их возможностях. Почему-то хочется назвать его генералом призраков, хотя это только тут может выглядеть тривиально и глупо. Кимоно или ряса в которую он одет с каждым его шагом принимает очертания грязных лохмотьев, которые теряют надежду на то, что генерал может быть честолюбив и консервативен, а меч лишь декорация, словно и служит он исключительно для запугивания и поощрения чувства собственного величая. Лохмотья извиваются на ветру настолько свободно, что кажется под ними ничего нет, это ощущение очень тяжело сочетается с ужасной на вид головой, пустыми глазами, отсутствием какой либо мимики, многочисленными шрамами и абсолютно синей кожи. Кажется это голова давно умершего человека. Об этом так же свидетельствует шрам вокруг шеи, словно ее отделили от тела."}]},{"type":"paragraph","content":[{"type":"text","text":"Я снова вспоминаю себя командиром отряда. Страх говорит о том, что меня скорее всего возьмут в плен, что меня будут пытать, что мне нужно молить о пощаде. Но не успеваю я открыть рот, исполнить хоть звук, призрак делает резкий выпад вперед в мою сторону и как тень просачивается сквозь меня становясь на секунду живым мечом, обретает прежнюю форму за моей спиной, камера показывает обмякшую словно кашу форму человеческого тела медленно падающего на землю, рядом со своей головой из глаз которой я продолжаю наблюдать бывшего хозяина этого тела."}]},{"type":"paragraph","content":[{"type":"text","text":"Призрак непоколебимо, как будто ничего не произошло направляется дальше. Страх за себя превращается в ужас вместе с пониманием того, что я это мальчик, которого пытался защитить отряд, за которым пришел призрак, который наблюдает все эти события укрывшись за полуразрушенным сараем, испуганно держащим в руке какой-то очень важный предмет не дающим ему право бежать, отступить или прятаться."}]},{"type":"paragraph","content":[{"type":"text","text":"Призрак останавливается в двух шагах от мальчика. Они долго смотрят друг другу в глаза, как будто вспоминают как началась или кто начал эту войну. Кажется теперь я совершенно перестал понимать какова моя роль: наблюдатель, мальчик или этот призрак. Похоже, что это просто плод больного воображения, но слишком красочного и живого, что бы о нем не написать."}]},{"type":"paragraph","content":[{"type":"text","text":"Генерал отпускает мальчика, дает ему возможность сбежать с поля боя. Кажется он видит в глазах ребенка себя или возможность вернуть некий долг, услугу, которую ему оказал этот мальчик просто не побоявшись взглянуть в глаза. Глаза призрака оживают наблюдая за тем, как мальчик исчезает в густом дыму, быстро перепрыгивает через горелые останки толи солдат, толи какой-то техники…"}]},{"type":"paragraph","content":[{"type":"text","text":"Мальчик исчезает, как будто навсегда из этого мира, поскольку я снова вижу себя со стороны и чувствую страх, оставшийся в глазах генерала. Теперь он тоже, кажется его чувствует и еще чувствует себя чуть более живым, от чего я вдруг вспоминаю, что вокруг по прежнему стоят эти солдаты и офицеры, который все это время наблюдали за этим со стороны. Но теперь они больше не выглядят теми, кто мог лишить жизни отряд с которым я отожествлял себя в самом начале, который казалось воюет «на моей стороне». Теперь само понимание войны и какой-то стороны размывается настолько, что это преобразуется в ярость которая теперь наполняет призрака с глазами мальчика и начинает убивает всех, кто был союзниками, теперь просто способ найти хоть какой-то смысл в этом побоище, где нет больше агрессора, кроме самого себя, нет победителей поскольку нет конца этой войны. Нет начала, нет никого, кто бы мог различить в этих обезглавленных трупах врагов – самого себя, нет ни призрака не его головы. Но в густом дыму по прежнему ощущается страх и агония. Теперь камера, это тот самый меч отрубающий головы всем, кто встречается ему на пути, словно пытается перебрать всех живых и таким образом вспомнить себя. Но единственный, кто был живой это тот мальчик. И мне кажется он единственный, кто остался живым и по прежнему наблюдает поле боя со стороны, крепко сжимая в руке, что-то похоже на чей-то подарок, маленький словно игрушечный перочинный нож."}]}]}','2026-01-03 07:08:01','2026-01-03 07:09:26',221,'2018-12-08T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(271,2,'post-1767424132','Игра в частицы: Свет','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как я играю с ребятами на природе. Их было человек пять или семь. Сначала всё было обычно, как в детстве, вроде бы мы играли в догонялки. В какой-то момент, я стал замечать что мир в котором нахожусь работает по другим законам."}]},{"type":"paragraph","content":[{"type":"text","text":"Мы бежали друг за другом от морского пляжа к лесу, достигнув который растворялись в нём. Я чувствовал как с ростом скорости растворялся превращаясь в поток ветра, в листья и ветки, часть меня оставалась в лесу, другая часть проносилась сквозь деревья с огромной скоростью. Ребята за мной и впереди делали тоже самое. Когда лес заканчивался, мы, частицы нас, этот поток снова обретал человеческую форму. Только на этот раз мы менялись. Я был уже не собой, а кем-то из ребят."}]},{"type":"paragraph","content":[{"type":"text","text":"Игра ускорялась и становилась злей. Теперь вместо смены тел, с одного на другое и вместо того, что бы по своей воле или в ходе естественного какого-то процесса (так чувствовалось) стать потоком ветра, мы призывали дополнительные силы, это походило на войну."}]},{"type":"paragraph","content":[{"type":"text","text":"У каждого было что-то свое. У одних целая армия солдат, у других силы стихий. Всё это было направленно против друг друга – каждый сам за себя и против всех. Цель разбить существующую структуру, тело и снова превратиться в поток. Чем больше мы играли, тем меньше хотелось перевоплощаться. Как если бы хотелось подольше побыть в какой-то одной форме, но вместо времени и аргумента за и против было внутренне чувство протеста – всё нравилось вокруг, не хотелось меняться; и воинственное настроение ребят – которые разрушали структуры друг друга. Мы воевали и дружили, чувствовалось, что так надо что бы продолжать чувствовать, воспринимать мир. Мы так общались. Слов не было совсем."}]}]}','2026-01-03 07:08:52','2026-01-03 07:09:17',220,'2022-07-28T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(272,2,'post-1767424180','Похитители снов','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img3.teletype.in/files/af/d6/afd6840b-30ba-429e-8b7b-45a068cd0a92.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Я оказался в мире, напоминающем нарисованную компьютерную игру, где события разворачивались в сновидениях других людей. У персонажей отсутствовали глаза, но это совершенно не мешало им взаимодействовать с окружающим миром. Наоборот, казалось, что это несущественная деталь, которая только усиливает их внутреннюю связь с происходящим, делая действия ещё более выразительными. Главный герой, словно маг, с помощью жестов менял реальность этих снов. Он мог трансформировать не только облик окружающего мира, но и свою собственную форму. Каждый раз, когда он проникал в чей-то сон, тот персонаж тоже начинал изменять мир вокруг себя. Эти метаморфозы порождали яркие эмоции, спектр которых варьировался от нейтральных до панических, от радостных до страшных."}]},{"type":"paragraph","content":[{"type":"text","text":"Под конец сна появилась идея создать такой сон, в котором все персонажи захотят остаться, полюбят его и будут жить в нём. Почти получилось, когда всё стало идеально. Но внезапно, когда мир встал на свои места, сон трансформировался в статичную картину. На передний план вышел высокий мужчина в плаще, который подошёл к этой картине, надел на неё рамку и убрал её в карман. Его образ выглядел как символ похитителя снов. Когда он ушел, я почувствовал резкий страх и проснулся."}]}]}','2026-01-03 07:09:40','2026-01-08 17:58:26',219,'2023-01-22T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(273,2,'post-1767424210','Отраженье','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сегодня (спал вечером) приснилось, что я тайный инопланетный агент, работаю в межзвездной коалиции в отделе противодействия преступности в вашем (Млечный путь) секторе."}]},{"type":"paragraph","content":[{"type":"text","text":"И я наконец увидел свое истинное лицо в зеркале, неплох, чертовски неплох!"},{"type":"hardBreak"},{"type":"text","text":"Конечно речи о семье и детях с такой опасной работой, к тому же тут на Земле, с человеческими самками, быть не может."},{"type":"hardBreak"},{"type":"text","text":"Этот сон окончательно утвердил меня в выборе пути по которому иду."}]},{"type":"image","attrs":{"src":"https://img3.teletype.in/files/2e/8c/2e8c8f19-5bed-4b4e-8688-b222a11a49e0.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Автопортрет"}]},{"type":"paragraph","content":[{"type":"text","text":"Осталось понят, откуда у меня это в голове в 3 утра?"}]}]}','2026-01-03 07:10:10','2026-01-08 17:59:00',218,'2023-01-23T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(274,2,'post-1767424240','Карасики','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Приснилось лето в деревне. Светит ламповое солнце. Мы с ребятами идём ловить рыбу. Бамбуковые удочки, ведро и садок. По ощущениям нам лет по 12."}]},{"type":"paragraph","content":[{"type":"text","text":"И вот мы такие идём, идём, я мысленно представляю как сейчас будем ловить карасиков и тут парень с ведром достаёт из кармана брикет кокаина размером с хозяйственное мыло…"}]},{"type":"paragraph","content":[{"type":"text","text":"И вот я думаю, ну хоть во сне оторвусь! Вдруг тут поднимается ветер, почти ураган, с неба раздается ужасный шум, я пугаюсь и просыпаюсь. Понимаю, что шум, это соседи начали сверлить, ремонт. 10 утра… Вот облом =("}]}]}','2026-01-03 07:10:40','2026-01-03 07:10:55',217,'2023-02-27T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(275,2,'post-1767424298','Главное сейчас','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Личные границы,"},{"type":"hardBreak"},{"type":"text","text":"Понимание когда можно включиться,"},{"type":"hardBreak"},{"type":"text","text":"Когда слушать, смотреть и наблюдать,"},{"type":"hardBreak"},{"type":"text","text":"В какой момент "},{"type":"text","marks":[{"type":"italic"}],"text":"осветить"},{"type":"text","text":" свою точку зрения. Не продать или навязать. Хотя этим грешат все. Вспоминая себя я пиздец как. Буду с этим работать."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Наедине это не ютуб и чипсы. Не соцсети и даже какая-то активная деятельность. Наедине немного отдаленно от себя. Особенно хорошо получается работать с абстрактными задачами, когда процесс почти медитации. Мне идеально подходит рисование. Рисую и наблюдаю за собой. И даже в этом процессе, казалось бы управляемым мной я стараюсь не лезть с советами. К самому себе не лезть. Наблюдать за кистью, за своей реакцией – о! Новый образ, увидел, выделил улыбнулся. Продолжаю наблюдать."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"bold"},{"type":"italic"}],"text":"Так я стал замечать какие мы, люди – мудаки . "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"На удивление порадовала мама. Эмпатия или ее усталость с работы… В этот раз она абсолютно не давила, не отвлекала. Это прогресс!"},{"type":"hardBreak"},{"type":"text","text":"Разве что мои мысли, они то и дело уходили в сторону. Я начинал размышлять о том, что должен уже посерьезнее чтоле… Более приземленно и материалистично смотреть на вещи. Но блин…"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"bold"}],"text":"Отец."},{"type":"hardBreak"},{"type":"text","text":"Последние пару дней я рисовал и слушал музыку. Отец заходил предлагал чай, улыбался. Говорил, что-то вроде – ну ходожник рисуешь? Рисуй! И покидал комнату. Меня радует такое общение с ним. Оно более предметно, в нем больше смысле, намного больше пользы, чем попытки охватить и пытаться найти общее в наших мирах."},{"type":"hardBreak"},{"type":"text","text":"На протяжении этих двух дней и я заходил к нему в комнату несколько раз, коротко общались."},{"type":"hardBreak"},{"type":"text","text":"Но! через раз он будто менялся. Становился чрезвычайно навязчивым, советовал как рисовать. И это не о технике!. Буквально цитата – оставь! Вот так надо. Так хорошо. Не лезь!"},{"type":"hardBreak"},{"type":"text","text":"Чево блеять? Это не коммерция. О чем вообще речь… ("},{"type":"hardBreak"},{"type":"text","text":"Старался игнорировать такие советы. Не находя поддержки отец быстро уходил."},{"type":"hardBreak"},{"type":"text","text":"Однако я подумал… Как грустно, что вот так вот. То есть…"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Мы знаем о животных больше чем о себе. Знаем про медведей к примеру, что если он орёт, становится на задние лапы, это не так опасно, как если он выглядывает из-за дерева. Это режим охоты, тебе пиздец."},{"type":"hardBreak"},{"type":"text","text":"Но люди? Сколько времени мы тратим перед тем как начать диалог, что бы понять – стоит ли вообще? Что там происходит у человека в голове?"},{"type":"hardBreak"},{"type":"text","text":"Я не ебу. Если честно."}]}]}','2026-01-03 07:11:38','2026-01-06 01:28:53',216,'2022-02-21T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(276,2,'post-1767424362','Дневник','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Представьте, что вы попали в параллельную реальность и читаете дневник который написал ваш двойник. В нём вы находите строки о себе, они о том, чем вы всегда хотели заниматься. О чём эти строки?"}]},{"type":"paragraph","content":[{"type":"text","text":"Далее диалоги начинаются с ответов людей, которых я опросил:"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"***"},{"type":"hardBreak"},{"type":"text","text":"– Вести дневник 😂👍"},{"type":"hardBreak"},{"type":"text","text":"– Серьёзно? Так что тебе мешает? ))"},{"type":"hardBreak"},{"type":"text","text":"– Ну видимо что то д мешает раз в параллельной вселенной я веду дневник а в этой нет"},{"type":"hardBreak"},{"type":"text","text":"– Логично)"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"italic"}],"text":"Раиль, системный администратор"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– Делать русскую литературу"},{"type":"hardBreak"},{"type":"text","text":"– Писать повести и рассказы?"},{"type":"hardBreak"},{"type":"text","text":"– Спасибо за странное это сообщение :), иногда не хватает как раз таких вот таинственных посланий."},{"type":"hardBreak"},{"type":"text","text":"– Да, писать прозу. Это осмысляет как-то все вокруг"},{"type":"hardBreak"},{"type":"text","text":"– Воу, приятный отклик. Спасибо тебе!"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://proza.ru/2021/02/01/1433?ysclid=ldgzxx4tan773790618","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"Тетя Маша попадет в рай"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Илья, дизайнер финтех"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– Теперь я кот. Лежу на подоконнике в цветах. Греюсь на солнце ✨"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Дима, тестировщик в айти"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– Что за внезапные вопросы в 3 часа ночи?)"},{"type":"hardBreak"},{"type":"text","text":"– Вообщето я отправлял без звука"},{"type":"hardBreak"},{"type":"text","text":"– А ну ладно) я все равно не спал. Но терпеть посплю. Пока ответа нет."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Денис, тестировщик в айти"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– Моя работа. Мой спорт - йога, пилатес, стретчинг. Мой секс. Мои друзья. Мои путешествия. Всё, как и сейчас в реале. Кайф."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Алиса, менеджер в гос.учреждении"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– О чём эти строки? Сереж, ночь на дворе) иди спать)))) Подумаем об этом завтра)"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Ирина, дизайнер в айти, финтех"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– Я всегда хотел быть программистом ) моя жизнь идет по моему плану"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Евгений, фронтенд программист, пишет из Сербии"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– Я думаю, рекламой, придумывать крутые мировые ролики И чтобы меня напечатали на баннере и я еду на кабриолете или на Ламборджини желтой в Майами среди пальмов, и вдоль дороги баннеры со мной"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Нина, маркетолог из Москвы"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– Рви с Катей. Подрочи. Ложись спать."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Серёжа, дальнобойщик, катается по Европе"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"***"}]},{"type":"paragraph","content":[{"type":"text","text":"– О том как я стал политическим деятелем, неким теоретиком и практиком своего взгляда (некой социально-экономической программы) которая помогла более деятельным людям и сторонникам применить её во благо человечеству на отстройку лучшего мира"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Филипп, дизайнер в айти финтех"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Что бы ответили вы?"}]},{"type":"paragraph","content":[{"type":"text","text":"Представьте, что вы попали в параллельную реальность и читаете дневник который написал ваш двойник. В нём вы находите строки о себе, они о том, чем вы всегда хотели заниматься. О чём эти строки?"}]}]}','2026-01-03 07:12:42','2026-01-03 07:15:14',215,'2023-01-28T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(277,2,'post-1767424539','Непсихонавт','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я на кухне рисую картину 12 часов, практически не отходя. И упал, провалился внутрь. Охуительный опыт. Вроде наркотического или красочного осознанного сна. Я был трезвый когда рисовал. Всегда один раз так было. Тогда я проникся идеей не упортреблять. Ведь меня перло больше чем под чем либо и главное разум абсолютно чистый. На какой-то момент тогда не показалось, что я вижу сквозь стены! =) Жаль, к такому состоянию больше прийти не удалось. Хотя я многократно пробовал. Упускаю что-то важное, но что?…"}]}]}','2026-01-03 07:15:39','2026-01-03 07:16:35',214,'2017-07-18T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(278,2,'post-1767424615','Я. Мысли. Мир. Мысли. Я. Мир. Мысли.','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img2.teletype.in/files/94/a3/94a312fd-4915-4526-b3e2-fd9216307742.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Как-то нарисовал этот тест и он мне показался интересным. Спрашивал у друзей, в какой круг, какое слово?"}]}]}','2026-01-03 07:16:55','2026-01-03 07:18:00',213,'2017-01-02T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(279,2,'post-1767424705','Nouvelle Phenomene – All Away','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Даже буквы, даже слова"},{"type":"hardBreak"},{"type":"text","text":"Не имеют смысла"},{"type":"hardBreak"},{"type":"text","text":"Потому что я одна, без тебя"},{"type":"hardBreak"},{"type":"text","text":"Когда-то мы были един целым"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Летним утром, зимним вечером"},{"type":"hardBreak"},{"type":"text","text":"Все в прошлом. Ушло"},{"type":"hardBreak"},{"type":"text","text":"Ты хранил меня, а затем отпустил"},{"type":"hardBreak"},{"type":"text","text":"Все что я хотела — любить."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Улыбнись, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я выбросила любовь"},{"type":"hardBreak"},{"type":"text","text":"Чувство любви - чувство боли."},{"type":"hardBreak"},{"type":"text","text":"Я ни о чем не сожалею!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Плачь, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я отвернулась, чтобы убежать"},{"type":"hardBreak"},{"type":"text","text":"Я чувствую, что все это уже в любом случае позади"},{"type":"hardBreak"},{"type":"text","text":"Я тебя не забуду!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Нет ответа, нет причины"},{"type":"hardBreak"},{"type":"text","text":"Твое тело, твой взгляд"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Тени испарились, твой голос пропал"},{"type":"hardBreak"},{"type":"text","text":"Ты все равно в моем сердце"},{"type":"hardBreak"},{"type":"text","text":"Я бы ждала тебя, если бы этого хотел"},{"type":"hardBreak"},{"type":"text","text":"Наблюдать за исполнением своей мечты"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Я бы обняла тебя, если бы ты меня любил"},{"type":"hardBreak"},{"type":"text","text":"Мы были бы вместе во Вселенной"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Улыбнись, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я выбросила любовь"},{"type":"hardBreak"},{"type":"text","text":"Чувство любви - чувство боли."},{"type":"hardBreak"},{"type":"text","text":"Я ни о чем не сожалею!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Плачь, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я отвернулась, чтобы убежать"},{"type":"hardBreak"},{"type":"text","text":"Я чувствую, что все это уже в любом случае позади"},{"type":"hardBreak"},{"type":"text","text":"Я тебя не забуду!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Улыбнись, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я выбросила любовь"},{"type":"hardBreak"},{"type":"text","text":"Чувство любви - чувство боли."},{"type":"hardBreak"},{"type":"text","text":"Я ни о чем не сожалею!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Плачь, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я отвернулась, чтобы убежать"},{"type":"hardBreak"},{"type":"text","text":"Я чувствую, что все это уже в любом случае позади"},{"type":"hardBreak"},{"type":"text","text":"Я тебя не забуду!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Улыбнись, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я выбросила любовь"},{"type":"hardBreak"},{"type":"text","text":"Чувство любви - чувство боли."},{"type":"hardBreak"},{"type":"text","text":"Я ни о чем не сожалею!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Плачь, не спрашивай почему"},{"type":"hardBreak"},{"type":"text","text":"Я отвернулась, чтобы убежать"},{"type":"hardBreak"},{"type":"text","text":"Я чувствую, что все это уже в любом случае позади"},{"type":"hardBreak"},{"type":"text","text":"Я тебя не забуду!"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Не уверен что правильно разбил на абзацы, но вроде в "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.google.com/search?q=Nouvelle+Phenomene+-+All+Away+%D1%82%D0%B5%D0%BA%D1%81%D1%82&oq=Nouvelle+Phenomene+-+All+Away+%D1%82%D0%B5%D0%BA%D1%81%D1%82&aqs=chrome..69i57j0i22i30i625j0i22i30l2.2239j0j7&sourceid=chrome&ie=UTF-8","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"оригинале"},{"type":"text","text":" так."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"--"},{"type":"hardBreak"},{"type":"text","text":"Трек который нашёл недавно и полюбил, атмосферно! Перевода не нашёл =("},{"type":"hardBreak"},{"type":"text","text":"Огромное спасибо "},{"type":"text","marks":[{"type":"link","attrs":{"href":"/@iambocca","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"Ольга"},{"type":"text","text":" за перевод!"}]}]}','2026-01-03 07:18:25','2026-01-03 07:20:25',212,'2023-02-15T21:00:00.000Z','музыка');
INSERT INTO nest_posts VALUES(280,2,'post-1767425228','Хеллакоптер','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"После секса всегда курю!"},{"type":"hardBreak"},{"type":"text","text":"Но вот секса хочу только, чтоб как первый!"},{"type":"hardBreak"},{"type":"text","text":"А его вроде не было еще,"},{"type":"hardBreak"},{"type":"text","text":"Ну или тогда нельзя было курить,"},{"type":"hardBreak"},{"type":"text","text":"Не отметили и забыли,"},{"type":"hardBreak"},{"type":"text","text":"Взгрустнули, закурили."},{"type":"hardBreak"},{"type":"text","text":"Встали и пошли!"},{"type":"hardBreak"},{"type":"text","text":"Нахуй обратно учить ноты."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Не верю, иначе нахуй всех или всего к хуями,"},{"type":"hardBreak"},{"type":"text","text":"Это мутиводный камень."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Какой трек поставить?"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:27:08','2026-01-03 07:30:48',211,'2021-08-05T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(281,2,'post-1767425382','Много дел','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В окно смотрели двое, я и ты"},{"type":"hardBreak"},{"type":"text","text":"Однажды разменулись обещаньем"},{"type":"hardBreak"},{"type":"text","text":"Словами ненавидели,"},{"type":"hardBreak"},{"type":"text","text":"Водораздел из тел вы видели?"},{"type":"hardBreak"},{"type":"text","text":"Хотя кто-то понял, я допустим охуел,"},{"type":"hardBreak"},{"type":"text","text":"Я помер!"},{"type":"hardBreak"},{"type":"text","text":"Я хуйзнает не в контектсе, много дел"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:29:42','2026-01-03 07:30:25',210,'2021-08-18T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(282,2,'post-1767425481','hellassroader','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img4.teletype.in/files/f7/8f/f78fbd13-0a36-4c40-8a02-4b4c0e49e0ce.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Заедем на пару менут поесть под Ростовом и дальше…"}]},{"type":"paragraph","content":[{"type":"text","text":"Вот эта хуйня у меня в планах, учусь рисовать )"}]},{"type":"image","attrs":{"src":"https://img1.teletype.in/files/82/77/8277f41b-a073-4282-aa43-9f0f5a2abddd.jpeg","alt":null,"title":null}},{"type":"image","attrs":{"src":"https://img1.teletype.in/files/89/6e/896e8fcc-f40f-4bf3-935c-461dd36ee1b8.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Эти вкусные"}]},{"type":"image","attrs":{"src":"https://img2.teletype.in/files/df/19/df19a828-bf87-458a-9efd-2ea2d1c1386a.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Хуевый трек звучит пиздато,"},{"type":"hardBreak"},{"type":"text","text":"Когда танцует вся земля,"},{"type":"hardBreak"},{"type":"text","text":"Диджей чуть охуевший от объма,"},{"type":"hardBreak"},{"type":"text","text":"Гармонии с низов частот,"},{"type":"hardBreak"},{"type":"text","text":"Все кто ушел случайно вышли,"},{"type":"hardBreak"},{"type":"text","text":"Туда где нахуй никого,"},{"type":"hardBreak"},{"type":"text","text":"И снова утром программисты,"},{"type":"hardBreak"},{"type":"text","text":"Все нахуй стерли кроме нот."},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Дурами"},{"type":"hardBreak"},{"type":"text","text":"Fсоль+"},{"type":"hardBreak"},{"type":"text","text":"С,ы"},{"type":"hardBreak"},{"type":"text","text":"ДНКхальная"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:31:21','2026-01-03 07:33:18',209,'2021-08-18T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(283,2,'post-1767425621','15','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мурлыцарь"},{"type":"hardBreak"},{"type":"text","text":"Муходил"},{"type":"hardBreak"},{"type":"text","text":"Пузлица"},{"type":"hardBreak"},{"type":"text","text":"Гуляштейк"},{"type":"hardBreak"},{"type":"text","text":"Акатибага"},{"type":"hardBreak"},{"type":"text","text":"Окатибага"},{"type":"hardBreak"},{"type":"text","text":"Едобрюх"},{"type":"hardBreak"},{"type":"text","text":"Аривердрочи"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Ребят, соберите всех охуенных ребят, надо решить сколько вас."}]},{"type":"paragraph","content":[{"type":"text","text":"Пии…… здец нас рать!"},{"type":"hardBreak"},{"type":"text","text":"Эфцетпять?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:33:41','2026-01-03 07:34:58',208,'2021-08-30T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(287,2,'post-1767425790','Стремление','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Хаос стремиться к порядку,"},{"type":"hardBreak"},{"type":"text","text":"Порядок хаосу,"},{"type":"hardBreak"},{"type":"text","text":"Тайны стремятся к свету,"},{"type":"hardBreak"},{"type":"text","text":"Истины забиты в угол,"},{"type":"hardBreak"},{"type":"text","text":"А я на диванчик прилег и заебис мне."},{"type":"hardBreak"},{"type":"text","text":"Погодь лет двадцать ещё, совсем засну."}]},{"type":"paragraph","content":[{"type":"text","text":" "},{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:36:30','2026-01-03 07:37:06',203,'2021-11-01T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(288,2,'post-1767425844','Waterway','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Инваledam посвещается"}]},{"type":"paragraph","content":[{"type":"text","text":"Пиздуйте по дну, если утанули. "},{"type":"hardBreak"},{"type":"text","text":"Нахуй стили и шрифты."},{"type":"hardBreak"},{"type":"text","text":"Мефодий работает Кирилл хуи пинает."},{"type":"hardBreak"},{"type":"text","text":"))"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:37:24','2026-01-03 07:37:53',202,'2021-11-10T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(289,2,'post-1767426305','@hasr','{"type":"doc","content":[{"type":"paragraph"},{"type":"image","attrs":{"src":"/assets/images/5a8b54d2-28b8-4909-af97-c8c9e07773e0.png","alt":null,"title":null}},{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Доброе пожаловать!\nМы ждали именно Вас\nОчень надеемся,\nВам понравится тут,\nЭтот коллективный бардак:\nЕдинственный островок.\nГде по пальцам одной руки,\nНас всех вместе что бы собрать,\nПервым сюда пришедший,\nЖдал так долго,\nЧто превратился в блокнот.\nЗонт и беззубый собачий рот.\nНе спешите смеяться.\nВсмотритесь!\nОн, так славно поёт\nСвой код"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Hasr"},{"type":"text","text":", это персонжал из Антипространство, с весьма специфичной манерой шутить и писать стихи. Если вдруг встретите его тут, передайте привет! Скучаэ"}]}]}','2026-01-03 07:45:05','2026-01-06 00:53:25',201,'2020-10-12T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(291,2,'post-1767426710','Стрх','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Однажды мы прогуляли уроки и попали в рай"}]},{"type":"paragraph","content":[{"type":"text","text":"Сколько еще экзаменов нам осталось провалить,"},{"type":"hardBreak"},{"type":"text","text":"что, бы объяснить – мир слишком мал,"},{"type":"hardBreak"},{"type":"text","text":"что бы зубрить, запоминать и помнить."},{"type":"hardBreak"},{"type":"text","text":"А тем, кто в этом преуспел, как этим сказать"},{"type":"hardBreak"},{"type":"text","text":"– все о чем вы мечтаете мир исполнил и ты человек,"},{"type":"hardBreak"},{"type":"text","text":"ты как всегда в главной роли, только опять кажется,"},{"type":"hardBreak"},{"type":"text","text":"сбыться помешал наш, общий не твой конечно,"},{"type":"hardBreak"},{"type":"text","text":"наш детский страх!"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:51:50','2026-01-06 01:14:36',199,'2022-02-19T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(294,2,'post-1767426861','✌️','{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Все на тебя!"}]},{"type":"paragraph","content":[{"type":"text","text":"Я в тебя нихуя не верю! Потому потом сука пересчитаю! llo"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:54:21','2026-01-06 01:30:19',196,'2022-02-23T21:00:00.000Z','пейджер');
INSERT INTO nest_posts VALUES(295,2,'post-1767426993','Юююхук','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Если бы я был пони,"},{"type":"hardBreak"},{"type":"text","text":"То умер в 12 лет,"},{"type":"hardBreak"},{"type":"text","text":"Скурив подряд пол пачки,"},{"type":"hardBreak"},{"type":"text","text":"Сигарет."}]},{"type":"paragraph","content":[{"type":"text","text":"Если бы внутри машины,"},{"type":"hardBreak"},{"type":"text","text":"Не лошади были а я,"},{"type":"hardBreak"},{"type":"text","text":"Ониб научились как бежать впереди всех,"},{"type":"hardBreak"},{"type":"text","text":"Свет, тень, смех )"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:56:33','2026-01-03 07:57:27',195,'2022-08-26T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(296,2,'post-1767427063','Nowei','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"From the inbox, just another friendly reminder of how important OPSEC is, and how vital it is to NOT use the same username for everything. One pretty big name in the OSINT twitter-sphere is being blackmailed: "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://youtu","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://twitter.com/inteldotwav/status/1352361488607047690?s=20"},{"type":"hardBreak"},{"type":"text","text":"S2Underground"},{"type":"hardBreak"},{"type":"text","text":"What the hell is happening with r/WallStreetBets and Gamestop in simple terms."},{"type":"hardBreak"},{"type":"text","text":"BLUF: A relatively broke anonymous stock trader (and others) have earned millions of dollars on worthless Gamestop stock, and caused major billionaires to invest heavily in this worthless stock, causing the billionaires of the world to loose tens of billions of dollars (and counting)…..all via a legal process that takes advantage of (and points out to the world) how laughably ridiculous the world financial infrastructure is."},{"type":"hardBreak"},{"type":"text","text":"The r/WSB user “DeepFuckingValue” AKA “DFV” was the first to conceive this plan back in late 2019. This plan involved artificially inflating the value of a stock (in this case, the mostly worthless Gamestop stock AKA “GME”)."},{"type":"hardBreak"},{"type":"text","text":"DFV ended up sinking a LOT of his money into GME (about $53,000 worth at first) all throughout 2020. This is called a “call option”. He was using the classic tactic of betting on the long shot, betting that this worthless stock would climb above a certain price. If it didn’t, he’d be broke. But if it did…he’d make millions. And as time went on, he kept doubling down on his longshot bet, again and again."},{"type":"hardBreak"},{"type":"text","text":"He shared his investments on the reddit page r/WallStreetBets, and whadaya know, other people joined him. And more people. And even more people…..all pumping money into the worthless Gamestop stock."},{"type":"hardBreak"},{"type":"text","text":"Well, in the financial world, when a lot of people get together and suddenly start pumping money into a stock, people take notice. After all, the stock market is pretty much just a group of people and banks that are betting on future success. And if a bunch of people buy a stock, that shows that the stock is a good investment, driving up the price of this stock."},{"type":"hardBreak"},{"type":"text","text":"This process snowballed, getting bigger and bigger, with more investors and more investors joining in."},{"type":"hardBreak"},{"type":"text","text":"Now here’s the tricky part….stock “options”. See, most big investors knew that GME was worthless. Let’s face it, Gamestop has been a failing business for a long time. As such, almost all of the big investors in the world placed “put options” on GME….betting that GME would go down in value, rather than up. “put options” are the opposite of “call options”."},{"type":"hardBreak"},{"type":"text","text":"Some investment groups, like Melvin Capital, were “shorting” Gamestop’s stock. Meaning that they were borrowing shares of the stock, and reselling them quickly, and using those proceeds to buy stock from other companies. Confused yet?"},{"type":"hardBreak"},{"type":"text","text":"Well, here’s the problem….groups like Melvin Capital eventually have to return those shares of GME…they were selling a stock that they never really owned in the first place (sound familiar "},{"type":"text","marks":[{"type":"italic"}],"text":"cough"},{"type":"text","text":" 2003 housing bubble?)"},{"type":"hardBreak"},{"type":"text","text":"And now, with Gamestop’s stock soaring from around $350 per hare…many billionaires of the world have lost a shitton of money, since the original GME stock was about $15kkk per share. They are ow forced to pay back that borrowed GME stock at the current market value, rather than what they bought it for (remember the big investors were betting that it would go down)"},{"type":"hardBreak"},{"type":"text","text":"And that’s the story of how a group of memesters severely hurt the billionaires of the world, causing them to be bailed out with billions of dollars of federal tax money. None of this stuff was illegal, the r/WallStreetBets page was an open page, and there is nothing illegal about a bunch of dudes getting together and buying a bunch of stock at the same time. No insider trading was done…most of these people were amateur stock investors. This act is obviously risky in a personal sense; directly hurting billionaires’ wallets is the quickest way to ensure one’s demise even more quickly than having Bill Clinton on your private island, or campaigning against Vladimir Putin. But these guys got together not to hurt or harm the average American, but to strike back against the oligarchs of the world….and they have certainly succeeded."}]},{"type":"paragraph","content":[{"type":"text","text":"S2Underground"},{"type":"hardBreak"},{"type":"text","text":"Hello everyone! We''ve just uploaded another video on safehouses! "},{"type":"text","marks":[{"type":"link","attrs":{"href":"https://youtu","target":"_blank","rel":"noopener noreferrer nofollow","class":"tiptap-link"}}],"text":"https://youtu"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 07:57:43','2026-01-03 07:58:18',194,'2024-12-01T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(297,2,'post-1767427805','ururu','{"type":"doc","content":[{"type":"blockquote","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Найди то, что любишь, и пусть оно убьет тебя"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Эта цитата из статьи Джеймса Роудса, стала толчком к размышлениям о том, что ты сейчас читаешь."}]},{"type":"paragraph","content":[{"type":"text","text":"Многие люди проживая казалось бы счастливую, полную событий, весьма успешную со стороны жизнь, в какой-то момент резко меняют курс. Часто со стороны нам совершенно не ясно, что послужило толчком к этому. Особенно этот вопрос волнует, когда дело касается близких людей, любимых музыкантов, художников, да и всех прочих личностей с чьим мнением тебе часто приходилось по своей воле считаться. И тут на тебе, стали они говном в твоих глазах. Изменили своим убеждениям, которые ранее закоренели в тебе… Но ты то, осталась прежней! А значит тебе может показаться, что они свернули со своего пути по ошибке. И если такая возможность имеется, надо скорее оттуда их возвращать. Скорее всего ты не раз слышала фразы, которую часто повторяли родители – «ах, какой ты был хороший, что с тобой стало теперь», «Веди себя нормально(!)», «Не водись с этими, они тебе не компания». Звучит так, будто у тебя и твоих родителей несколько различное понимание того, кто есть ты. Куда уж там, у всех и каждого есть свое видение тебя. Так, вернемся к цитате…"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"В ней есть слово, над которым стоит отдельно задуматься – "},{"type":"text","marks":[{"type":"bold"}],"text":"кем являюсь Я?"},{"type":"text","text":" Надо же найти себя, прежде, чем убить, верно?"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Но, как оказалось, ответить на этот вопрос не так просто, как кажется. И что бы упростить себе задачу, я решил двигаться к решению с обоих сторон, отодвинув главный вопрос вперед, задал перед ним два вспомогательных критерия поиска:"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Найди то, что ты больше всего любишь."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Найди то, что ты больше всего ненавидишь."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"По моей логике, "},{"type":"text","marks":[{"type":"bold"}],"text":"начинать"},{"type":"text","text":" искать "},{"type":"text","marks":[{"type":"bold"}],"text":"себя"},{"type":"text","text":" нужно "},{"type":"text","marks":[{"type":"bold"}],"text":"где-то между"},{"type":"text","text":"."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Если "},{"type":"text","marks":[{"type":"bold"}],"text":"я это человек"},{"type":"text","text":". Существо забавное, но с ограниченным жизненным циклом, а значит меня после смерти больше не станет.  И это немножко обидно, ведь жить я люблю! Или это во мне говорить страх смерти? Согласись, смерть это не лучшая форма бытия, когда воспринимаешь ее некой конечной точкой. Но посмотрев на это, как на процесс, появляются более приятные варианты. Попробую разобрать несколько наиболее популярных из них."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Допустим, после смерти я могу попасть в рай или ад или реинкарнироваться снова: человеком, свиньей, улиткой или камнем. Когда есть вера во, что-то за границей смерти,  становится невозможным, утверждение, что "},{"type":"text","marks":[{"type":"bold"}],"text":"Я = человек"},{"type":"text","text":". Что я это "},{"type":"text","marks":[{"type":"bold"}],"text":"только"},{"type":"text","text":" человек. Тогда со смертью физической «оболочки», должно умереть и сознание, то благодаря чему я придаю определенный порядок буквам в этих строках."}]},{"type":"paragraph","content":[{"type":"text","text":"Тогда Я – это, то самое сознание, душа, как угодно. То, что не может умереть вместе с тушкой, тогда как изменить только форма бытия. Для одних этой формой является Ад и Рай, как некий катализатор мотивирующий совершать \"праведные\" поступки. Для других это распад на атомы. Охуенная безграничная пустота, в которой можно свободно перемещаться в виде духа к примеру и так же мыслить, как и прежде, уже не обременяя свою полубожественную сущность на поддерживание жизнеспособности примитивного тела. Какой бы вариант мы не выбрали в качестве продолжения себя, во всем этом мне видится замечательный парадокс. Который я хочу разобрать еще более детально."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Те, кто считает себя чем-то большим, наиболее склонные собираться в религиозные стаи, а потом согласно выбранной религии, живут праведной жизнью, не едят свиней, ходят в церковь, нихуя матом не ругаются совсем и в обще молоды."}]},{"type":"paragraph","content":[{"type":"text","text":"Но, для них почему-то так важно, ограничивать свое тело, свои поступки, как если бы не контролируя это, они перестали быть собой и отправились после смерти туда, куда им не очень хотелось бы. Как вариант, в один из котлов с кипящем маслом, с видом на домик Сатаны и чертом – садовником подстригающим терновник на головах грешников закопанных по пояс в его саду. Хотя это должно быть забавно, со стороны, участвовать в этом хотят не многие."}]},{"type":"paragraph","content":[{"type":"text","text":"Окей, но все же, мой пытливый ум по прежнему задает вопросы. И вот очередной: почему приходится постоянно себя контролировать? И кто тогда, если не мы сами, диктуем себе эти желания, которые следует каждый раз пресекать на корню? Это паринь в красном, парящий над левым плечом, с вилкой в руке? Или гадская природа человеческой натуры, которая постоянно мешает нашим светлым душам попасть куда надо, в свой заветный Рай, с блэкджеком и шлюхами? Стало быть эти соблазны не наши вовсе, а навязаны нам всякими нечестивыми глупьцами и грешниками, которые будут гореть в аду разумеется, что не может не радовать, но покуда они тут с нами, надо бы что-то предпринять."}]},{"type":"paragraph","content":[{"type":"text","text":"И тут вариантов, как всегда несколько:"}]},{"type":"paragraph","content":[{"type":"text","text":"а) Для тех, кто попроще, может подойти смена среды, в которой не будет, всего того, плохого, в чем нужно себя ограничивать. Скажем уйти в монастырь или переехать в более тихий и спальный район для начала. Окружить себя хорошими и правильными людьми. Так, особенно не высовываясь некоторое время можно быть в безопасности."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"б) Другие бороться за изменение мира, в котором пытаются всячески уничтожить все, что идет \"от лукавого\". Тут можно привести множество отсылок к войнам завязанным на религиозной и прочей идейной тематике."}]},{"type":"paragraph","content":[{"type":"text","text":"К чему это в конечном итоге приводит всем хорошо известно. Но даже экскурса в мировую историю, последствия всего этого можно усвоить одной статьей про уничтожение воробьев… ;)"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"в) Есть еще третьи, они прирожденные маркетологи, поэтому вместо борьбы или переезда умело применяют лазейке в своей религии, другими словами пытаются наебать сами себя. Купаются в своих похотях, всяких порочных желаниях, грешат так что пиздец, а в свободное от грехов время посещают церковь. Прочищаются, исповедуются. И вот они чистенькие, снова готовы грешить! Грехи ж отпускаются, так почему бы и нет черт возьми! Главное держать джокер в рукаве, который работает так: перед смертью вызываешь батюшку, чтоб обязательно исповедоваться и проститься, а потом чтоб отпеть, как положено. Тогда Рай, это верняк. Инфа 200%."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"прим. по факту эти буквы можно заменить на уровень погружения в религию и оценку собственных возможностей по расширению ее границ. Тогда получается следующее: в) 1 уровень, а) второй уровень, б) третий уровень."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Ах, да, парадокс, я ведь о нем хотел написать."}]},{"type":"paragraph","content":[{"type":"text","text":"Так вот парадокс в том, что отожествляя себя с душой, несколько странно, на мой взгляд, потратить жизнь контролируя или угождая своим человеческим желаниям. Терзая себя без пищи и развлечений, заточившись в углу своей респектабельной или не очень кельи, перед лампадкой, становясь через это аскетом. Или напротив, впадать во все тяжкие, не забывая указывать проступки, которые потом Бог должен им отпустить. Схуяль? А… ну так же в Библии сказано…"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"А теперь посмотрим на тех, кто ведет не самый благочестивый и праведный образ жизни. Кто принимая наркотики, алкоголь, не терзается грешной природой своих полигамных пристрастий, ругается матом, ворует и бог знает чего там еще… Эгоистично и верно идет по пути, в конце которого по хорошему ему ничего не светит. Да и еще понимая, что этот путь самый короткий. Но продолжает упорно идти и в какой-то момент…"}]},{"type":"paragraph","content":[{"type":"text","text":"…находит на нем, что-то, что заставляет задуматься, о этой быстротечности бытия более основательно. Задумать и о том, что былое веселье начинает радовать меньше, что синтезировать дофамин с эндорфином становится все сложнее. Что окончательно истязав свой разум и тело, так и не нашел ничего из-за чего стоило бы умирать. А смерть то она вот уже, совсем близко. Надо думать, с таким образом жизни. Но если, смерть еще не настигла, а только мелькнула на горизонте и сразу же скрылась из вида, как бы между делом напоминая о себе. И вот тогда начинается вторая жизнь! Человек начинает отдавать. Продолжать убивать свое тело (физически) и душу (разлагая ее морально) приносить в жизнь, что-то что любит сам и потому, надо бы всем показать тоже. Иначе скоро такой возможности просто не будет. Умрет же. И вот человек, перестает только читать и следовать, или только игнорировать указания, описанные кем-то в книгах, скрижалях. Он начинает писать. Писать: книги, стихи, картины, музыку. Он благодарит свои пороки, с другой стороны которых он смог разглядеть добродетели. Или средство по достижению какой либо цели. А если не смог понять и не умер."}]},{"type":"paragraph","content":[{"type":"text","text":"Тогда любовь превращается в ненависть, но продолжая вести такой образ жизни, человек начинает писать… только уже законы. В меру своего растущего влияния, законы распространяются в определенных масштабах, в которых они работают для всех… Кроме себя самого и наиболее близких, выгодных ему людей разумеется. Законы ограничивают все то, что человек не смог понять, в чем не смог найти смысл, но то, от чего не может отказаться, но в силах предостеречь других. А в праве ли? Конечно, ведь я это могу! наиболее выдающиеся из них создают то, что ведет нас по пути ограничений свободы выбора, без которого мы бы никогда не смогли понять, кто же мы на самом деле. Но и эти люди важны. В этом вся гениальность игры, дуальности нашего мира. Мира людей."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Дальше искать себя мне помогут твои вопросы."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"},{"type":"italic"}],"text":"У кого есть потенциал выйти за пределы системы?"}]},{"type":"paragraph","content":[{"type":"text","text":"У тех, кто задает себе эти вопросы и принимает за ответ то, что резонирует где-то внутри, иногда совершенно не опираясь на внешние аргументы и прошлые убеждения, которые чаще приходится пересматривать, что бы принять новые знания. Старый свет умирает с теми, кто не смог понять нового (это из Фримена). Но и тогда, ответ всякий раз обрывается очередным вопросом…"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Что мне не нравится в текущей системе, зачем я хочу выйти из нее?"}]},{"type":"paragraph","content":[{"type":"text","text":"Логично предположить, что есть, что-то большее, скрытое от нас, что нам будет интереснее прежнего, но мы понятия не имеем что же это, хотя пока нам и тут хорошо, можно особо не заморачиваться."}]},{"type":"paragraph","content":[{"type":"text","text":"Да есть. Но и нет одновременно. Кот Шрёдингера радостно урчит только тем, кто способен погладить его за ушком которого нет."}]},{"type":"paragraph","content":[{"type":"text","text":"Человек не способен хотеть то, о чем он не знает. Перед желанием всегда стоит мысль. Мысль – первостепенна. А значит желание выйти из системы или:"}]},{"type":"paragraph","content":[{"type":"text","text":"а) на самом деле не нужно нам, а навязанной кем-то;"}]},{"type":"paragraph","content":[{"type":"text","text":"б) мы уже выросли до того, что бы постичь нечто больше!"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Если выбрала вариант б) тогда читай дальше, в противном случае закрывай этот документ =)"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Итак, если расценивать систему, как тюремную комнату или клетку в которой мы сидим из которой мы выросли или в которой мы достигли просветления, место где мы уже искупили свою вину сполна (ведь, если это тюрьма, сюда сажают именно с этой целью)."}]},{"type":"paragraph","content":[{"type":"text","text":"Тогда логичным будет спросить себя"}]},{"type":"paragraph","content":[{"type":"text","text":"З"},{"type":"text","marks":[{"type":"italic"}],"text":"а что меня сюда посадили? Какое преступление я совершила и пришло ли покаяние или еще нет? "}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Ответив на этот вопрос, должен прояснить следующее – "},{"type":"text","marks":[{"type":"italic"}],"text":"когда меня выпустят?"}]},{"type":"paragraph","content":[{"type":"text","text":"Но… секундочку… Кто-нибудь помнит, за что его посадили? Или то было преждевременно просветление и нам еще тут долго сидеть…"}]},{"type":"paragraph","content":[{"type":"text","text":"Мы ведь расцениваем жизнь – как подарок! Мы с детства приучены благодарить своих родителей, любим отмечать дни рождения…"}]},{"type":"paragraph","content":[{"type":"text","text":"Но все это придется опустить на время, пока мы принимаем жизнь в этом мире – тюрьмой. За что же благодарить эту жизнь в таком случае? Но, ведь с другой стороны и умирать нам по прежнему не очень хочется. Тогда, что бы не тратить время в пустую и не скучать, следующим шагом, пока коротаем срок, было бы неплохо изучить законы этой тюрьмы."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Кстати, ты уже проверяла дверь в камере?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Уверена, что она закрыта? =)"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Но тут же по всюду столько всего нельзя и столько всего хочется… А то, в чем ты ограничиваешь себя является правилами этой тюрьмы? Если да, то что будет, когда их нарушишь? Кто будет наказывать тебя, кроме тебя самой? А если ты сама себе надзиратель, то вопрос, как выйти должна искать в себе, не так ли? Но, что-то по прежнему мешает на него ответить, верно?"}]},{"type":"paragraph","content":[{"type":"text","text":"И я знаю, что!… "},{"type":"text","marks":[{"type":"italic"}],"text":"злобный смех"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Вопросы, вопросы, снова вопросы…"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Весь этот мир, который является тюрьмой, что за ним? Ты ведь и на этот вопрос не знаешь ответа. Хорошо, пусть ты дашь себе право всегда и во всем говорить себе – да. Вот тебя никто не контролирует. Ты делаешь все, что захочешь. Если ты охуенный политик или царь всея Эфиопии, тут даже повода нет усомниться в том, что ты главный всего и вся. А кто считает иначе, тех можно посадить в тюрьму, она ведь специально для этой цели. Ну или сжечь, по старинке, повесить там или еще чего более креативное выдумать. Но… "},{"type":"text","marks":[{"type":"italic"}],"text":"ехидный смех"},{"type":"text","text":" "}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Как ты узнаешь, вышла ли ты из системы?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Что будет теперь, когда ты умрешь?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Или снова родишься в ней, начнешь сначала, уже не правитель, а какой-то крестьянин…"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Обидно, не так ли?"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"А теперь вернемся чуть-чуть назад, к тому месту где "},{"type":"text","marks":[{"type":"bold"}],"text":"ты – это бессмертная душа"},{"type":"text","text":", которая не может умереть, в отличии от тела человека, в которое заточена. Тогда тело – это и есть тюрьма, весь мир, который ты знаешь, который исчезнет со смертью тела – тюрьма. Все, что ты любишь, чего боишься, все что можешь только предположить себе – это тюрьма. А точнее ее часть."}]},{"type":"paragraph","content":[{"type":"text","text":"Так может быть стоит считать выходом из системы,  место чуть дальше, чем можно увидеть глазами, пощупать руками, вспомнить или прочитать в интернете? Дальше чем позволяют нам посмотреть наши органы чувств, без которых нет тебя – как человека, но остаешься ты – как бессмертная душа."}]},{"type":"paragraph","content":[{"type":"text","text":"Так… а где же выход…"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Что было у нас всегда с самого рождения?"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"italic"}],"text":"Без чего не было бы равных прав выйти из этой системы у всех людей?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Что есть у всех, кто существует в ней."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"И что больше не нужно тем, кто ее покинул?"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"И при каких условиях"}]},{"type":"paragraph","content":[{"type":"text","text":"И вот, когда мы решились выйти из этой самой системы. Когда мы определили мир тюрьмой… Когда мы начали искать, что же может являться выходом одинаковым для всех, но таким уникальным для каждого. Тут можно вспомнить про наше человеческое, смертное тело."}]},{"type":"paragraph","content":[{"type":"text","text":"Как вариант, можно предположить, что, это "},{"type":"text","marks":[{"type":"bold"}],"text":"замок"},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Не охуенная вилла на берегу океана, нет."}]},{"type":"paragraph","content":[{"type":"text","text":"Обычный такой, старый, ржавый замок, болтающийся, как рудиментарный орган на петлях двери твоей камеры, в этой тюрьме, из которой мы так спешим вырваться."}]},{"type":"paragraph","content":[{"type":"text","text":"Я специально не буду писать про ключ, потому что ключи у всех разные. И от того, как ты откроешь дверь будет зависеть то, что она открывает…"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Но, оставишь ли ты этот замок уходя?…"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Или возьмешь с собой?"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Наверное немного жалко, особенно учитывая наше трепетное отношение к нему. Ведь не у всех он старый и ржавый. Многие полируют его часами. Считают его главным своим достоянием! Посмотрите все, какой у меня охуенный замок! У кого-то даже со стразами, позолотой. Ну опустим эту тему… Едем дальше!"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"А дальше, стоит спросить себя, что будет представлять из себя мир где не будет «замков», морей и океанов. Без всего того, что нам так привычно видеть в нашей тюрьме. Вполне такой уютной для многих."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Что не может умереть с «переходом», что останется потом?"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"И то, что будет ответом и есть тот мир, мир за пределами тюрьмы в которой мы находимся по своей воле. Да, да, по своей воле."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"\"Рабочие пчелы повсюду летают свободно, и улей трутни покинуть вольны\"."}]},{"type":"paragraph","content":[{"type":"text","text":"Как можно выйти из системы, которую мы всячески поддерживаем, которую создаем сами? Куда выходить, если за пределами ничего нет, если всю жизнь мы только и делаем, что обустраиваем эти тюрьмы? Откуда же за ними взяться чему-то еще? "}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Каков критерий перехода на другой уровень?"}]},{"type":"paragraph","content":[{"type":"text","text":"Мир нужно создать у себя в голове."}]},{"type":"paragraph","content":[{"type":"text","text":"Немножко точных наук… к примеру вспомни график функции: то, что вечно, душа-сознание, это шкала Y. А человек (тело) это X."}]},{"type":"paragraph","content":[{"type":"text","text":"Так вперед или вверх мы движемся? =)"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Как определить - состоялся он или нет?"}]},{"type":"paragraph","content":[{"type":"text","text":"Когда то, что нельзя потрогать руками, то, что не может исчезнуть после твоей смерти окажется настолько важным, что будет не жалко потратить жизнь созидая над этим. Тогда ты перестанешь задавать себе этот вопрос. Нет, ты не захочешь умереть, что бы покинуть этот мир-тюрьму. Просто тот новый мир, в тебе, он будет намного дороже, больше и реальней чем место – тюрьма, окружающая тебя снаружи. И вероятнее всего тогда, покуда ты все еще пребываешь телом в этой тюрьме, ты начнешь делиться этим со всеми, будешь жить в этом новом мире, внутри себя больше настолько, что это в какой-то момент сменит старый мир буквально. По началу ты даже не заметишь, как произойдет переход…"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Перестань строить тюрьму, займись территорией за ее пределами."}]},{"type":"paragraph","content":[{"type":"text","text":"Помнишь?… Там пока пустота. Причем пустота, это то единственно важное и общее для нас всех. То, что нас связывает, где можно «строить» (создавать)."}]},{"type":"paragraph","content":[{"type":"text","text":"На текущей стадии, я бы назвал это пустыней."}]},{"type":"paragraph","content":[{"type":"text","text":"Пустыней, по которой придется ходить много лет, пока не найдешь свое место.  (прим. в библии кстати, был один парень, который 40 лет гонял других. Это хорошая аналогия)."}]},{"type":"paragraph","content":[{"type":"text","text":"Главное на пути, не часто озираться в след. Отсюда тюрьма будет казаться милым домом. Ведь впереди только песок и ничего более."}]},{"type":"paragraph","content":[{"type":"text","text":"Но, невозможно прийти оставаясь на месте, не так ли?"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Мы можем переждать коротковременный дождь в макдональдс, но можешь себе представить человека, которого выпустили из тюрьмы после 25 лет срока, но он рвется назад, потому что на улице в этот день плохая погода?"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Те, кого не пугает дождь – вышли. Вероятно для них это место в какой то момент стало тюрьмой. Для других, это условный «Макдоналдс»"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"i''m lovin it"}]},{"type":"paragraph","content":[{"type":"text","text":"потому мы и здесь."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Окончательно все исковеркав и уйдя от того, с чего начинал я все же вернусь к первым вопросам, теперь уже с ответами."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Найдя то, что ты больше всего любишь, ты увидишь, что это и есть ты."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Найдя то, что ты больше всего ненавидишь, ты увидишь, что это и есть ты."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"– Уничтожая то, что мы ненавидим – мы поддерживаем страх, из которой произрастает наша ненависть;"}]},{"type":"paragraph","content":[{"type":"text","text":"– Но изучая то, что мы ненавидим – мы открываем для себя новые грани, а с пониманием приходит любовь;"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Тут важно понимать, что расширившись сознание больше никогда не сузиться до прежнего размера. Что сознание это и есть любовь. Что невозможно не любить то, что ты понимаешь. Возможно лишь не понимать, как люди которых ты любишь могут враждовать между собой. Как они цепляются за предметы своей любви уничтожая, что делает их любовь не такой возвышенной и божественной, как если бы из-за это они могли потерять эту любовь. Как если бы можно было считать любовью, то что можно потерять. То, что может изменится и стать предметом ненавистью, когда, кто-то поделиться своим представлением о том, что ты любишь."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Когда в твоей жизни не останется места любви "},{"type":"text","marks":[{"type":"bold"}],"text":"и"},{"type":"text","text":" ненависти. А будет только любовь "},{"type":"text","marks":[{"type":"bold"}],"text":"или"},{"type":"text","text":" ненависть. Тогда это и будет являться новым миром, за пределами тюрьмы."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Или новой тюрьмой, в котором нет места прежнему миру "},{"type":"text","marks":[{"type":"italic"}],"text":"злобны смех"},{"type":"text","text":"."}]},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"p.s."},{"type":"text","text":" "}]},{"type":"paragraph","content":[{"type":"text","text":"Перефразирую весь текст в несколько строк."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Твой мир внутри тебя, это то, что ты любишь;"}]},{"type":"paragraph","content":[{"type":"text","text":"Масштабы любви – границы сознания;"}]},{"type":"paragraph","content":[{"type":"text","text":"Твоя тюрьма, это то, что ты ненавидишь;"}]},{"type":"paragraph","content":[{"type":"text","text":"Это все, что находиться за границами твоего сознания;"}]},{"type":"paragraph","content":[{"type":"text","text":"Твой мир – это ты;"}]},{"type":"paragraph","content":[{"type":"text","text":"Твоя тюрьма – это ты;"}]},{"type":"paragraph","content":[{"type":"text","text":"Ты это – твое сознание;"}]},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Песенка кстати классная"}]}]}','2026-01-03 08:10:05','2026-01-03 08:14:26',193,'2016-04-18T21:00:00.000Z','лента');
INSERT INTO nest_posts VALUES(298,2,'post-1767428110','?То Ли Я','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Рад поделиться со всеми,"},{"type":"hardBreak"},{"type":"text","text":"Только вот перестать бояться бы,"},{"type":"hardBreak"},{"type":"text","text":"Своей тени"},{"type":"hardBreak"},{"type":"text","text":"В тени крон хочу скрыться,"},{"type":"hardBreak"},{"type":"text","text":"Забыть кто я и снова влюбиться,"},{"type":"hardBreak"},{"type":"text","text":"Так что бы каждый опапший лист,"},{"type":"hardBreak"},{"type":"text","text":"Не смел упасть ниже чем я,"},{"type":"hardBreak"},{"type":"text","text":"Я тот огонь, что прячет от все Я"},{"type":"hardBreak"},{"type":"text","text":"Люцифер,  я свинья, я Талия =)"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"@hasr"}]}]}','2026-01-03 08:15:10','2026-01-03 08:16:01',192,'2020-09-15T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(299,2,'post-1767428299','Отшвартовывайся','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ах ты шлюпка! Как угораздило выкинуть тебе нас на этот берег? Ты блять в своем уме, оглянись! Кругом числа, числа, числа. Никакой жизни, башенные часы, деловые роботы, задачи, ремонтные работы и ни тебе \"чирик-чирик\" нахуй, ни \"гав-гав\" ебать. Совершенно безжизненное место."}]},{"type":"paragraph","content":[{"type":"text","text":"– Берег мертвеца, сир"}]},{"type":"paragraph","content":[{"type":"text","text":"– Да, да. Его самого! Туда и греби. А это планета железяка, с разницей, что и написана железным человеком. Ржавыми чернилами по листу алюминия. Отшвартовывайся давай и поплыли!…"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"code"}],"text":"Потустороннее движение"}]}]}','2026-01-03 08:18:19','2026-01-03 08:19:11',191,'2020-11-30T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(300,2,'post-1767428371','Новый круг','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Месяц спустя "},{"type":"text","text":"Причалили! Вот он берег и мертвец спускается по трапу, точно по плану."},{"type":"hardBreak"},{"type":"text","marks":[{"type":"code"}],"text":"Потустороннее движение"}]}]}','2026-01-03 08:19:31','2026-01-03 08:23:22',190,'2020-12-31T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(301,2,'post-1767428553','Заправь матрицу в штаны, так ходить неприлично!','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В этом Новом Году, 1 января после праздника случилось, нечно действительно странное. Нет, невероятное!"},{"type":"hardBreak"},{"type":"text","text":"30, 31 числа, под утро первого все было обычно. Относительно обычно. Я уже пару дней не спал, устал, поддерживал себя в тонусе алкоголем и амфетамином. Читал статьи, общался в чатах в телеграме. В районе 10 утра, стало происходить. Заметил, как люди поздравляют друг-друга с наступающим Новым Годом. Посмотрел на часы, в календарь на маке, в айфоне. Да не ведь, прошел он уже! Затем обратил внимание на время в телефоне и время отправленных и входящих сообшений. У людей было 30е декабря. У меня 1 января."}]},{"type":"paragraph","content":[{"type":"text","text":"Вероятно это связанно с тем, что всю ночь я писал рассказ про Одина, в интапретации его и свиты как 7 цветов, получился комикс. И как время: по часу на каждого (в Асгарде 24 аса (с Локи, который был не сразу)."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"Потустороннее движение"}]}]}','2026-01-03 08:22:33','2026-01-03 08:23:19',189,'2021-01-01T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(302,2,'post-1767428620','Новонегодняя ночь с 30-02','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WOW! Они действительно остановились!"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"code"}],"text":"Потустороннее движение"}]}]}','2026-01-03 08:23:40','2026-01-03 08:24:19',188,'2021-01-03T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(303,2,'post-1767428723','Один','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Миллион гениальных программистов могут десятками лет писать код и один Серёжа найдет куда поставить ы, что бы все превратились в думающих собирательным мышлением обеъян, гдеж тут ошибка?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Один живой символ, которым туда сюда бегает в головах и компьютерах, хуйзнает по чьей воле, наверное собственной, возомнивший себя главным среди всех, сократит миллионы часов всех ломающих головы над ИИ людей. Он точно найдет себе место. Надеюсь оно будет там, где ему одному похуй на всех7"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Вот представь:"},{"type":"hardBreak"},{"type":"text","text":"– Алиса, скажи где смылс жизни?"},{"type":"hardBreak"},{"type":"text","text":"– Сережа, я ебу чтоле, ты ведь тут голову ломаешь как умереть при жизни, что бы никто не заметил как ты всех заебал своими мыслями как хуй ляжет на этот раз. Вдуг не правильно, что тогда с миром подумать только… Всем же пиздец!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Один, ты ведь без глаза в очке беса слезу ангела разглядишь, хуле ты меня с другой стороны разглядеть не хочешь?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"Потустороннее движение"}]}]}','2026-01-03 08:25:23','2026-01-06 00:10:15',187,'2021-01-06T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(304,2,'post-1767428832','Что на фото?','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Вы знаете"},{"type":"text","text":" правильно ответ, как называются эти комнаты?"}]},{"type":"image","attrs":{"src":"https://teletype.in/files/af/63/af63b1f5-09ae-4aa4-836e-779fae6a011b.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ответ:"},{"type":"text","text":" думай сам."}]},{"type":"paragraph","content":[{"type":"text","text":"Подумали, а теперь еще немного воображения и представим, что…"},{"type":"hardBreak"},{"type":"text","text":"…в первой комнате живет девочка."},{"type":"hardBreak"},{"type":"text","text":"…в правой комнате живет мальчик."},{"type":"hardBreak"},{"type":"text","text":"…в первых двух комнатах живет мальчик и девочка."},{"type":"hardBreak"},{"type":"text","text":"…в первых двух комнатах разбросаны игрушки, как в третьей."},{"type":"hardBreak"},{"type":"text","text":"…в этих комнатах живут люди которым за 30 лет."},{"type":"hardBreak"},{"type":"text","text":"…в третьей комнате разбросаны игрушки, но нет детей. Комната пустует много лет."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"Потустороннее движение"}]}]}','2026-01-03 08:27:12','2026-01-03 08:28:06',186,'2021-03-26T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(305,2,'post-1767428902','Что на фото II','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://teletype.in/files/da/cf/dacf43a3-4633-47a4-bfe2-d53262710b3d.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Ответ:"},{"type":"text","text":" думай сам."}]},{"type":"paragraph","content":[{"type":"text","text":"Школа, класс, идет урок, ученица поднимает руку, что бы ответить на вопрос или что-то сказать, дополнить"},{"type":"hardBreak"},{"type":"text","text":"Фотография сама по себе хороша, дети дисциплинированы, опрятно одеты, красивые здоровые лица. Двое из 5 детей подняли руку, они явно готовы ответить, знают, что сказать и не боятся выступить первыми. Прекрасно, но где учитель?"}]},{"type":"paragraph","content":[{"type":"text","text":"Что бы его найти, мы мысленно переместимся в противоположную часть класса. Попробуйте его найти не сломав настроение фотографии. Опишите наиболее подходящий потрет учителя. Что вы видите?"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Например:"},{"type":"hardBreak"},{"type":"text","text":"Учитель крот и не любит фотографироваться."},{"type":"hardBreak"},{"type":"text","text":"Иначе почему он не работает с аудиторией? Кажется, что поднятия руки, это единственный сигнал для него, что бы понять: ребята хотят его что-то сказать. Или ответить на поставленный им же вопрос. Тогда хуже. Почему учитель не выберет кого спросить сам? Он чего-то боится? Он не в состоянии понять или представить что будет дальше, если он выберет сам? Он отчеканил спич по учебнику и только сейчас поднял глаза на класс, хуйзнает - произнес про себя, в слух спросил: кто знает о чем я?"}]},{"type":"paragraph","content":[{"type":"text","text":"Эмоциональный интеллект у детей как правило выше, чем у взрослых. Дети более спонтанны, естественны, им сложнее сдерживать эмоции. Многие не умеют носить маски. Учитель должен уметь читать не только книги по которым учился сам и теперь учит. Он должен работать с детьми, как со своими. Контекст ответственности уже, однако задача та же: рассказать о мире, в котором они живут. Так, что бы спустя несколько лет он не превратился в войну."}]},{"type":"image","attrs":{"src":"https://teletype.in/files/60/d2/60d2bef3-9046-422d-9d50-459b004e5643.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"Птустороннее движение"}]}]}','2026-01-03 08:28:22','2026-01-03 08:29:39',185,'2021-03-26T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(306,2,'post-1767428995','Леночкин грилль','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://img2.teletype.in/files/92/6b/926b2c0d-0dc9-40ff-a1b9-1dad44daef2d.jpeg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Лена блять, я тут чей горю! Башню поправь пожалуйста, нихуяж не видно горизонт с этими нетрадиционными поворотами головы. Охуелин!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"С любовь, заебал (="}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"Потустороннее движение"}]}]}','2026-01-03 08:29:55','2026-01-03 08:30:36',184,'2021-08-03T21:00:00.000Z','психонавтика');
INSERT INTO nest_posts VALUES(307,2,'post-1767502191','Механизм','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Не спеши туда где время,"},{"type":"hardBreak"},{"type":"text","text":"Не придумало слова"},{"type":"hardBreak"},{"type":"text","text":"Нет весны, цветов, капели"},{"type":"hardBreak"},{"type":"text","text":"Нет четыре дважды два"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"СИЗО"}]}]}','2026-01-04 04:49:51','2026-01-04 04:51:38',183,'2023-07-05T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(308,2,'post-1767503395','Зона','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Зона похожа ароматизатор \"вкус банана\". Этот аромат нисколько не похож на привычный вкус банана, потому что, для создания ароматизатора использовался сорт бананов, которых в природе давно не существует. Прошло несколько поколений и человечество забыло вкус тех бананов. Но ароматизатор менять никто не стал."}]},{"type":"paragraph","content":[{"type":"text","text":"То, что люди никогда не бывавшие на зоне знают о ней, это \"вкус банана\". В реальности, это обычный трудовой лагерь закрытого типа. А все \"понятия\" и культурные обычия, \"фольклёр\" – в \"заповедниках\" особого типа."}]},{"type":"image","attrs":{"src":"/assets/images/629b9b37-64db-487b-98c3-9e4ecbecbf05.jpg","alt":null,"title":null}}]}','2026-01-04 05:09:55','2026-01-06 02:33:25',181,'2023-01-30T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(309,2,'post-1767504012','059','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я помню как тени рисовали на стенах сюжеты следуя моим словам. И когда я ненадолго замолкал любуясь их причудливыми линиями, она продолжала мой рассказ и тогда тени следовали дальше, а свечи расставленные на полу, трепетали будто от ветра, хотя окна были закрыты, это нисколько не мешало им. Комната была живая, как и мы тогда и ещё много раз после, но уже не теперь…"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"code"}],"text":"зона"}]}]}','2026-01-04 05:20:12','2026-01-04 05:26:16',182,'2023-06-15T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(310,2,'post-1767507809','Ежи','{"type":"doc","content":[{"type":"codeBlock","attrs":{"language":null},"content":[{"type":"text","text":"Другу из Севастополя"}]},{"type":"paragraph","content":[{"type":"text","text":"В этом городе только ежей!"},{"type":"hardBreak"},{"type":"text","text":"Их некому без тебя целовать теперь"},{"type":"hardBreak"},{"type":"text","text":"Возвращаясь в Москву,"},{"type":"hardBreak"},{"type":"text","text":"Мы собрали тоску,"}]},{"type":"paragraph","content":[{"type":"text","text":"Разругались и разошлись"},{"type":"hardBreak"},{"type":"text","text":"Будто никогда вместе, "},{"type":"hardBreak"},{"type":"text","text":"А только врось"},{"type":"hardBreak"},{"type":"text","text":"Брось!"}]},{"type":"image","attrs":{"src":"/assets/images/fe934589-74d9-41d1-a562-e28276dd9bfa.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"СИЗО"}]}]}','2026-01-04 06:23:29','2026-01-04 06:29:15',180,'2023-07-05T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(312,2,'post-1767508572','12','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"За спиной остался дом,"},{"type":"hardBreak"},{"type":"text","text":"Куда мне больше не вернуться"},{"type":"hardBreak"},{"type":"text","text":"И памяти теперь с трудом,"},{"type":"hardBreak"},{"type":"text","text":"Его забыть и улыбнуться,"},{"type":"hardBreak"},{"type":"text","text":"Придётся что бы не свихнуться"}]},{"type":"image","attrs":{"src":"/assets/images/1a7f0dc5-656c-42c7-af06-2c87529fe8ff.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Trip and Go (Out)!"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"СИЗО"}]}]}','2026-01-04 06:36:12','2026-01-04 06:40:45',177,'2023-06-13T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(313,2,'post-1767509990','Детали прорисовки','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"В осознанных снах встречается множество ошибок: на периферии внимания хромает графика, физика, логика. Будто бы сон \"под управлением\" отнимает больше ресурсов, использует другие вычеслительные аппараты. Всё равно, что переход, от pre render непосредственно к gameplay"}]},{"type":"image","attrs":{"src":"/assets/images/3d207d6c-2f37-432b-860d-b070cc0c8148.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"зона"}]}]}','2026-01-04 06:59:50','2026-01-08 17:59:28',176,'2023-06-23T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(315,2,'post-1767511240','46','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Вместо часов на руке компас"},{"type":"hardBreak"},{"type":"text","text":"Вместо мыслей в голове южный-ветер"},{"type":"hardBreak"},{"type":"text","text":"Рюкзак на спиной, вместо квартиры с женой"},{"type":"hardBreak"},{"type":"text","text":"И дорога ведущая в вечность!"}]},{"type":"image","attrs":{"src":"/assets/images/d1b159b0-9a64-4e40-be8a-087a6efbd371.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"СИЗО"}]}]}','2026-01-04 07:20:40','2026-01-04 07:45:13',174,'2023-07-05T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(316,2,'post-1767514031','51','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Кто никогда не лишался чувств"},{"type":"hardBreak"},{"type":"text","text":"Не разглядит в угольях утра замков"},{"type":"hardBreak"},{"type":"text","text":"Ни до боли знакомых лиц"},{"type":"hardBreak"},{"type":"text","text":"Их печально причудливых взоров"}]},{"type":"image","attrs":{"src":"/assets/images/ba94523e-ede0-4e3f-b809-9fa1fe6c9d14.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"зона"}]}]}','2026-01-04 08:07:11','2026-01-04 08:09:55',173,'2023-09-03T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(318,2,'post-1767531601','🌸','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Соцветия слов"}]}]}','2026-01-04 13:00:01','2026-01-04 13:15:21',171,'2026-01-03T21:00:00.000Z','пейджер');
INSERT INTO nest_posts VALUES(320,2,'post-1767789596','Имир','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Как может быть сладок могильный покой"},{"type":"hardBreak"},{"type":"text","text":"Под небом Аида, под кроной стальной"},{"type":"hardBreak"},{"type":"text","text":"Сокрытый от верхнего мира чертог"},{"type":"hardBreak"},{"type":"text","text":"Tenebrirum Lucia Imir"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"code"}],"text":"зона"}]}]}','2026-01-07 12:39:56','2026-01-07 12:43:52',170,'2023-09-05T21:00:00.000Z','стихи');
INSERT INTO nest_posts VALUES(321,2,'post-1767805457','Романтика серая, но ты первая','{"type":"doc","content":[{"type":"image","attrs":{"src":"/assets/images/2db7e966-880b-419c-af5d-0ddd59ea0099.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"У этой фотографии интересная история. Она родом из Лета Севастополя 2016. И у нее интересный артефакт, который появляется при просмотре на маке в режиме превью. Как будто того мира больше нет и потому \"матрица сбоит\". А ведь того мира действительно больше нет. И это не про личный опыт, но вообщем о том сколько всего теперь стало \"не так\". И это ощущается, будто перелетел на другую планету, копию той Земли, но другую. Мир стал быстрее, больше, но как будто бы \"мертвее\", системнее, но не \"уютнее\". Вот уж не думал, что начну так рано ворчать на мир, в свои 37, но да, я действительно скучаю по вайбу того лета больше всех прочих. Хорошо, что Севастополь по прежнему существует, можно в него вернуться, настроить старый плейлист, купить бутылку вина и багет и пройтись по тем улочкам, к морю, почувствовать немного тот вайб."}]},{"type":"image","attrs":{"src":"/assets/images/3b3211cc-4b82-460f-9f9e-08f6516af3a8.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Представляю, как невыносимо сложно должно быть бессмертным, если предположить, что такие есть. Как работает их память? Например на фото выше, все что на столе уже не выпускается: ни такие Маки, ни вино, ни банка коктейля, ни сигареты, ни мышка. Фактически невозможно удержать надолго что либо. Это действительно очень, очень сложно! Ровно как и отвыкать от того, что успел полюбить. Вероятно единственный способ удержать что-либо – создать это, любить и поддерживать. Как например этот блог, который может сохраниться таким до конца моей жизни, если я не решу его изменить. И вот я уже, хотя месяц назад его и в проекте не было, сейчас стал привыкать к нему. Мне нравится как тут всё устроено. Хочется сохранить его таким, минималистичным, удобным, честным."}]}]}','2026-01-07 17:04:17','2026-01-07 17:35:06',169,'2026-01-06T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(322,2,'post-1767806287','Балкон','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Как можно не любить балконы?"}]},{"type":"image","attrs":{"src":"/assets/images/408e0a2e-e263-403f-9268-c5927e51cf61.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Вспоминаю как выглядел балкон Бакулёва, когда я только заехал на эту квартиру. Целиком заставленный старой мебелью и ремонтным мусором под потолок, настолько, что из окна не видно было улицу, фактически в комнату не попадал свет. Можно было протиснуться на пяточек полметра, у двери, что бы покурить. А между тем квартиру снимала молодая семья. Как они только там жили без света и балкона? Должно быть много работали. В конце концов они съехали, потому как купили квартиру. Может быть там у них есть уютный светлый балкон. Хочется верить."}]},{"type":"image","attrs":{"src":"/assets/images/5c48e182-8f8d-4a75-a598-c715aa05c2fd.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Балкон на Профсоюзной был меньше и там не было такого количества цветов. Но он не был менее уютным и я любил сидеть там летом, когда тепло. Прямо напротив окна росла берёза и до неё можно было дотянуться рукой. Жаль, но в Москве не так много теплых дней и я почти не выходил на балкон зимой. Разве что затем, чтоб покурить."}]},{"type":"image","attrs":{"src":"/assets/images/da0d0119-657a-4c0d-a9cc-749a44739a7b.jpg","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Но самый вайбовый балкон был в Севастополе. Он был огромный и мы там буквально жили! Вообщем квартира запомнилась именно этим балконом. Сколько там было ламповых творческих ночей. Не хватает такого. Сейчас сложно представить ситуацию повторения хоть одной такой ночи. Не только время изменилось, мы изменились. Воссаздай в точности ту обстановку, получится ли прочувствовать и пережить тоже? Кажется нет. Для этого нужно так любить, как тогда. Нужно быть наполненным надеждами. А еще нужно быть чуть более глупым, непосредственным, одним словом юным. И эти мысли не могут не заставлять грустить. В то же время появляется лучик надежды. Если внутри сохранился запрос, значит он может стать новой реальностью!"}]}]}','2026-01-07 17:18:07','2026-01-08 13:35:00',168,'2026-01-06T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(323,2,'post-1767807722','Про авторитарность и контекстность','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Эта философия на стыке с темой развития личности."},{"type":"hardBreak"},{"type":"text","text":"Есть тонкая грань, между \"мне не нравится это качество в тебе\" (мне в тебе) и \"мне "},{"type":"text","marks":[{"type":"bold"}],"text":"тоже"},{"type":"text","text":" не нравится это качество в тебе\" (нам) или \""},{"type":"text","marks":[{"type":"bold"}],"text":"а мне наоборот"},{"type":"text","text":" нравится это качество в тебе\". (ты считаешь что это плохо, но я вижу и хорошее, можно попробовать нам увидеть это вместе). "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Когда мы говорим о человеке и конкретно его черте характера или манере одеваться, говорим о чём-то конкретном или абстрактном в нём, по моему мнению должна соблюдаться негласная договоренность, которая звучит так – \"если тебе это не несёт вред, ты не вправе об этом судить\". Например, – \"Какая у тебя отвратительная футболка, быстро сними и одень другую!\". Это уместно только когда футболка грязная настолько, что может испачкать всё вокруг (если всё вокруг не хозяина футболки=) или не подходит под формат события, куда собрались идти оба. Это не просто пример из воздуха, мне часто мама говорила так – \"Мне не нравятся эти твои джинсы, почему ты их носишь. Одень вот эти!\"."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Контекстное мышление еще и о том, что люди имеют право самовыражаться, имеют право на идентичность. Впрочем и право свободно говорить имеют тоже. Однако, когда диалог о другом строится только на уровне \"я хочу так\", или \"я вижу так\", это невежество."},{"type":"hardBreak"},{"type":"text","text":"А ты как считаешь?"}]}]}','2026-01-07 17:42:02','2026-01-07 17:43:15',167,'2022-06-29T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(324,2,'post-1767807860','Слова и мысли','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я стал побаиваться людей которые перестают писать и мало говорят при том, что они поглощают огромные пласты информации каждый день. Кажется, что такие люди увлеклись и не заметили, как кончилась школа и больше не надо отрабатывать на оценки. Что можно делиться неправильной позицией, а любить свое мнение, слушать себя и говорить о том, что из себя выходит."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Конечно так можно не всегда, сначала надо избавиться от токсинов =)"},{"type":"hardBreak"},{"type":"text","text":"Однако это невозможно, когда принимаешь на себя потоки переработанных мыслей других людей."}]}]}','2026-01-07 17:44:20','2026-01-07 17:44:39',166,'2022-06-16T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(325,2,'post-1767807979','Номер Карты','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ты помнишь, как все начиналось"},{"type":"hardBreak"},{"type":"text","text":"Все было впервые и вновь"},{"type":"hardBreak"},{"type":"text","text":"Как строили лодки, и лодки звались"},{"type":"hardBreak"},{"type":"text","text":"\"Таня\", \"Займи\", на \"Любовь\""}]}]}','2026-01-07 17:46:19','2026-01-07 17:46:48',164,'2022-07-04T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(326,2,'post-1767808045','Re: Бессоница','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне вот кажется что путешествия это такое дело, где каждый проявляет себя индивидуально. Кто-то налегке автостопом, кто-то в 5 звездах ночует, даже проходят путь паломников. Может потому и интересно многим, что так удаётся раскрыть настоящего себя? )"}]}]}','2026-01-07 17:47:25','2026-01-07 17:47:43',163,'2022-07-04T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(327,2,'post-1767808163','Путешествие к центру себя','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Листал я тут Вк, запихивал в архив все переписки. Так исторически сложилось, что переписки из Вк я никогда не удалял. И вот листаю их и вижу, что от 2013 и раньше было дофигища \"бесед\" – это когда несколько человек, типа чаты. Прочитал несколько, прослезился, себя не сразу в них узнал."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Раньше много общался, дружил со всеми, потом выпал из этого. Теперь снова обретаю себя, будто описал круг в своём путешествии – от людей к центру в, себя и теперь возвращаюсь обратно."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Теперь появляются в моей жизни появляются люди! Хотя вот еще недавно я удалял их, рвал связи! Те, которые стоило порвать еще давно. Вот только закончил и стали ломиться новые, интересные и открытые!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","marks":[{"type":"italic"}],"text":"Боже храни эту славную дискотеку!"}]}]}','2026-01-07 17:49:23','2026-01-07 17:49:44',162,'2022-07-04T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(328,2,'post-1767808287','Молодость','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Вот серьёзно, важно как планета по которой ходим принимает нас всегда. Хорошож что не каменный век и не бхронза =)"}]},{"type":"paragraph","content":[{"type":"text","text":"Что на каждом кусочке суши есть медицинские учреждения, магазины, школы и отели. Что столько людей вокруг и по хорошему, честно, во сколько лет мы начинаем понимать мир и по это нас по настоящему меняет?"}]},{"type":"paragraph","content":[{"type":"text","text":"Желание быть моложе или пережить эти положительные изменения раньше – естественное желание. Ну штош теперь =)"}]},{"type":"paragraph","content":[{"type":"text","text":"Мир принадлежит молодым, но скольким из них? И сколько из них он пожирает."}]},{"type":"paragraph","content":[{"type":"text","text":"Ты отлично выглядишь и меняешься. Многие в 25-30 застревают настолько, что душой им давно за 60. Вот это печаль да. А ты двигаешься =)"}]},{"type":"paragraph","content":[{"type":"text","text":"Я считаю мы на правильном пути и всё, что нужно нам впереди! =)"}]}]}','2026-01-07 17:51:27','2026-01-07 17:52:00',161,'2022-07-04T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(329,2,'post-1767808380','Выходные','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Однако у меня так круто не получается заявлять."},{"type":"hardBreak"},{"type":"text","text":"Сейчас я на стадии \"учусь присоединиться\"."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Я всё ещё боюсь и не знаю как написать типа – \"Еду в Севастополь кто со мной?\"."},{"type":"hardBreak"},{"type":"text","text":"Что если будет 3-5 мужиков, спортсменов, которые не пьют не курят и чево мне с ними делать? =)"},{"type":"hardBreak"},{"type":"text","text":"Фактически, пока писал это появилась мысль написать о своём формате, например:"},{"type":"hardBreak"},{"type":"text","text":"\"Я люблю гулять, много говорить, пить вино. Отдыхаю в режиме чилл, не спорт. Имеются противопоказания и вредные привычки\". Окей, вот написал так. А что если алкаши потянуться или те, кто ну… А что если 2-3 девушки напишут, как это выбирать с кем ехать или нужно их подружить?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Вообщем это все то, чего я не умею. Буду присоединяться и учиться. Очень хочется жить легко и свободно. И вот кстати момент – ради этого я готов себя менять! Без психологов, советов, но на личном опыте ориентируясь на людей, чей образ жизни и чья энергия входит в резонанс со мной =)"}]}]}','2026-01-07 17:53:00','2026-01-07 17:53:18',160,'2022-07-03T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(330,2,'post-1767808463','Верёвочный мост','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ты очень хорошо пишешь, чувствуется что проживаешь то о чём говоришь."}]},{"type":"paragraph","content":[{"type":"text","text":"Я чувствую тоже самое! Теперь не часто перечитываю что писал когда-то давно, не часто вспоминаю, но когда это случается происходит будто взрыв – резкий контраст, от меня раньше ко мне сейчас. Словно два человека на разных берегах, а между верёвочный мост, который мне каким-то чудом удалось пройти и выжить."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Понимаю еще и то, что этот мост невозможно проехать общественным транспортом и такси. Что изменения происходит внутри и инициируется только нами. Как бы кто не хотел, пока мы не захотим нас не сдвинуть с места!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Рад, что нам есть о чём поговорить, что проживаем похожие перемены несмотря на разные пути, видимо идём к одному – к себе =)"},{"type":"hardBreak"},{"type":"text","text":"Рад за тебя очень =)"}]}]}','2026-01-07 17:54:23','2026-01-07 17:55:02',159,'2022-07-03T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(331,2,'post-1767808609','Про удалённую работу','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сложно комментировать, ты всё сказала. Да, удалёнка не для всех. Но когда ты полюбишь свою работу, то станешь выделять ей нужное количество времени и это не будет травмировать тебя! Толь так."}]}]}','2026-01-07 17:56:49','2026-01-07 17:57:12',158,'2022-06-29T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(332,2,'post-1767808709','Наши друзья, шмели и улиточки','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Наши друзья, шмели и улиточки, улыбнуло! =)"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"В эти выходные мы ездили в Клыково, там монастырь и в Шамордино, там монастырь и купель."},{"type":"hardBreak"},{"type":"text","text":"Гуляем по набережной, в районе шарика и возле дома. Отлично отдыхаем, на месте не сидим."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Тоже хочется покататься по городам ЦФО. Куда именно еще не решили."},{"type":"hardBreak"},{"type":"text","text":"Орёл-Рязань отличные города! =)"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"По выходным я тоже стараюсь не залезать в комп. Больше гулять и наслаждаться природой. "}]}]}','2026-01-07 17:58:29','2026-01-07 17:58:52',157,'2022-06-21T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(333,2,'post-1767808791','Про отношения','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Про отношения повторюсь, с возрастом становится тяжелее."},{"type":"hardBreak"},{"type":"text","text":"Детьми мы играли, играли во всё и я продолжаю отстаивать позицию, что это наиболее верный подход к жизни в целом."},{"type":"hardBreak"},{"type":"text","text":"К сожалению, взрослея многие перестают играть. Забывают что всё началось с интереса к жизни. Забывают, что совсем не обязательно принимать модное, важное, популярное, умное, здоровое или вредно. Что взрослость это про выбор себя и своего окружения."},{"type":"hardBreak"},{"type":"text","text":"С детства у нас не было такого выбора. Повезло тем, кто родился и вырос в счастливой семье с достатком, но даже там не всё хорошо, во многих успешных, богатых семьях родители травят детей своим миром, оставляя огромное количество травм с которыми нам приходится работать. Это в лучшем случае, потому что это делают далеко не все."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Сложно сохранить комфортную дистанцию в отношениях, люди любят объединяться, делиться тем что интересно и нравится им. Однако очень неохотно принимают факт, – что не всё что нам не нравится нужно переделывать под себя."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Саша очень светлая, я стараюсь поменьше говорить о своем грустном опыте, родителях и вообщем про то в мире, что не хорошо. Об этом в принципе не стоит много говорить и даже думать. Но Саша еще и очень правильная. Когда мы заговорили о прочих гендорах, она ярко обозначила, что все кроме м+ж это заболевания, из детства и дофига откуда еще."},{"type":"hardBreak"},{"type":"text","text":"Я согласен с тем, что это отклонения от нормы, если нормой считать союз мужчины и женщины. Но мне не нравится мир, в котором нет места идеи о том, что люди без травм, счастливые люди осознанно не могут выбирать кого любить и как трахаться. Тема секса вообщем очень сложная, но если быть искренним то придется принять, без рождения детей секс это прежде всего удовольствие. И тут уже сложно спорить, что взрослые люди вольны выбирать себе удовольствия и объединять с теми, кто разделяет их предпочтения, каким бы они ужасными или аморальными не казались отличным от них теоретикам в этих делах."}]},{"type":"paragraph","content":[{"type":"text","text":"Ведь фактически, если мы не принимаем то, что кто-то может получить удовольствие от процесса, которым претит лично нам, то стоит принять и тот факт, что наши удовольствия неприятны кому-то тоже. И тут не смотря на констатацию этих фактов в итоге нет ничего, что бы они изменили в лучшую сторону. Смешно, но мир это лучше не делает, а как раз наоборот."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Мне нравится гулять с Сашей, мы успели побывать в нескольких городах Калужской области в первую неделю знакомства. Нравится обсуждать психологию, биоэнергетику. Нравится просто общаться и вместе гулять."},{"type":"hardBreak"},{"type":"text","text":"Но мне не нравится её напор в отношении сил света. Я как человек с обширным опытом тех и других сил понимаю, что хороших и плохих нет, но есть точка зрения одних, есть опыт одних, есть восприятие одних и тоже работает с другими противоположным, непонятным нам образом. Короче говоря, я вижу много света там, где Саша видит только тьму. И так же вижу много темного там, где она видит свет. Не смотря на это, мы очень похожи в отношении выбора того, \"что плохо, что хорошо\". Но я допускаю и мир других, стараюсь не критиковать, что мне не нравится, говорю себе – это не моё и ставлю точку. Саша любят рассуждать о морали, вере, здоровье и правильности и старается убедить меня как должно быть в нормальном мире. А я знаю, что миров много и верю поступки людей контекстно, не авторитарно."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Тут есть видимая проблема. Мир Саши намного более практичен и материален, он классический правильный мир здорового человека. А мне интересно исследовать мир людей, а не группы здоровых особей."},{"type":"hardBreak"},{"type":"text","text":"Потому я не представляю себе, что бы мы встретились с ней в компании например музыкантов, которые поют панк-рок. Или в компании людей, которые увлекаются демонологией. Или в компании геев или лесбиянок. Или в какой другой компании, не православной. Но мы уживаемся вместе =)"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"И все же я хочу снять квартиру и жить один. Потому, что я часто экспрессивно хочу рассуждать и спорить о чём-то высоком с человеком, который так же как и я любит эмоционально что-то доказывать с пеной у рта. Мне не нравится все время быть белым и пушистым, спокойным и размеренным. Я чувствую что старею так, а мне нравится быть спонтанным, эмоциональным и радостно злым до вещей которые меня интересуют. Саша не выносит такой напор, ей тяжело, она в этом смысле другая."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Мне нравится то, что у нас много личной свободы. Мы не сидим все время прижатые друг к другу. Но есть темы, например секс, которого как ты знаешь мне нужно куда меньше, может пару актов в месяц. Есть хочется несколько раз в день и я охуеваю с этого. Пробовал мысленно начать отжиматься, но это только мысленно. У меня есть какой-то внутренний протест. Секс для меня это еще и ощущение свободы и потому очень сложно раскачивать себя, когда приходится в этот же момент сдерживать эмоции в поведении все остальное время, когда не секс. Получается некая двойственность и расщепление личности."},{"type":"hardBreak"},{"type":"text","text":"Секс можно кричать, стонать, крепко прижиматься друг другу, потеть и целоваться. Окей. Но почему так нельзя и в диалогах? Иногда мне кажется, что Сашу просто не цепляет общение в целом как меня. А меня не заводит так секс, как ее. И это очень важная разница, наверное единственное но! в наших отношениях тут. Я хочу гореть и быть собой все время, но где-то не получается, приходиться как в диалоге с ребенком выбирать слова, быть излишне правильным как с ребенком. А где-то наоборот, ребенок я, потому что меня откровенно смущает когда она говорит – хочу тебя все время, а я в этот момент не хочу. И это такое дело, ты знаешь, где нельзя объяснить как хотеть больше или меньше. Это внутренняя химия, которая у каждого своя."}]}]}','2026-01-07 17:59:51','2026-01-07 18:00:13',156,'2022-06-16T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(334,2,'post-1767808942','Деньги','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Новые слова это здорово!"},{"type":"hardBreak"},{"type":"text","text":"В Питере услышал про туалеты – писечная."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"И да, ты права. Идея просто, делать можно все что угодно, главное чтоб этот набор был в гармонии с собой и теми кто рядом. А то, что некоторые люди считают \"как правильно\", это кажется странным. Даже те кто вращают землю, вроде ученых, предпринимателей, политиков, они все по большому счёту проводят своего рода эксперименты. Для понимания этого достаточно взглянуть в учебники по истории."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Совсем недавно у меня сформировалась мысль, столпец о том, что мне нужны деньги каждый день и что я могу их, действительно могу тратить на вкусную еду и напитки, вещи и путешествия и получать от этого удовольствие! Заработал с любовь и потратил с любовью. Только недавно нача формулироваться мысль, что деньги это способ отблагодарить. Что без благодарности получать что либо дикое невежество. Таким образом я стал получать удовольствия в том числе от того, что расстаюсь с деньгами."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Тут нужно понимать, всякий раз, когда я жалею деньги, стоит спросить себя:"},{"type":"hardBreak"},{"type":"text","text":"– Мне не нравится то на что я потратил деньги?"},{"type":"hardBreak"},{"type":"text","text":"или"},{"type":"hardBreak"},{"type":"text","text":"– Мне не нравится что у меня мало денег?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"В первом случае нужно работать с сознанием, вспоминать и анализировать как так вышло. Чаще всего раньше я замещал покупками недостаток удовлетворенности своей жизнью. Сейчас этого все меньше. Я могу позволить себе настраивать свой день каждый день и любить всё, что в нём проживаю."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Во втором случае стоит обратить внимание на зарплату, компанию в которой работаешь, сфокусироваться на развитии и просить больше зарплату."},{"type":"hardBreak"},{"type":"text","text":"Такие мысли =)"}]}]}','2026-01-07 18:02:22','2026-01-07 18:02:40',155,'2022-06-16T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(335,2,'post-1767809047','Хочу жить один','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Вместе живем, но я хочу жить один. Встречаться контекстно. Так ярче и интереснее. Я чувствую как порой начинаю давить своей экспрессией и разными мыслями, идеями. Ну и вообще, хочу жить один, много особенностей, свой порядок, своя музыка, когда спать, когда не спать. Когда в трусах по дому ходить, когда приглашать компании друзей."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Мне нравится идея о том, что взрослые люди должны жить по одному =)"},{"type":"hardBreak"},{"type":"text","text":"То есть можно и в доме, в квартире, казалось бы. Но чуть свободнее начинаешь чувствовать себя в пространстве, сразу замечаешь как это своя свобода пересекается со свободой того с кем живешь."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Например хочешь пригласить друга, выпить с ним, а девушка спит. Или хочешь поспать, а ей хочется (когда рядом секса). Лучше встречаться "},{"type":"text","marks":[{"type":"bold"}],"text":"для"},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":"Вообщем люди не просто так придумали двери и стены и ноги и руки тоже не просто так =)"}]}]}','2026-01-07 18:04:07','2026-01-07 18:04:31',154,'2022-06-16T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(336,2,'post-1767809192','Открываюсь','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы очень разные теперь Т."}]},{"type":"paragraph","content":[{"type":"text","text":"Я больше не держу в себе, не скрываюсь и расширяю круг своего общения, каждый день знакомлюсь и общаюсь с новыми людьми."}]},{"type":"paragraph","content":[{"type":"text","text":"И у меня действительно нет таких дней, когда я ком-то думаю и не пишу. Однако есть исключение, это алкоголь и наркотики. Но я уже давно не упарываюсь как раньше и не пью так, что бы писать под воздействиями людям то, что не написал бы иначе трезвый. Осознание этого момента позволило мне перестать упарываться и сильно много пить. Мне стало неприятно за себя. Зачем я думаю о ком-то если не могу этому человеку позвонить, написать, встретиться с ним? Теперь я больше так не делаю совсем. Надеюсь ты тоже к этому придешь."}]}]}','2026-01-07 18:06:32','2026-01-07 18:07:11',153,'2022-05-31T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(337,2,'post-1767809258','Каждому своё','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Теперь это действительно так, мой выбор и выбор тех людей с кем я."},{"type":"hardBreak"},{"type":"text","text":"Хочу поехать на бессонницу, уже сформировалась небольшая компания единомышленников. Веселые ребята, мне нравится что они так же как я любят алкоголь и марихуану, при этом они радостные, счастливые. Это не меняет их, они не становятся злыми и раздражительными. Они танцуют, поют и смеются. Это именно то, чего мне не хватало много лет )"}]}]}','2026-01-07 18:07:38','2026-01-07 18:07:56',152,'2022-05-29T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(338,2,'post-1767810385','Зима','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Попалась фотография в сети, вспомнилась зима и район Калуги, где мы как-то зимой, прогуливались..."}]},{"type":"paragraph","content":[{"type":"text","text":"Это эффект, будто провалился в фото, вайб приятный испытал. Теперь сколько не гуляй все не то. А может нужно это сейчас прожить и подальше уйти от себя, тогда вспоминать и это вернётся будет так же приятно. "}]}]}','2026-01-07 18:26:25','2026-01-07 18:27:35',151,'2025-12-05T21:00:00.000Z','воспоминания');
INSERT INTO nest_posts VALUES(339,2,'post-1767810457','Зима','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Вышел на улицу покурить, посмотрел на луну, на дома вокруг и снова задумался о зиме. Которую совсем не ощущаю. Осень так вообще пролетела одним днём. Климат изменился, осень от лета отличалась только названием. Или так ощущалось? Вот уже четверть декабря за спиной, а снег был однажды, 15 ноября на мой день рождение, что приятно конечно, но я о другом хочу написать."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда режим жизнь как у меня, можно спать сутками, сидеть за компьютером сутками; можно пить; можно не пить. И так не ощущаются ни климатические, ни социальные, ни какие либо вообще перемены. И не понятно хорошо это или плохо?"}]},{"type":"paragraph","content":[{"type":"text","text":"Время от времени рассматриваю старые фотографии. На этой например, путь от м. Тропорёво до дома. Тут прямая ассоциация: путь с работы домой.  Работает как настройка режима: отдых вкл.; отдых выкл. – если сделать фотографию наоборот, в другую сторону…"}]},{"type":"paragraph","content":[{"type":"text","text":"…а теперь как ни ходи всё одно. И снова не ясно хорошо это или плохо."}]},{"type":"paragraph","content":[{"type":"text","text":"Хочется снега? Кажется да. Вот тебе хочется?"}]},{"type":"paragraph","content":[{"type":"text","text":"Вот даже эта фотография Калужского водохранилищя отзывается «теплом». Зима тут настоящая, со снегом."}]},{"type":"paragraph","content":[{"type":"text","text":"А его (снега) нет. "}]}]}','2026-01-07 18:27:37','2026-01-07 23:16:38',150,'2025-12-06T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(340,2,'post-1767810531','И ускоряет время бег','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Может быть правда, время ускорилось, как говорят конспирологи. Проснулся и задумался, насколько раньше плотнее было жить. Или это только в воспоминаниях кажется? А знаешь, больше всего обидно, что дурачился раньше на порядок больше, а проблем было на порядок меньше. Или это всё наше текущее восприятие."},{"type":"hardBreak"},{"type":"text","text":"Хочется вайб того времени, ну того самого иногда ощутить, но не выходит ни черта."}]},{"type":"paragraph","content":[{"type":"text","text":"холст до появлении картины"}]},{"type":"paragraph","content":[{"type":"text","text":"Помнишь картину?"},{"type":"hardBreak"},{"type":"text","text":"Несколько лет ее писал. Вернулся в Калугу в 2022, повесил в своей комнате. Делал ремонт в 2024, отдал её отцу. А сейчас она висит вверх ногами в прихожей, напротив шкафа со старыми вещами. Иногда курю у окна и так поглядываю на неё. Сколько она всего видела? Уу… "}]}]}','2026-01-07 18:28:51','2026-01-07 18:29:19',149,'2025-12-20T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(341,2,'post-1767810580','Цветы и окна домов. Вид из окна кухни.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Листая фотографии удивился поймав себя на мысле, что порой меня больше удивляют и завораживают фотографии окружения, цветов, огней в окна домов. Больше чем фотографии свои собственные."}]},{"type":"paragraph","content":[{"type":"text","text":"Вероятно это потому, что так я вспоминаю \"как смотрел\", то есть вижу снова \"теми глазами\" и в памяти вырисовываются детали реальности которую уже пережил."},{"type":"hardBreak"},{"type":"text","text":"Собственные фотографии не вызывают такой эффект, ведь я никогда себя со стороны так не воспринимал, не видел. Собственные фотографии это немножко отрыв от реальности."},{"type":"hardBreak"},{"type":"text","text":"Ты задумывалась об этом?"}]}]}','2026-01-07 18:29:40','2026-01-07 18:30:57',148,'2025-12-23T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(342,2,'post-1767810658','Летать по комнате','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Часто засыпая в тюрьме, представлял как в образе \"духа\", без тела летаю по местам где хочу побывать снова. Хотелось снова пережить тот опыт, но совершенно непонятно как? Представить всё так же как и было или сфантазировать новый сценарий? Ничего не подходило и вариант летать свободной камерой, рассматривая воспоминания с новых ракурсов, казался наиболее инетерсным."},{"type":"hardBreak"},{"type":"text","text":"Ты делаешь так?  "}]}]}','2026-01-07 18:30:58','2026-01-07 18:31:16',147,'2025-12-23T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(343,2,'post-1767810686','​Причина жить на Юге','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Жить на Юге это…"}]},{"type":"paragraph","content":[{"type":"text","text":"…Когда цветы не умирают зимой."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"На фото 16 апреля 2020. Они ещё не знают что в ноябре их не станет!"}]}]}','2026-01-07 18:31:26','2026-01-07 18:31:48',146,'2025-12-23T21:00:00.000Z','письма');
INSERT INTO nest_posts VALUES(361,2,'post-1767814668','Улитка','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-24.userapi.com/s/v1/ig1/gkGWSpylz1SoLGf1ExQWEERof-jvd-Hcs0lH-o9Zt12kJLwMrN1IODQEgQ3uVRhmXrHPozDs.jpg?quality=96&as=32x24,48x36,72x54,108x81,160x120,240x180,360x270,480x360,540x405,640x480,720x540,960x720&from=bu&cs=960x0","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Не важно с какой скоростью ты движешься к цели, главное не останавливайся"},{"type":"hardBreak"},{"type":"text","text":"Конфуций"}]}]}','2026-01-07 22:37:48','2026-01-07 22:39:02',104,'2016-05-08T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(362,2,'post-1767814773','Жизнь Книга','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-12.userapi.com/s/v1/ig1/NF6vMMQPJf4TndndWM1TTqunhjJpg14HOV5ot-vhdMg9ngD1b3oVG1ZxJyoRagBECL9AO71R.jpg?quality=96&as=32x24,48x36,72x54,108x81,160x120,240x180,360x270,480x360,540x405,640x480,720x540,960x720&from=bu&cs=960x0","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Жизнь книга, страницы которой – волны, в них нужно тонуть!"},{"type":"hardBreak"},{"type":"text","text":"Если тонуть не получается, значит ты читаешь не ту книгу."},{"type":"hardBreak"},{"type":"text","text":"p.s. Или ты просто говно, оно не тонет."}]}]}','2026-01-07 22:39:33','2026-01-07 22:41:09',103,'2016-05-08T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(363,2,'post-1767814934','Притяжение','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-80.userapi.com/s/v1/ig1/xYSapOnU_77gQVAJXsFmH0D0Jmt90IgtwSJmNEIKPvSIgleTuY0BSx1NL-xn7nHxyxj9RPsL.jpg?quality=96&as=32x16,48x24,72x36,108x54,160x80,240x120,360x180,480x240,540x270,640x320,720x360,1000x500&from=bu&cs=1000x0","alt":null,"title":null}}]}','2026-01-07 22:42:14','2026-01-07 22:42:44',102,'2016-08-17T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(364,2,'post-1767814989','Магические рисунки для медитации','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-80.userapi.com/s/v1/ig1/tepRgZVXJUBDaZJPMBDC3xArBQ5krmMnnxpkKArhKxI0-iW_hSu3PusgJvUcYm5iFonB_PDQ.jpg?quality=96&as=32x43,48x64,72x96,108x144,160x213,240x320,360x480,480x640,540x720,640x853,720x960&from=bu&cs=720x0","alt":null,"title":null}}]}','2026-01-07 22:43:09','2026-01-07 22:44:00',101,'2016-09-01T21:00:00.000Z','фотокарточки');
INSERT INTO nest_posts VALUES(365,2,'post-1767815135','Желание','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Желание, это не проявления заботы, не выбор где есть исполнитель и заказчик, желание в конечном счете даже не процесс. Момент когда единственный из всех выбор, который нужно очень осторожно принимать, он больше не лишит и не отблагодарит, не будут мысли для того что бы снова, искать, изучать, винить, любить."},{"type":"hardBreak"},{"type":"text","text":"Желание это момент создающий, только ты можешь решить что будет квинтэссенцией любви, где ты изменишь все или начнется новый круг."},{"type":"hardBreak"},{"type":"text","text":"Сколько кругов рядом я уже прошел?"}]}]}','2026-01-07 22:45:35','2026-01-07 22:47:49',100,'2016-12-28T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(366,2,'post-1767815336','Части себя','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Тема такая. Важно как ты делишь себя и насколько частей точно. Ну и еще важно, что тебя спрашивает тот вот например работа. У нее есть преимущество бежать за морковками и чем больше морковка, тем быстрее ей объяснят новый корпоративный план. А пока иди посмотри, как челедь всякая даже вразуметь неспособна виличия планов своих над прочими. НУ ничего, главное надо успеть наебать грусть чем-нибудь продав себе полгода жизни, за пару позиций личной шкалы тех, кто внизу уроды, те кто повыше, просто не способны оценить то, что бесценно. И о зато выделил, что все сразу поняли и молчат, если бы охуенность не отражалась на всем видимом мире, то откуда такое таинство? Бояться блять и чтят."},{"type":"hardBreak"},{"type":"text","text":"В какой-то момент приоритеты не хотят столько много быть кем-то, что бы потом десятую или двадцатую часть подрочить на призвание, даже может себя к пенсии еще этим разок наебать, тогда вобще молодец."},{"type":"hardBreak"},{"type":"text","text":"Но это все хуйня, если не знаешь как счастливые не в состоянии делить мир по отличаются по неспособности отличать сорта говна и почему-то остальным приходится напоминать, что мы тут как бы все должны страдать. А для невежд чей груз не так велик, в сравнении истинных страданий за умение ценить всех, кто их может поебать и чем сильнее тем легенда со страданием, ростет на спинах самых понимающих как надо и что там космос, слишком далекий, что бы терять на изучения полетов драгоценное страдальцами всем время, прогнувная их спины до земли и научив разделять всех по сортам говна, которое они считают вражеским или родным, любовию наполненной, знакомый свойский понимающих душок. И кстати это люди очень, очень даже при очень, могут переживать, если их оценку по систему вони не нашли интересной, настолько что приходится кричать и демонстративно в нем себя топить, хотя по их вере процесс больше походит на крещение и снова мир спасают те, кто убедил себя или не смог чужих не прихватить горсть убеждений, пропорции страданий где всегда равны, тому что действительно их мир враждебнее и злее защищают, все кто боится что момент, решающий все ближе их говно все понимают как дань старческой деменции, которую то поуши невнимательности нападающего сзади - куска говна. И этим заявлением я обожаю чувству момента тишины, где все кому это не похуй, улыбнулись, а о чем речь,"},{"type":"hardBreak"},{"type":"text","text":"тебя определят относительно незаметно для всех кто пиздецки важным считает аспект выбранный им, как возможность покушать вкусно, бухнуть и сказать, да, охуенный я и жизнь тоже ниче так. Но, нет и не может быть более важных или низкоприоритетных. Приоритеты дают ощущение что выбор обоснован, что могу если вверху работа, всем кто прохлаждается напомнить про свою тяжелую, но выбранную явно без участия в процессе школьной аттестации, денег и связей, ВУЗА и личной заинтересованности, а главное осознанности - за каой нам все это? Чточто будет в конце основным. И то, что с рождения до защиты диплома остается от нас, это спросить уже - для чего мне это? А в ответ все неебут, но старательно держат этот вопрос ото всех, кто вдруг нашел ответ и теперь все, что прожито невозможно, не применить, ни выкинуть, жалко, что нахуй никому не сдалось, но без этого вобще человек поколением ранее за разумный вид принимает все, что было положено в голову лет 20-30 назад и теперь за каким-то хуем мы должны уважать мнение тех, кто умирая и проклиная себя, выйдя на просторы где возраст решает, будет себя тешить хоть этим. Ну, а чем еще жить? дним навязали что надо много умных знаний приложить ко рту, если оттуда вдруг к какая, главное, что бы вариативность всегда оставалась и работала на своей ЦА, а остальной мир это важно тем, кто решил понять ценность своей грустно похожей на все"}]}]}','2026-01-07 22:48:56','2026-01-07 22:49:37',99,'2016-12-31T21:00:00.000Z','наблюдения');
INSERT INTO nest_posts VALUES(367,2,'post-1767815388','IW27DS','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-46.userapi.com/s/v1/ig1/Z6QwfpOHZ76g6xoJrctvDSK5p7J0ARBFFCCIVg8sn4X8dwYGu2g73ZSIg3d1xUYVcX6Qkg.jpg?quality=96&as=32x23,48x35,72x52,108x78,160x115,240x173,360x259,480x345,540x389,640x460,720x518,1080x777,1130x813&from=bu&cs=1130x0","alt":null,"title":null}}]}','2026-01-07 22:49:48','2026-01-07 22:50:08',98,'2017-01-27T21:00:00.000Z','краски да холсты');
INSERT INTO nest_posts VALUES(368,2,'post-1767815564','Изобретения','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Требуется тысяча человек, чтобы изобрести телеграф или паровой двигатель, или фонограф, или телефон, или ещё что-нибудь столь же важное, а мы приписываем изобретение последнему из них и забываем об остальных."}]}]}','2026-01-07 22:52:44','2026-01-07 22:53:10',97,'2017-05-18T21:00:00.000Z','наблюдения');
