INSERT INTO nest_posts VALUES(372,2,'post-1767815750','Ты как весений лист…','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ты как весений лист…"},{"type":"hardBreak"},{"type":"text","text":"Упавший раньше срока."},{"type":"hardBreak"},{"type":"text","text":"Гонимый ветром ты летишь,"},{"type":"hardBreak"},{"type":"text","text":"И свой приют находишь…"},{"type":"hardBreak"},{"type":"text","text":"На потной грузчика Зураба,"},{"type":"hardBreak"},{"type":"text","text":"Жопе."}]}]}','2026-01-07 22:55:50','2026-01-07 22:56:09',93,'2017-06-20T21:00:00.000Z','стихи');
