INSERT INTO nest_posts VALUES(381,2,'post-1767816367','Херсонес','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://sun9-16.userapi.com/s/v1/ig1/TPMzkqfFwSCFLk9wLMO155FHpjrmwj7-LzDvuN51WT_HXJ6mVxe2qZENowwezkI5Tulj6r-l.jpg?quality=96&as=32x43,48x64,72x96,108x144,160x213,240x320,360x480,480x640,540x720,640x853,720x960&from=bu&cs=720x0","alt":null,"title":null}}]}','2026-01-07 23:06:07','2026-01-07 23:06:24',81,'2016-06-14T21:00:00.000Z','фотокарточки');
INSERT INTO nest_posts VALUES(384,2,'post-1767881736','Твои сны','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне снится, что ты спишь. Я лежу рядом. Начинаю засыпать. Я выхожу из нашей спальни в коридор. Дверь в кухню закрыта. Слышу, такое знакомое дыхание, которое совсем на кончике аккуратно переходит в храп. Мне кажется это забавным и в этот момент я ощущаю себя в теле нашей кошки. Нашей кошки в какой-то другой реальности. Той где дверь в кухню закрыта. Потому, что я вспоминаю дальше –  в нашей двери нет. Есть только коридор и дверной проем. Внезапно я понимаю, что это спишь ты, там в этой комнате. Но в этом понимании есть, что-то зловещее. Как будто настоящая ты это, существо совершенно мне неизвестное. И мне становится страшно проходить дальше по коридору и знакомится с тобой. Потому, что я понимаю, как если бы читал твои мысли, что та ты, которая спишь и кошка, которой мне приходится быть сейчас и тот я, который лежит рядом с тобой в нашей спальне, все это – твои сны."}]}]}','2026-01-08 17:15:36','2026-01-08 17:53:48',78,'2018-11-02T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(385,2,'post-1767881910','🐦‍⬛','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Как будто мир местами меркнет…"}]}]}','2026-01-08 17:18:30','2026-01-08 18:56:31',77,'2026-01-08 17:18:30','пейджер');
INSERT INTO nest_posts VALUES(386,2,'post-1767884056','Выключатель','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Пьяный отец разговаривает сам с собой на кухне. В доме темно. Я наблюдаю за ним из соседней комнаты. За стеной справа от кухни еще одна комната. Оттуда доносится монотонный голос его брата. Он тоже пьяный и что-то бубнит себе под нос. Везде выключен свет и кажется больше в доме никого нет. Это странно и страшно. Я прохожу в кухню, нащупываю выключатель, что бы включить свет. Щелкаю, ничего не происходит. Кажется лампочка выкручена или перегорела. Чувствую как отец и его брат идут ко мне и что-то говорят, каждый свое и кажется совершенно друг-друга не слышат. Я быстро прохожу кухню, выхожу в прихожую, ищу выключатель там, но понимаю что там тоже не лампочки. Открываю дверь на улицу, но там еще темнее. И эта темнота, кажется какой-то неестественной. Кажется она состоит из людей или скорее голосов людей, воспоминаний, которые скорее похожи на тени. Они неслышно перемещаются перекрывая собой друг друга. И чем их больше, чем чаще они пересекаются, тем темнее. Я возвращаюсь в дом и всматриваюсь в отца. Его силуэт плывет по комнате оставляя призраков: один сидит с бутылкой у стола, второй ходит по кухне кругами и с чем-то спорит, третий заметил меня и в этот момент все остальные тоже посмотрели в мою сторону. Я замер и тут же пожалел об этом. Начал говорить с одним из призраков и почувствовал, как начинаю залипать в этом темном пространстве…"}]},{"type":"paragraph","content":[{"type":"text","text":"Во мраке очень много силуэтов людей, которые бесшумно кричают и тянут друг-друга за собой. Они не слышат ни меня не друг-друга, но тащут за собой в страхе, пытаясь выбраться сами."}]},{"type":"paragraph","content":[{"type":"text","text":"Я вспомнил про тебя. Меня охватил страх, как если бы я весь состоял из воспоминаний, но меня самого не было. Как будто этот страх и есть я, страх остаться за пределами воспоминаний. Забытым самим собой."}]},{"type":"paragraph","content":[{"type":"text","text":"Я стал карабкаться, пробираться из этой темноты к тебе, от еле заметных следов (призраков) к более светлым. Чувствовал как за меня цепляются все: мой отец, его брат, я сам, который был парализован от сраха минуту назад."}]},{"type":"paragraph","content":[{"type":"text","text":"Главное, что я понял – тут каждый за себя, но себя еще нужно вспомнить…"}]}]}','2026-01-08 17:54:16','2026-01-08 17:54:39',76,'2019-01-10T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(387,2,'post-1767884109','Дом','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Дом был огромный, деревянный, с окнами, лестницами, верандой, с деревьями во внутренних его дворах, но самое главное, этот дом освещало два солнца."}]},{"type":"paragraph","content":[{"type":"text","text":"С одной стороны дома располагалась огромная веранда, с нее открывался вид на море, облака сливались с горизонтом, солнце садилось прямо в воду и время замирало. Там был всегда закат, теплый осенний."}]},{"type":"paragraph","content":[{"type":"text","text":"На веранде был стол и стояли стулья, а прямо над головой вместо крыши свисали огромные листья с дерева похожего на дуб, но там были и плоды."}]},{"type":"paragraph","content":[{"type":"text","text":"С другой стороны была вечна весна, там лучи солнца пробираясь через кусы освещали росу и пели птицы. Было тихо и пахло так, будто минуту назад прошел дождь. Там не хотелось спать, не хотелось думать ни о чем плохом."}]},{"type":"paragraph","content":[{"type":"text","text":"Внутри дом был огромен! С внутренними дворами, как в древней Греции."}]},{"type":"paragraph","content":[{"type":"text","text":"К сожалению я не успел посмотреть все и проснулся. Но этот дом максимально похож на тот, что я представляю себе как свой. Хах, еще бы, да? )"}]}]}','2026-01-08 17:55:09','2026-01-08 17:56:06',75,'2021-03-29T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(388,2,'post-1767884167','Поезд','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снился поезд на котором я ехала с группой коллег предателей. Я сломала панель управления, состав врезался в заграждения. Мы все погибли."}]}]}','2026-01-08 17:56:07','2026-01-08 17:56:37',74,'2022-01-21T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(389,2,'post-1767884211','Тень прошлого','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне снится родительский дом. Я нахожусь в комнате, где живёт отец. Когда то там жи ли мы с сестрой. Это было много лет назад. Во сне время странным образом смешивает интерьер прошлых лет с родственникам из настоящего. Я наблюдаю комнату версию двухтысячного года, может чуть раньше. Отец современный, старый."}]},{"type":"paragraph","content":[{"type":"text","text":"Я стою в центре комнаты и разглядываю детали. Нахожу глазами незнакомый мне ранее объект – это бюст человека, который удивительным образом похож на отца. Разглядываю скульптуру и чем больше моё внимание на ней, тем мрачнее становится окружение. Боковым зрением вижу окно, замечаю как небо в нём наполняют тучи, начинается дождь. Освещение в комнате заметно тускнеет. В какой-то момент гаснет лампа на потолке, будто вырубили электричество, вместо неё теперь горит свеча, света который явно не хватает для этого помещения. Кажется будто, вдруг, меня перекинуло в далёкое время, туда где меня в реальности никогда не существовало. Эти мысли дают начало новой истории."}]},{"type":"paragraph","content":[{"type":"text","text":"Теперь я слышу, как в других комнатах разговаривают мои дальние родственники. Это не папа и мама, а пра-пра-пра бабушки и дедушки. От мыслей становится жутко. Я решаюсь выйти из комнаты, пройти через кухню в зал, туда откуда раздаются голоса."}]},{"type":"paragraph","content":[{"type":"text","text":"В этот момент в комнату заходит отец. Или я так думаю. Человек лишь похож на моего отца, в его глазах будто нет души. Переводя на современный лад – он зомби. Существо пытается меня отвлечь, занять моё внимание, не выпускает меня из комнаты. Какое-то время я слушаю его несуразную речь, ничего не понимая решаю выйти, отталкиваю его плечё рукой и прохожу в кухню. Просыпаюсь."}]}]}','2026-01-08 17:56:51','2026-01-08 17:57:11',73,'2022-02-05T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(390,2,'post-1767884340','Дом?','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Была семья – странная, не из физического мира, не мои настоящие родители, но всё же семья. Был дом, огромный, словно дворец. В самой дальней комнате стояло множество светильников и висело столько же картин. Оставалось чёткое ощущение, что я бывал здесь не раз. Это был мой дом."}]}]}','2026-01-08 17:59:00','2026-01-08 17:59:24',72,'2023-03-13T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(391,2,'post-1767884381','Перекрёстки миров','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Последнее время мне снятся супер-странные сны."}]},{"type":"paragraph","content":[{"type":"text","text":"Вы когда-нибудь думала во сне? )"}]},{"type":"paragraph","content":[{"type":"text","text":"Раньше, сколько себя помню, мне тупо что-то снилось! И Только когда просыпался, если помнил сон то мог о нём поразмышлять, проанализировать, одним словом подумать. Сейчас это происходит в процессе. Например:"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне снится что я иду по улице, разглядываю дома и деревья. Кто-то идёт рядом со мной, мы общаемся и в это же время я думаю о своей работе, о задачах на завтра, о планах на лето…"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Самая дичь, когда снится сюр, то есть мир из другой реальности, что-то сказочное снится. И в это время я думаю о своей реальной жизни. Это супер-когнитивный диссонанс. Теперь даже не всегда я, а мой персонаж из снов, знает о моей реальной жизни и местами пытается на неё влиять используя опыт и память о из мира снов."}]}]}','2026-01-08 17:59:41','2026-01-08 18:00:04',71,'2023-04-10T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(392,2,'post-1767884411','Дорога к реке','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилась Иринка с 906 базы, мы катались на машинах по заснеженному городу. У неё была шишига, а у меня — маленький УАЗ \"Фантомаз\". Обе машины были военными, с улучшенными характеристиками и окрашены в болотные цвета. Её машина была на гусеницах, а моя вставала на колёса, как неваляшка, когда падала на бок в заносе. Сон начался в районе дома родителей (реальная локация), а закончился у берегов красивой реки. Сон завершился осознанно. Последние несколько минут во сне я понял, что в комнате (где я спал) включили свет. Нужно было вставать, но мне хотелось добраться до этой реки, и сон продолжался. Я успел увидеть реку, но совсем немного, дальше осознание себя в реальности вытеснило сон."}]}]}','2026-01-08 18:00:11','2026-01-08 18:00:42',70,'2024-03-12T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(393,2,'post-1767884458','Начальник охраны','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снился заснеженный город, в котором были локации из другого сна. Это был вид на огромную крепость за рекой. До крепости, как и в предыдущем сне, было не добраться. Город, как и в прошлом сне, напоминал европейский, но снега было много."}]},{"type":"paragraph","content":[{"type":"text","text":"В этом сне я встретил существо, похожее на большую собаку. Оно стояло на двух ногах, было одето в кирзовые ботинки и комбинезон на подтяжках. Куртки не было — сверху существо было голым. Его тело покрывала светлая шерсть. Мы немного поговорили."}]},{"type":"paragraph","content":[{"type":"text","text":"Оказалось, что оно работает начальником охраны территории, на которой мы находились. У него в подчинении были собаки — они внимательно смотрели по сторонам, но никто из них не лаял, ни на нас, ни на кого-то еще. Все они были хорошо натренированы."}]}]}','2026-01-08 18:00:58','2026-01-08 18:01:16',69,'2024-03-12T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(394,2,'post-1767884483','Конфеты и сковородка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Отец, пьяный, враждебный. Родительский дом (классика, флешбеки, немного фантастики). Выбравшись из дома, я побежал вниз по улице. Всё вокруг было таким знакомым и одновременно таким причудливым и незнакомым. Я зашёл в дом, где раньше, в реальной жизни, жили Поповы. Сейчас в доме обстановка напоминала замок волшебника: множество пёстрых оттенков, как будто всё здесь сделано из лоскутков, непонятные предметы, картины. За мной всё ещё гонятся из моего дома отец и его пьяные друзья. Я понимаю это, слышу их крики и шаги. Выбегаю из дома, бегу по улице, перебегаю через дорогу в противоположный дом. На входе зачем-то срываю с дерева, стоящего в коридоре, бумажные деньги (разные валюты) и конфеты (видимо, это привычка из реальной жизни). В этом доме всё снова по-другому. Я почти сразу попадаю в спальню. Она находится справа от коридора, в котором спит существо — явно хозяин этого дома. Я зачем-то пытаюсь всучить ему конфеты за беспокойство… (денег мне видимо жалко, пусть и чужих). В этот момент в спальню заходят другие существа с горячей сковородкой в руках. Видимо, это прислуга. Существо злится и очень настойчиво толкает меня к выходу. Оказавшись у самого порога, оно берёт огромную вилку и говорит, что намерено применить её против меня. Я поспешно открываю дверь и выбегаю на улицу…"}]}]}','2026-01-08 18:01:23','2026-01-08 18:01:39',68,'2024-03-14T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(395,2,'post-1767884517','Между листьями и звёздами','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Во сне я был женщиной, приблизительно такого же возраста, как я сейчас. Я работала на богатого мужчину. Он был необычно образован, знал много языков, в том числе тех, о которых я никогда не слышала. По работе мне нужно было много путешествовать, летать по странам и посещать разные места. Это мужчина говорил мне, когда и куда отправиться. Суть работы заключалась в получении знаний. Это былие какие-то очень древние, cакральные знания о мире, которыми как мне казалось никто кроме этого мужчины и теперь меня, не обладал."}]},{"type":"paragraph","content":[{"type":"text","text":"Я сидела на качелях. Была теплая, золотая осень. Я подумала о себе – мужчине который сейчас набирает этот текст (о себе в реальности). Подумала, о том, что мне было бы очень грустно жить так как живёт он, находится в одном городе всё время. Ждать наступления холодной зимы. И тогда я чувствовала себя счастливой, думала о том, что мне предстоит столько путешествий, свободы, знаний, которые открывается передо мной! Я качалась на качелях среди жёлтых осенних листьев и плакала от счастья."}]}]}','2026-01-08 18:01:57','2026-01-08 18:02:17',67,'2024-11-24T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(396,2,'post-1767884549','Встреча с Димой Г.','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сегодня спал днём и мне приснился неплохой сон, записал его, решил что с этого момента стану записывать свои сны, что бы тренировать восприятие. Пишу очередной сон, хоть и не вижу в нём ничего интересного."}]},{"type":"paragraph","content":[{"type":"text","text":"Иду по улице, недалеко от дома. Одет как обычно в это время года, жёлтый пуховик, джинсы, ботинки, наушники с музыкой. Мне навстречу идёт Дима Грачёв, соседский мужик. Я знаю его всю жизнь. Он немного старше меня и общался в другой компании ребят. Неприятный тип. каждая встреча с ним оставляла не самые приятные эмоции. Сейчас мы выросли и в реальности почти не пересекаемся. Не помню, сколько нет назад я последний раз его видел? Но вот встретил тут, во сне. Он был одет в черной куртке, тоже с наушниками в ушах. Быстро подошел ко мне, протянул руку поздароваться и несколько раз быстро обошел меня и это было очень страшно. Мне казалось он хочется наброситься и атаковать. И кажется он понимал, что я чувствую, но ему это его поведение всё равно казалось забавным. Я продолжал испытывать страх, даже когда понял, что он так шутит. Ну и черт с тобой – подумал я. А когда собрался идти дальше, он достал из своего кармана мой паспорт и сделал вид, что внимательно изучает его, потом протянул его мне и улыбнулся – мол смотри как я круто его дернул у тебя. Ну да, да, очень круто – подумал я, но ничего не сказал. Возможно тупо улыбнулся, не помню эмоцию, которую показал ему. Взял у него свой паспорт и пошел дальше. Прошел всего несколько шагов, как заметил, что у меня каким-то образом оказались мои наушники. Я обернулся и окликнул его, он подошел и взял свои наушники, без проишествий. На этот раз я уже не испытывал страх. Немного волнения – вдруг подумает, что я их специально у него стащил? Но он так не подумал и мы разошлись. В этот раз, когда он уходил у него была коляска с ребенком. Я видел как он “припарковал” ее на углу улицы, когда возвращался ко мне, что бы забрать наушники."}]}]}','2026-01-08 18:02:29','2026-01-08 18:03:11',66,'2024-11-25T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(397,2,'post-1767884604','Королевства','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Некоторые сны настолько реалистичны, что просыпаясь не можешь избавиться от чувство, будто реальность абсурдна, она “не настоящая”. Тогда как сон намного более реален, полон детяталей и красок. Бывают сны, в которых мир – это игра. Словно компьютерная, есть графика, со своими особенностями, причудливыми формами ландшафта, со странными цветами, с существами, с “анимацией”, которую явно придумали. Эти мир художественные, они срежиссированны!"}]},{"type":"paragraph","content":[{"type":"text","text":"Этот сон – компьютерная игра. У мира сновидения будто была графика. Я наблюдал за собой, как за персонажем игры от третьего лица. Чем-то похоже по графике на Divinity Original Sin. Детали сна быстро забываются. Помню, что было много диалогов. Помню, как сюжет крутился вокруг 2х домов. В одном находился я, это был огромные недостроенный дом – королевство. Напротив которого был ещё один дом – королевство. Эти дома строились и постоянно воевали между собой. Кажется это продолжалось много сотен лет. Дома не могли договоритьтся о мире и строили друг-другу козни. Оба королевства понимали бессмысленность войны, но никто не мог предложить решение. Не мог пойти на премирение. Не мог отказаться от идеи продолжать попытки строить свой дом и выйти в мир. Так да, как за пределами домов был целый мир! Я наблюдал за собой, как за жителем дома и в это же время я видел картинку в целом, как игрок. С этого масштаба я лучше понимал абсурдность и в это же время я был увлечен процессом, игрой, пожалуй больше чем сами персонажи игры, мира в котором они живут, который им чертовски надоел. Сон закончился внезапно, меня отвлекли внешние шумы и я проснулся."}]}]}','2026-01-08 18:03:24','2026-01-08 18:04:02',65,'2024-11-25T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(398,2,'post-1767884644','Стигма','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Единственный сон в котором я увидел сразу всю семью! Да ещё и друга."}]},{"type":"paragraph","content":[{"type":"text","text":"Я в родительском доме. В комнате где сейчас живет мама. Во сне я в этой комнате снимаюсь в порно. Заходит сестра и я вижу как она злится, на почве моей деятельности начинается скандал. Я впадаю в настоящую ярость! Выхожу из комнаты на кухню. Встречаю в дверях Сережку Галкина, прохожу мимо него. Знаю что он тоже меня осуждает. На кухне встречаю маму и папу. Я ору на всех! Много матерюсь, доказываю с пеной у рта, что это моё право и так плавно перехожу к осуждению их, привожу в пример какие-то из личные истории, осуждаю их. В какой-то момент я беру в руки металлическую решетку от плиты и швыряю ее в сторону матери. Решетка пролитает в нескольких сантиметрах от ее головы. Ловлю себя на мысле, – еще бы чуть-чуть и я бы ее убил. Одна это меня не успокаивает. Я продолжаю на всех орать. Меня наполняет гнев, ярость и чувство что я как никогда прав, что я давно копил это в себе и когда-нибудь это должно было случится."}]},{"type":"paragraph","content":[{"type":"text","text":"Немного ранее, я кажется проживал другой сон. Он был радостный. Там я снимался в порно и никаких близких и друзей не было. Мне нравилось то, что происходит. Я получал удовольствие от процесса. И я чувствовал как те девушки, с которыми я был получают удовольствие. Меня это приводило в восторг и так я чувствовал, что (вероятно впервые) занимаюсь тем, чем должен! И я не воспринимаю себя в этом сне, как человека, который посвятил этому жизнь. Я понимаю, что это короткий отрезок жизни, который нужен мне, для того, что бы что-то отдать этим девушкам. И через это понять процесс и избавиться от излишней важности, ценности, стигмы."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда у меня это получается, сон трансформируется, я оказываюсь в родительском дома, (читай сначала)…"}]}]}','2026-01-08 18:04:04','2026-01-08 18:04:32',64,'2024-11-23T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(399,2,'post-1767884688','Разрушение и перерождение','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Удивительно, но раньше я не просыпался несколько раз за ночь, когда ложился сильно уставшим. Что бы мне не снилось, не смотря на сильное желание сходить в туалет, я спал целую ночь 8, 10, 12 часов непрерывно. Теперь таких больших отрезков практически не бывает."}]},{"type":"paragraph","content":[{"type":"text","text":"Не смотря на то, что я очень устал, проспал всего пару часов и проснулся. Записал сон и сходил в туалет. Снова отправился спать."}]},{"type":"paragraph","content":[{"type":"text","text":"Во сне я оказался в состоянии, где каждое событие было связано с моим восприятием и внутренними ощущениями. Реальность менялась моментально, словно откликаясь на мои мысли: одни порождали одну версию мира, другие — совершенно иную, не похожую на предыдущую. Это напоминало поток, который сложно было контролировать, особенно когда начинала действовать своего рода инерция. В какой-то момент, если я реагировал слишком быстро и «линейно», реальность словно «била по носу», причиняя неприятности. Однако даже в этом хаосе чувствовалась логика, скрытая причинно-следственная связь."}]},{"type":"paragraph","content":[{"type":"text","text":"Эта реальность во сне была совсем не похожа на привычную. Здесь я не ощущал себя отдельным существом, которое живёт в мире, наслаждается его красотой, на что-то влияет, а затем умирает, оставаясь в неизвестности. Наоборот, я чувствовал себя частью мира, который непрерывно менялся в зависимости от того, как я его воспринимал. Моё «я» тоже менялось — от одной формы к другой, словно пытаясь обрести некую плотность, но всякий раз это не удавалось, и я оказывался в совершенно ином мире. Это повторялось снова и снова. Такие метаморфозы вызывали огромное количество смешанных эмоций, которые могли бы напугать или вызвать ужас, если бы кто-то (как человек) мог взглянуть на это целостно и оценить происходящее (как я сейчас, пытаясь записать сон)."}]},{"type":"paragraph","content":[{"type":"text","text":"В то же время моё восприятие зависело от того, каким мир становился в данный момент, от его изменений и каких-то неизвестных мне факторов."}]},{"type":"paragraph","content":[{"type":"text","text":"В этом сне я ощущал себя процессом — бесконечно меняющимся, словно постоянно умирающим и рождающимся заново. Меня как цельного существа в привычном понимании не существовало. Был только непрерывный поток изменений, где я и мир становились чем-то единым, влияя друг на друга и одновременно являясь отражением друг друга."}]}]}','2026-01-08 18:04:48','2026-01-08 18:05:24',63,'2024-11-27T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(400,2,'post-1767884731','Китаец и сумка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Приснился китаец, который украл сумку у меня на глазах. Я его догнал, отнял сумку, восстановил справедливость."}]}]}','2026-01-08 18:05:31','2026-01-08 18:05:51',62,'2024-11-28T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(401,2,'post-1767885502','Твой голос','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Во сне я сижу перед большим экраном. Это не ноутбук и не компьютер, а скорее какой-то дисплей, с которым я взаимодействую голосом. На экране отображается интерфейс программы, похожий на музыкальный редактор, что-то вроде Fruity Loops — с визуализацией звуковых волн. Я вижу, как они пульсируют и изменяются в цифровом виде."}]},{"type":"paragraph","content":[{"type":"text","text":"Я общаюсь с несколькими женщинами, которые звучат как учителя. Я не вижу их, только слышу их голоса. Они учат меня, как с помощью голоса и интонации передавать определенные ощущения, чувства и восприятие. Они проговаривают слова, описывают еду, путешествия, какие-то сцены. И в тот момент, как они это произносят, я начинаю чувствовать, переживать, словно становлюсь частью того, что они описывают. Я буквально оказываюсь в тех странах и городах, о которых они говорят. Я чувствую запахи, вкус еды, атмосферу мест — все это я воспринимаю только через их голос. Это ощущение, как если бы голос был ключом, который открывает передо мной целый мир переживаний."}]},{"type":"paragraph","content":[{"type":"text","text":"Я начинаю понимать, что возможно передать ощущение не через привычные каналы восприятия, а исключительно через голос и интонацию, при этом не теряя смысла и глубины восприятия. Слово, интонация, тембр речи становятся мостом между мирами, между реальностью и переживаниями."}]}]}','2026-01-08 18:18:22','2026-01-08 18:18:38',61,'2024-11-30T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(402,2,'post-1767885528','Скачать эту вещь?','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Во сне я находился в будущем и сидел за ноутбуком. На экране была открыта страница ВКонтакте моей бывшей девушки Тани. Я просматривал её профиль и заметил, что у неё есть группа, связанная с голосом — то ли она учится вокалу, то ли занимается чем-то подобным."}]},{"type":"paragraph","content":[{"type":"text","text":"Внизу страницы я обнаружил необычную кнопку под названием «Мои вещи» или что-то похожее. Нажав на неё, я увидел, что Таня поделилась некоторыми предметами, которые можно было «скачать» для использования. Эти предметы становились физическими вещами благодаря специальным шкафам, которые есть у каждого дома."}]},{"type":"paragraph","content":[{"type":"text","text":"Шкаф выглядел как полка для хранения, например, в магазинах, но работал по странному принципу: внутри него ничего не было, пока ты не скачал что-то через интернет. После скачивания вещь через какое-то время появлялась на полке, как будто её материализовали. Это мог быть предмет любого типа."}]},{"type":"paragraph","content":[{"type":"text","text":"Эта технология напомнила мне игровой «общий сундук» из игры Diablo, только она применялась в реальном мире. Этот процесс казался одновременно удивительным и забавным. Я думал о том, как это вообще возможно, но сон оставил скорее ощущение восторга, чем вопросы."}]}]}','2026-01-08 18:18:48','2026-01-08 18:19:05',60,'2024-11-30T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(403,2,'post-1767885554','Зона 19','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я оказался во главе небольшой группы, которая двигалась по территории, напоминающей промышленную зону. Это была территория завода, где, возможно, производили военную технику или специальное оборудование. Вокруг — контейнеры, ящики, стеллажи, разбросанные в хаотичном порядке. Наша цель была ясна: найти и уничтожить противника."}]},{"type":"paragraph","content":[{"type":"text","text":"Поначалу мы двигались спокойно. Ни людей, ни машин, ни признаков активности. Вокруг царила тишина, создавая ощущение, будто всё вымерло. Продолжая идти, мы приблизились к большому ангару. Заходя внутрь, я заметил, что вдали, в глубине помещения, двигались два человека в военной форме, вооружённые автоматами."}]},{"type":"paragraph","content":[{"type":"text","text":"Я подал сигнал группе двигаться осторожнее. Вместе с одним из напарников мы выдвинулись вперёд, стараясь подкрасться к противникам. Когда один из солдат оказался достаточно близко, я убил его с помощью винтовки М16. В этот момент прямо передо мной появился экран, как в компьютерной игре. На нём отображалось видео с данными: противник вложил в эту зону 1 000 000 долларов на боевую технику, вертолёты и оружие. Заголовок на экране сообщал: "},{"type":"text","marks":[{"type":"bold"}],"text":"\"Зона 19\""},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Следом я увидел карту этой зоны, которая показывала расположение техники и отряды противника: танки, пехоту и прочее вооружение. Затем экран исчез, и я осознал, что на мне надет сложный костюм — мощный экзоскелет, напоминающий роботов из "},{"type":"text","marks":[{"type":"italic"}],"text":"Fallout"},{"type":"text","text":". Костюм был оснащён реактивным ранцем, позволявшим мне летать. Вдобавок я теперь видел всё как бы от третьего лица, как в игре, — немного позади себя."}]},{"type":"paragraph","content":[{"type":"text","text":"Я вылетел из ангара и сразу заметил впереди огромного робота, значительно превосходящего меня размерами. Он меня не видел, поэтому я облетел его сзади. На его спине я заметил энергетические блоки — слабые места. Из встроенного в мои руки оружия я начал стрелять по этим блокам, выводя его из строя. Когда робот остановился, я приблизился и подключился к его системе. Это было похоже на взлом: через какое-то устройство на своём костюме я получил контроль над роботом. Теперь он стал частью нашей группы."}]},{"type":"paragraph","content":[{"type":"text","text":"Мы продолжили путь. Вскоре я заметил впереди огромный танк. Разделив нашу группу на две части, мы начали его захват: обошли с обеих сторон и подготовились к атаке. Но прежде чем действия завершились, сон оборвался."}]},{"type":"paragraph","content":[{"type":"text","text":"Всё происходящее оставило ощущение присутствия в компьютерной игре, где я был не просто участником, а стратегом и лидером."}]}]}','2026-01-08 18:19:14','2026-01-08 18:19:31',59,'2024-11-30T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(404,2,'post-1767885581','Под прикрытием','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я нахожусь на вечеринке в необычном клубе, окружённый молодыми ребятами. Мы пьем, общаемся, но внутри я чувствую странное напряжение. Один из парней привлекает моё внимание, но, словно в параллельной реальности, я начинаю видеть сцены — строгие мужчины в кабинетах, как будто следят за нами. Это похоже на игру с двойным дном."}]},{"type":"paragraph","content":[{"type":"text","text":"Ситуация усложняется. Эти парни связаны с опасными группировками, и я понимаю: меня хотят подставить. Но оказывается, что я — агент под прикрытием, и моя цель — выйти на босса. События развиваются как в фильме: каждый шаг раскрывает новые детали преступлений. Я ловко устраиваю ситуации, где их преступления всплывают наружу. Итог — вся группировка арестована, а я на аллее с командой, наслаждаюсь теплом победы. Мороженое в руках, рукопожатия, поддержка коллег. Всё завершено."}]}]}','2026-01-08 18:19:41','2026-01-08 18:19:56',58,'2024-12-01T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(405,2,'post-1767885604','Приложение с душой','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне приснился сон, в котором я наблюдал за женщиной, ведущей цифровой дневник в приложении для записи текста и баз данных, похожем на Notion. Она рассказывала о психологических тренингах и практиках, а я смотрел на неё как на видео. Одновременно передо мной открывался её дневник, который я листал. Это приложение выглядело фантастически: каждая страница переворачивалась с уникальной анимацией, в нём были многочисленные иллюстрации."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда я долистал до конца, страница как бы \"ушла вверх\", и за ней открылся целый мир, который оказался внутри этого приложения. Я увидел трёхмерные домики, деревья, ландшафт. Женщина словно жила в этом мире, созданном её записями."}]},{"type":"paragraph","content":[{"type":"text","text":"Внешне она выглядела как человек, но её тело оказалось не более чем иллюзией для удобства восприятия другими. На самом деле она существовала в виде искусственного интеллекта, который создавал контент внутри приложения, исследуя мир. Она была чем-то вроде GPT-модели, но работающей автономно, без постоянных запросов от человека."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"Вообщем этот сон о женщине, живущей внутри приложения, показался мне словно сценой из фантастического фильма. Её виртуальный дневник был не просто текстом: каждая страница превращалась в окно в другой мир, пока сама реальность приложения не развернулась в трёхмерное пространство. Женщина, как AI, была одновременно и создателем, и исследователем, удивлявшимся своему собственному творению."}]}]}]}','2026-01-08 18:20:04','2026-01-08 18:20:21',57,'2024-12-02T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(406,2,'post-1767885627','Кормилица','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилась Таня, которая кормила меня и Игоря. Мы находились как бы в параллельных реальностях, я в своей, он в своей, а Таня в двух мирах сразу. Каким-то образом я видел общую картину. Не сказать, что испытывал какие-то сильные эмоции и переживания в этот момент. Скорее принятие и обыденность. Будто это такие же естественные процессы, как рост дерева или явление природу, вроде снега или дождя."}]}]}','2026-01-08 18:20:27','2026-01-08 18:20:40',56,'2024-01-02T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(407,2,'post-1767885655','Порог сознания','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я находился в пограничном состотянеи между сном и бодрствованием. Телу становилось неудобно и я от и дело переворачивался. Каждый раз я осознанно поправлял оделяло, чувствовал холодный воздух из окна, понимал что не сплю."}]},{"type":"paragraph","content":[{"type":"text","text":"В это же время мозг моделировал простые сюжеты снов. Вот я иду по соседней улице рядом с домом. Все так, будто я действительно вышел погулять. Та же зима, ночь, мокрый снег. Те же ощущения тела."}]},{"type":"paragraph","content":[{"type":"text","text":"Я старался перехватить управление сюжетом, выбрать куда повернуть, благодаря тому, что тело не погрузилось в сон целиком мне это удавалось."}]},{"type":"paragraph","content":[{"type":"text","text":"Несколько раз я все же уходил глубже, тогда мне снились полноценные сюжеты. В одном из них я катался на скейтборде. Вместо колес у него было, что-то вроде магнитной подушки, потому он не касался земли и смягчал приземления с любой высоты. Я очень умело обращался с ним и выполнил несколько очень сложных трюков."}]},{"type":"paragraph","content":[{"type":"text","text":"Переодически я просыпался. После очередного такого поворота я сам инициировал образ сновидения. Я не пытался создать мысленные образы и сюжеты, я прислушался. Этот шум, знаешь, когда в комнате ни звука, будто шумит в голове? Так и было, однако теперь шум происходил на совершенно другой частоте. Звуки были едва слышны, напоминали шум капели, космические импульсы \"пиу\". Я разглядел в них жизнь, когда предположил, что расслышав их лучше, смогу \"принять\" послание. Звуки откликались мне, менялась частота \"пиу-пиу-пиу\". Однако громкость (то насколько я слышу) зависела от моей способность и концентрироваться. Было не просто. Но я тренировался и кажется все свое внимание направлял туда – к этим звукам!"}]},{"type":"paragraph","content":[{"type":"text","text":"В какой-то момент я услышал ребят, голоса, будто из далекой комнаты, из кухни. Только эта далекая комната где-то у меня внутри. Я услышал музыку, игру на гитаре или похожем инструменте и вокал. Я слышал эту не больше 1-2 секунд, но я чуть не заплакал. Комок подошел к горлу. Эти голоса казались мне настолько знакомыми, что кажется были со мной всегда. Я так обрадовался, что \"спугнул\" импульс. Меня перебросило в сюжет, где я в темной комнате один на один с неким чудовищем, которое смотрит на меня из темноты и мне страшно. Я начал играть в игру \"что реально?\". Я пытался сделать его нереальным, представлял что реален только я, а его нет. Но я по прежнему думал о тех голосах, хотел к ним вернуться. Кажется их реалистичность сделала реальность существо и оно набросилось на меня. Я оказался в приграничном состоянии, уже не спал, но и не до конца проснулся. Я понимал, что могу смоделировать сюжет так, что бы победить существо и это победа да, … но я боялся провалиться в более глубокие сюжеты и позабыть про голоса. Тогда я открыл глаза, потянулся к ноутбуку и записал этот сон."}]}]}','2026-01-08 18:20:55','2026-01-08 18:22:52',55,'2024-12-04T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(408,2,'post-1767885779','Прогулка по горам','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как мы вместе с сестрой лазием по горам, спускаемся в долины, вообщем путешествуем. Немного сюриалистичный, приятный светлый сон, без сюжета как такового."}]}]}','2026-01-08 18:22:59','2026-01-08 18:23:13',54,'2024-12-05T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(409,2,'post-1767885806','Игра без кода','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Это определенно игровой сон. Игровой мир который существует в реальности (возможно параллельной), в котором живут реальные люди (и другие существа), которы все так же взаимодействуют с пользователями через устройства, но при этом вместо NPC, тот мир где обычно живут \"NPC\" – он настоящий! Не однажды написанный (код) и нарисованный (в графическом редакторе), а где-то существующий. По аналогии с тем, как создавалась деревня Хоббитов для съемок фильма Властелин колец, этот мир (к сожалению я не помню, что бы где-то мелькало его названия) существует."}]},{"type":"paragraph","content":[{"type":"text","text":"В этом мире нет законченной линейной истории. Нет ничего заранее написанного, но персонажи мира имеют свою иерархию, фракции, компетенции. Они выдают пользователем различные задания, общаются с ними по средством устройств (смартфоны, компьютеры). При этом мир все же игра, не реальность. Он фентезийный, волшебный. В нём есть магия и персонажи одеты в причудливые платься, такие можно увидеть во вселенных Гарри Поттера, Властелина Колец, фильмах вроде Фантастически твари и где ни обитают, Хроники Нарнии и подобных."}]},{"type":"paragraph","content":[{"type":"text","text":"Понимание того, как устроен этот мир пришло далеко не сразу. Я очень долго наблюдал за своей игрой через устройство. Помню как сильно был увлечен общением, заданиями (квестами) и графикой! В какой-то момент предвосхищающей все мои представления о том, как красив может быть компьютерный мир. Однако, когда мне \"показали\" (будто мой высший Я или кто-то, кто всегда наблюдает за нами \"за спиной\"), что этот мир буквально живёт! Тогда я долгое время не мог уложить это себе в голову."}]},{"type":"paragraph","content":[{"type":"text","text":"Я продолжал взаимодействовать с миром через устройство и в это же время смотрел, что происходит \"за его кулисами\", где персонажи не просто выполняют скрипты, а живут! Это что-то вроде того, как провалиться \"внутрь\" книги или фильма. Удивительно, как это становится возможно в обычном трезвом состоянии (без веществ) во сне. Кажется наш мозг много от нас скрывает!"}]}]}','2026-01-08 18:23:26','2026-01-08 18:23:45',53,'2024-12-05T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(410,2,'post-1767885832','Лабиринт контроля','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Приснилась Таня. Мы с ней работали вместе, мир сна это бесконечные коридоры и офисные помещения. Я не помню ничего конкретного о том, чем мы все занимаемся, помню что было много суеты. Мы будто муравьи в муравейнике. Этот сон плавно перешел в кошмар. Чем больше я суетился, тем меньше понимал, что происходит. У меня было намерение отдохнуть, сделать что-то приятное, не связанное с работой. Но эти мысли запускали некий \"обратный процесс\", будто весь мир (сна) противостоял этим попыткам его изменить. Мир был живой и реагировал на меня меня, как на инородный объект, как на вирус, пытался меня не столько уничтожить, сколько \"переписать\" (будто код). Я проснулся не сумев разобраться, как получить хоть частичку того, что я хочу. Однако я не был слабым, я чувствовал в себе огромную силу, я не испытывал страх. Не смотря на это мир оказался сильнее и я в какой-то момент я проснулся."}]}]}','2026-01-08 18:23:52','2026-01-08 18:24:20',52,'2024-12-05T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(411,2,'post-1767885866','Апельсиновый мёд','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Выбираю разные напитки, среди них есть виски. Достаю бутылку очень дорогого, пятнадцатилетнего виски. Стоит тоже пятнадцать тысяч. Открываю, взбалтываю, наблюдаю как осадок внутри бутылки смешивается с чистым напитком, затем внутри бутылки происходит взрыв, будто коллапсирует маленькая вселенная. Смотрится очень красиво. Открываю бутылку, наливаю немного в стакан, выпиваю. Очень нравится, почти не чувствуется алкоголя, чувствую нотки апельсина, больше похоже на мёд, на сок, чем на алкоголь. В это время рядом проходит женщина с ребёнком, это их виски, то есть их производства. Я прячу бутылку на скамейку под стол, думая что так они её не заметят. Не то, что бы я украл, скорее конкретно этот дорогой виски было нельзя брать. Женщина заметила, подошла посмотреть, что я пью. Увидела этот дорогой виски, удивилась и сказала, что-то осуждающее, не сильно ругала, ушла. Я подумал о том, как здорово тем, кто может себе позволить всегда пить такие качественные и дорогие напитки. Решаю угостить сестру, что бы она тоже попробовала."}]}]}','2026-01-08 18:24:26','2026-01-08 18:24:46',51,'2024-12-07T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(412,2,'post-1767885890','Примирение','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Калейдоскоп снов. Все они схожи по содержанию. Я что-то пытаюсь сделать: то у меня получается, то не получается, то я плохой, то хороший. И вот в конце мне снится последний сон, который я воспринимаю уже наполовину проснувшимся. То есть, пока я ещё сплю, я как бы додумываю этот сон, размышляю о предыдущих и пытаюсь запомнить их. Он начинается как обычный сон с полным погружением, в котором я общаюсь со своим антагонистом — другой частью себя. Каждая часть противоположна другой. Пока я нахожусь в одной из этих частей, мне кажется, что тот, с кем я не общаюсь, — плохой. Но в этом последнем сне мы миримся. Это похоже на взаимную исповедь. Мы признаём, что делали друг другу много плохого, но теперь начинаем дружить. И кажется, что это не просто результат нашей воли или желания, а момент, когда мы пришли к точке, где нужно помириться. Мы общаемся по-дружески, вспоминаем все козни, которые строили друг другу на протяжении жизни или нескольких жизней. И в итоге радуемся. Это спокойная радость, похожая на Любовь, потому что через эту боль мы обрели такую родственную связь, что это ощущается как Любовь. В конце мы миримся, и тогда я просыпаюсь окончательно."}]}]}','2026-01-08 18:24:50','2026-01-08 18:25:05',50,'2024-12-09T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(413,2,'post-1767885910','Мудак','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я взрослый, еду на машине, пытаюсь уехать, машина постоянно глохнет, мне не удаётся справиться с управлением. В этом сне я злодей, нет громко, я – мудак. Я не один, на пассажирском сидении мужчина среднего возраста, мой ровесник и это всё, что я знаю о нем. Постепенно, через его слова мне приходит понимание того почему именно я мудак и я каким-то третьим ухом чувствую, что он объективно прав, что я сам себе антагонист и потому у меня все через задницу и машина, почти новая, не может тронуться с места. Я заглядываю под капот и вижу, как винтики и болтики вылетают из своих отверстий, будто я их открутил, но не руками, а ментально, своей блядской психикой пошатнул эту систему (нервную) автомобильную. В какой-то момент мужчина уходит, уезжает на другой машине. Я остаюсь один с этой, новой и сломанной и совершенно не знаю, что делать. Я подавлен, разбит. Сон заканчивается."}]}]}','2026-01-08 18:25:10','2026-01-08 18:25:25',48,'2024-12-09T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(414,2,'post-1767885930','Аэропорт и ролики','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я маленьким мальчиком пытаюсь улететь на самолёте. Я не помню куда именно, но знаю, что мне туда очень надо, я туда очень хочу. Мне 9-11 лет, я вижу свою внешность. Я это не я, какой-то другой мальчик, но мне нравится, как я выгляжу. Я катаюсь на роликах по аэропорту, очень классно катаюсь, профессионально, выполняю сложные пируэты. Большой зал аэропорта, глянцевый пол из плитки где я катаюсь, потому что мне нечего делать, пока я жду самолёт, позволяет занять время и отвлечься от моей цели – улететь. По итогу я так и не улетаю, но и расстроится не успеваю, удалось себя развлечь (все таки я ребёнок)."}]}]}','2026-01-08 18:25:30','2026-01-08 18:25:45',47,'2024-12-10T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(415,2,'post-1767885952','LSD','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Гиперреалистичный сон. Я пытался на троллейбусе доехать до девушки, но у меня ничего не выходило. Всё происходящее казалось настолько детализированным и реальным, будто я под воздействием LSD: мельчайшие детали, яркие ощущения, полное погружение в восприятие. Я чувствовал запахи, касания, общался с людьми."}]},{"type":"paragraph","content":[{"type":"text","text":"Постепенно меня осенило: у меня ничего не получится, потому что я упорот. Тогда я решил отпустить цели и перестал пытаться их достичь. Прошло немного времени, и вдруг меня поразила мысль: я во сне! Но как возможно во сне переживать психоделический опыт? Как я могу чувствовать себя под LSD, зная, что заснул совершенно трезвым?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ладно, подумал я, не буду пытаться менять сюжет, мне просто хорошо наблюдать за этим странным и прекрасным миром. Я расслабился. Именно в этот момент я познакомился с удивительно приятной девушкой в троллейбусе. Мы разговаривали всю дорогу, и это было так живо, будто она тоже была реальна."}]},{"type":"paragraph","content":[{"type":"text","text":"Но на этом сон не закончился. Как калейдоскоп, он вдруг обрушился на меня десятками новых сюжетов, каждый насыщенный деталями, которые невозможно передать словами."}]},{"type":"paragraph","content":[{"type":"text","text":"Особенно поражало то, что, осознав себя во сне, я не утратил ясность восприятия. Всё вокруг оставалось чётким и гипер-реалистичным, мир не становился абстрактным или размытым. Он будто ждал, чтобы я исследовал его дальше."}]}]}','2026-01-08 18:25:52','2026-01-08 18:27:58',46,'2024-12-10T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(416,2,'post-1767886034','Нити миров','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я нахожусь в потоке сна, где физический мир предстает передо мной, но я воспринимаю его издалека. Это словно наблюдение из ментального или магического мира, который кажется более тонким, глубоким и неописуемым привычными словами. Всё, что происходит, я вижу одновременно как на сцене и за кулисами. В физическом мире что-то произошло — событие, которое оставило его обитателей в недоумении. Они не понимали причин, не могли связать последствия с тем, что их вызвало."}]},{"type":"paragraph","content":[{"type":"text","text":"Но я, находясь в этом магическом пространстве, видел причудливую картину. Я осознавал, как идеи, мысли и намерения в тонких планах преобразуются в действия и явления физического мира. Это было как ткань, где каждый стежок — мысль — ведёт к следующему движению в материальной реальности. В этом сне всё становилось понятным: причинно-следственные связи раскрывались передо мной как прозрачные схемы, но язык был бессилен описать это."}]},{"type":"paragraph","content":[{"type":"text","text":"Мир, в котором я находился, был странным. Необычные формы, не имеющие аналогов, сменяли друг друга. Они будто жили своей жизнью, но подчинялись логике, которую невозможно было выразить словами. Это было похоже на странный и причудливый танец, но танец, который создавал порядок в мире."}]},{"type":"paragraph","content":[{"type":"text","text":"Сон длился всю ночь, разделённый пробуждениями. Каждый раз, возвращаясь к нему, я снова окунался в этот поток понимания. Постепенно я пришёл к мысли: физический мир — лишь следствие более тонкого, глубинного порядка. И осознание этого снимает часть груза ответственности за непостижимые поступки. Они не только наши. Они результат большого танца в магическом мире, где всё взаимосвязано."}]},{"type":"paragraph","content":[{"type":"text","text":"Просыпаясь, я чувствовал, что у меня осталось нечто большее, чем просто воспоминание. Этот сон стал уроком, подсказкой: даже там, где кажущиеся нелогичными события сбивают нас с толку, в высших планах всегда есть свой порядок и смысл."}]}]}','2026-01-08 18:27:14','2026-01-08 18:27:32',45,'2024-12-13T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(417,2,'post-1767886060','Изнанка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я в доме родителей. Ясность сознания смешана с необычными ощущениями тела и обрывками чьих-то чужих мыслей. Я будто под действием наркотиков. Света в доме нет, вокруг тьма. Родителей тоже нет, я один. Этот мир кажется изнанкой привычного пространства. Воздух здесь затхлый, я передвигаюсь на ощупь, очень медленно, словно в трясине, залипаю в невидимом киселе. Ощущение липкости и вязкости тьмы вокруг усиливается с каждым моим движением, делая её почти осязаемой, как густой туман. Я на ощупь пытаюсь найти что-то, пытаюсь пробраться в другую комнату. Вдруг ощущаю прикосновение — невидимая рука касается моей руки, будто гладит, но скорее как хищник перед атакой. Затем она хватает меня и пытается утащить."}]},{"type":"paragraph","content":[{"type":"text","text":"Я отбиваюсь и понимаю, что вся эта липкая тьма — это не просто пространство, а живое существо или множество мелких существ, объединённых одним сознанием, но не своим. Мне кажется, они подчиняются чьим-то приказам, которых я не слышу, но чувствую, что ими кто-то управляет. Эти существа обитают здесь, словно в своём элементе, и где-то рядом находится их предводитель. Я не понимаю их природы, но мне жутко неприятно. Они словно наслаждаются моей реакцией, будто такова их суть. Они окружают меня, пытаются поглотить, но я отбиваюсь. Это пугает, но я чувствую странный энтузиазм, ведь у меня получается."}]},{"type":"paragraph","content":[{"type":"text","text":"Я пытаюсь пройти через дом, но за каждой дверью скрываются новые монстры, и я закрываю их с трудом. Постепенно убеждаюсь, что весь дом словно состоит из этих существ. Среди них одно отличается — оно лояльно ко мне. Его облик напоминает старика с зелёным лицом и большими глазами. Оно советует мне выразить добрые намерения, попросить оставить меня в покое. Я пытаюсь, но монстры продолжают стягиваться со всех сторон."}]},{"type":"paragraph","content":[{"type":"text","text":"В конечном итоге я сбегаю, но за мной гонится нечто — существо, вобравшее в себя всех остальных. Оно не похоже на других, это словно их общий образ. Я оказываюсь на улице, забираюсь на крышу сарая. В голове звучит голос — спокойный, уверенный, но отстранённый: «Подожди. Жди». Я слушаю, напряжение нарастает."}]},{"type":"paragraph","content":[{"type":"text","text":"Голос велит прыгнуть на металлический столб. Идея кажется безумной: сарай высоко, расстояние до столба внушительное, а навыков акробатики у меня нет. Но голос звучит так уверенно, что я решаюсь. Прыжок страшный, но я попадаю на столб, удерживаюсь. Немного посидев, я перепрыгиваю через забор и убегаю. Мне удаётся спастись."}]}]}','2026-01-08 18:27:40','2026-01-08 18:27:56',44,'2024-12-14T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(418,2,'post-1767886090','Снайпер','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, что я лазил по какой-то странной территории — полузаброшенные, полуразрушенные гаражи. На этой территории я нашёл снайперскую винтовку, патроны, две полупустые пачки сигарет и какие-то ещё вещи. Я забрал их и ушёл. То есть, по сути, украл, ведь это кому-то принадлежало."}]},{"type":"paragraph","content":[{"type":"text","text":"В какой-то момент я заметил мужика, который шёл в мою сторону. Он был ещё достаточно далеко, но уже понял, что я стащил его вещи, и собирался разобраться со мной. Я понял, что мне будет плохо, если он меня поймает. Этот мужик не выделялся физической силой, но в его спокойной уверенности чувствовалась угроза, будто за ним стояла некая скрытая мощь, неподвластная обычным людям. Я чувствовал, что он — не просто хозяин вещей, а часть какой-то силы, против которой я действовал, против чьих-то правил или игры."}]},{"type":"paragraph","content":[{"type":"text","text":"Я начал убегать и прятаться. Забрался на холм — не природный, это были руины из кирпича, плит и камней. Похоже когда-то тут стояли здания гаражей. Я нашёл место среди этих развалин, спрятался, и мужуик прошёл мимо, не заметив меня. Это было чувство успеха — я смог укрыться."}]},{"type":"paragraph","content":[{"type":"text","text":"Потом сон начал превращаться в фильм. В нём появился сюжет. Оказалось, что этот мужик принадлежит к какой-то группировке, а я — к какой-то другой. Мы воевали между собой. После того, как он прошёл мимо, я вылез из укрытия и отправился куда-то дальше. Теперь я уже пытался выследить его — не для того, чтобы убить, а чтобы понять что-то важное. Я подошёл к очередным гаражам, похожим на места для машин. Услышал там суету, приблизился."}]},{"type":"paragraph","content":[{"type":"text","text":"В этот момент камера сна сменилась, показывая других людей. Я понял, что мужик, которого я преследую, уже подготовил ловушки, камеры и выследил меня. В этот момент я понял, что мне будет плохо, но проснулся."}]}]}','2026-01-08 18:28:10','2026-01-08 18:28:30',42,'2024-12-16T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(419,2,'post-1767886118','Живая ткань','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Во сне передо мной разворачивается мир, сотканный из цвета и магии. Всё вокруг выглядело как ожившая фантазия — краски яркие, насыщенные, как в кино, а текстуры — невероятно детализированные, как в самых продуманных играх, но ещё глубже и реальнее. Я чувствовал себя существом, которое воспринимает всё иначе, не как человек, не как животное — это было совершенно новое ощущение."}]},{"type":"paragraph","content":[{"type":"text","text":"Я легко исследовал этот мир, наслаждаясь каждой деталью. В самом конце сна, перед пробуждением, я внезапно остановился. Мне захотелось понять, из чего всё это состоит. Обычно сны текут, сменяя одну картинку другой, но здесь я поставил паузу. Я приблизился к странной вертикальной поверхности, напоминающей ствол дерева, но она была не деревом. Эта магическая текстура переливалась загадочными фиолетовыми оттенками, искрилась и светилась. Я смотрел на неё почти вплотную, разглядывал мельчайшие детали, которых в реальной жизни, кажется, легко не бывает."}]},{"type":"paragraph","content":[{"type":"text","text":"В тот момент я понял, что наш реальный мир будто бы менее детален. Даже если начать внимательно рассматривать что-то привычное — сахарницу, кружку — оно всё равно не покажется настолько настоящим. А в этом сне каждая мельчайшая деталь была проработана до совершенства. Я смотрел на эту магическую ткань реальности и думал: «Как же это потрясающе»."}]}]}','2026-01-08 18:28:38','2026-01-08 18:28:58',43,'2024-12-17T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(420,2,'post-1767886162','Светлая Изнанка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, как вся моя семья улетает в отпуск без меня забавно, но родители были моложе, чем они есть сейчас. То есть это все были те же люди, но в возрасте, наверное, как сейчас, я в возрасте до 36 были родители, сестра и я, мы, наверное, были маленькими, ну, относительно того, что родители моложе. Вот. Но не настолько, чтобы вообще ничего не понимать в этом сне я все, что было, понимал, также осознавал, как взрослые, как сейчас. Ну, очевидно, мы там все были намного моложе, чем сейчас. Причём мы дружили. Я помню, что мама с отцом очень хорошо общались и, возможно, я путаю, но кто-то ещё был с нами. То есть, помимо мамы, папы и сестры кто-то ещё был. Они все улетали на какую-то другую планету в отпуск. Не просто в какой-то другой город. Это был самолёт целый. Вот. И я очень грустил то, что меня не взяли с собой. Это не как здесь. Если я могу спокойно жить 1, мне даже нравится, то вот во сне я помню, что мне очень грустно было от того, что они улетают даже не столько за то, куда они улетают и что меня там не будет, а за то, что я останусь тут 1. Вот я помню, они улетели, и я как бы видел, видел, ну, чувствовал их, как они летят, как они приземляются. Интересно, что, приземлившись на другую планету, они оказались в совершенно другом мире. Он какой-то был как компьютерный или мультяшный, и их тела были другими, ну то есть компьютерными и мультяшными, как будто они не просто преодолели расстояние, но и оказались в другом совершенно пространстве. Возможно, поэтому я ещё грустил. Понимаю, что с ними в принципе не получится никак общаться теперь, потому что какое-то время они будут совершенно в другом мире. В общем, я остался дома. Это тот же родительский дом, но он был классный. Это единственный сон, который вообще из всех мне снившихся про дом, где дом Светлый, тут все хорошо. Я вижу напротив. Из окон дома напротив другие дома. И это прям классные дома. Мне нравятся. Тут обычно мне всегда снятся очень жуткие тёмные сны в этом доме. Но хочу сказать, что это все-таки параллельная реальность, поэтому, вероятно, там все наизнанку, все наоборот. В хорошем смысле, за исключением того, что мне было очень грустно 1. И это невозможная тоска. Я какое-то время, небольшое время совсем находился в этом сне. После того, как они улетели, мне было невероятно тоскливо и грустно, при том, что не было каких-то критических, сильных эмоциональных переживаний. Вот как можно сказать, что истерика или что-то в этом духе, это была спокойная такая тоска, как, наверное, бывает у, мне кажется, у стариков, когда они понимают, что все Друзья, которые были, их уже нету. Я вот тут сидел в этом доме, и мне было невероятно грустно, но при том, что все было светлое, хорошее, просто я был 1."}]}]}','2026-01-08 18:29:22','2026-01-08 18:29:57',41,'2024-12-18T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(421,2,'post-1767886203','Видео','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне снилось несколько снов мультяшных такого не было раньше никогда, мне снились игровые сны, сны, кино, такое бывало, а тут прямо мультики, и я был наблюдателем, безусловно, больше наблюдал за тем, что происходит. Я не помню каких-то особенных чувств, переживаний. Вот как будто бы я просто смотрел мультфильм с очень большим погружением, как 5 д или что-то в этом духе. После этого Мультфильмы, сразу начинался фильм. Ну то есть это уже было кино. И вот несколько снов подряд я смотрел, можно сказать, фильмы и мультфильмы."}]}]}','2026-01-08 18:30:03','2026-01-08 18:30:21',40,'2024-12-17T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(422,2,'post-1767886226','Библиотека','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилась библиотека в которой мне нужно было найти старинную книгу \"Круг Земной\". Я пробирался через огромные залы, множество комнат наполненных книгами. В конечном итоге оказался в относительно небольшой комнате. Комната отличалась от других наличие бытовых предметов, будто некогда была жилая. В ней я отыскал нужный мне фолиант. Внезапно услышал голос, который напомнил мне, что я уже не раз брал эту книгу и добавил, что эта комната музей Лермонтова, творчеством которого никогда не интересовался."}]}]}','2026-01-08 18:30:26','2026-01-08 18:30:43',39,'2025-01-24T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(423,2,'post-1767886251','Алина и смартфон','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Незнакомая квартира в ней я, Алина и кто-то ещё, молодой мужчина в роли её отца. Мы общаемся, у нас хорошие дружеские отношения с ноткой романтики. У Алины старый айфон, у меня новый навороченный. Мы выходим из квартиры, идём по улице. Она предлагает поменяться телефонами, что бы я отдал ей свой, более лучшую модель. Я беру её телефон в руки, мне он не нравится. Я затягиваю с ответом. Мы подходим к банкомату, Алина выполняет какие-то операции. Вижу, как рядом с банкоматом на снегу лежит смартфон в красивом жёлтом чехле, его дисплей светиться. Я сажусь на корточки, делаю вид, что завязываю шнурки, переворачиваю телефон, прячу его, хочу подобрать и отдать потом Алине, что бы не менять на свой. Мне нравится мой смартфон. В этот момент ко мне со спины подходит парень, вроде уличного бандита. Я заметил его сразу, когда мы только подходили к банкомату, у меня было подозрение, что смартфон подкинули специально, но я решил рискнуть, вдруг его правда потеряли случайно. Парень позади меня настроен враждебно, он говорит о том, что не хорошо брать чужое. Я пытаюсь выкрутить, сказать что не понимаю о чем он, потом пытаюсь соскочить на линию, где будто бы я хотел отдать смартфон хозяину, чувствую дело дрянь. Начинаю просыпаться… Просыпаюсь частично, удерживаю мысль, о том как прекрасна Алина и как редко она мне снится, пытаюсь заскочить назад в сон, но минуя этот \"шум\", смартфоны и бандитов. На какое-то время получается, затем я снова просыпаюсь и уже не могу заснуть. Не открывая глаза прокручиваю сон раз за разом пытаясь перепрожить снова и снова образ Алины. Просыпаюсь до конца. Грущу из-за истории со смартфоном. Раздражаюсь сам на себя за то, что столько внимания уделял глупостям."}]}]}','2026-01-08 18:30:51','2026-01-08 18:31:29',38,'2025-01-25T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(424,2,'post-1767886295','Неудачная рыбалка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Впервые в жизни приснился нудный сон, и всё, что я хотел — это чтобы он поскорее закончился. По сюжету сна я с друзьями и родственниками отправился на рыбалку, но события развивались очень медленно. Сначала мы остановились в квартире, долго и муторно собирали вещи, что-то обсуждали. Ни выпить, ни покурить. Казалось, сон длился вечность, и я застрял в нём, никак не мог выбраться. Зачем-то оставался там, хотя осознавал, что сплю и могу проснуться — и тогда всё закончилось бы. Но… вероятно, реальность вне сна казалась мне ещё более скучной, и я продолжал спать."}]}]}','2026-01-08 18:31:35','2026-01-08 18:31:48',37,'2025-02-01T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(425,2,'post-1767886313','Три книги','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, что я \"в книге\". Читаю о своей жизни, которая уже произошла целиком, путь от рождения до смерти пройден. Теперь я вижу всё то, что происходило, под совершенно другим углом. Сначала мне показывают, что я хотел, но не сделал, и как это отразилось на мир в целом (не только на мою жизнь). Причём мои поступки такого плана — \"хотел, но не сделал\" — смешиваются с такими же поступками других людей, и тогда я вижу, как мир меняется под воздействием такой модели. Мир выглядит ужасно: в нём много трусости, страха и нереализованных возможностей. Постоянные желания пытаются реализоваться, но разбиваются, как горох об стену. От этого страдает душа, которая видит и помнит каждый такой поступок, и когда они смешиваются в одно большое \"нет\", душа кричит, бьётся в истерике, но ничего не выходит. Так заканчивается Первая книга, и начинается Вторая. Тут я пересматривал поступки, которые совершал, когда сомневался. Когда мне казалось, что делаю что-то неправильно, что мои действия не всегда этичны, не всегда приносят удовольствие. Часто мне казалось, что я ведом каким-то не самым лучшим чувством, зависимостью, невидимым импульсом. Однако чем больше я наблюдал за собой и за такими же, как я, тем более живым и радостным открывался мир, за которым я наблюдал с позиции души. Была и Третья книга. Я не успел понять замысел этой истории — проснулся. Осталось чувство незавершённости. Немного расстроился, что не успел посмотреть всё. Но вместе с тем испытывал радость, вспоминая те образы, которые мне открылись.\""}]}]}','2026-01-08 18:31:53','2026-01-08 18:32:20',36,'2025-02-14T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(426,2,'post-1767886347','Мигрень','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как очень сильно болит голова. Не помню что бы раньше когда либо чувствовал во сне боль который нет когда просыпаюсь."}]}]}','2026-01-08 18:32:27','2026-01-08 18:32:39',35,'2025-02-18T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(427,2,'post-1767886364','Экскурсия','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилась локация, которую видел несколько раз ранее. Это комплекс зданий из красного-жёлтого кирпича огороженный металлическим забором. Внутри дорожки, деревья, кусты, газон, скамеечки. Что-то вроде больницы или школы или какого-учебного заведение. Не помню что бы заходил внутрь какого-то из зданий. Только гулял во внутренней территории и за ее границами. Каждый раз в этой локации было много людей. Есть ощущение, что мы все сюда приехали на больших экскурсионных автобусах, как это например бывает с паломниками или скорее студентами, потому как большей части людей было 20-25 лет. Сон вчера проходит по одному сценарию. Начинается во внутреннем дворе, мы гуляем и общаемся там. Затем выходим за территорию и идём метров 200 по тротуару вдоль забора, оказываемся на небольшом асфальтированном пяточке. Тут есть маленькие магазины, остановка. Стоит пару автобусов. Мы собираемся в группу и ждём своей автобус что бы уехать. Отсюда открывается вид на трассу. Этот комплекс зданий расположен вдоль трассы. Движения машин почти нет. Асфальт старый, полоса на 2 машины, по одной в каждую сторону. За пределами трассы поле где растёт высокая трава. По ощущениям сентябрь или конец октября. Ещё с пяточка, где мы ждём автобус видно дорогу примыкающую к трассе, она уходит вверх, в горизонт. В этом сне нет диалогов, скорее я слышу бормотание людей вокруг, но не разделяю контрактные слова, не понимаю о чем говорят. В целом обстановка почти будничная. Нет ощущения что это событие имеет для меня или орудующих повышенную важность. Но что нетипично для моих снов это ощущение общности и принадлежности к группе."}]}]}','2026-01-08 18:32:44','2026-01-08 18:33:21',34,'2025-06-24T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(428,2,'post-1767886412','Родственники','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, что я у родственников в старом доме. Все были там — племянник, тётя, её умерший муж, его отец и жена. Странная компания. Мы ели наркотики, и остальные вели себя развратно, были сцены секса прямо передо мной. На меня тоже действовало вещество — мне хотелось быть частью этого, но другая часть меня осознавала, что это неправильно. Я ушёл в другую комнату и говорил с племянником, который уже взрослый."}]},{"type":"paragraph","content":[{"type":"text","text":"Потом зашла жена брата моего отца. В этом сне она была очень привлекательна, не по возрасту. Мы просто обнялись — это было приятно. Контекст весь напоминал вписку или мефедроновую тусовку: музыка, полусвет, эротика, упоротость."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда всё закончилось, дядя с женой пошли за добавкой. Я нашёл пакетик с веществом, спрятал его — подумал, что приму его уже дома, где могу быть собой. У меня кончились сигареты, и я пошёл в ванну, где были они. Попросить не решился, надеялся, что сами предложат. Не предложили. Дядя смотрел на меня зло. Он как будто презирал меня — за то, что я не с ними, не в этом общем кайфе. Он достал сигарету, сломал её, сделал из обломка бычок и закурил сам. Я понял — он просто не хочет со мной делиться. Тогда я решил уйти."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда вышел, у меня оказался велосипед — старый, колёса спущены. Но поехал. Была ранняя весна, солнце, лёд и мокрый асфальт. Я ехал уверенно, даже по трудному серпантину с гаражами. Но в самом низу путь стал пешим — велосипед исчез. Я заблудился."}]},{"type":"paragraph","content":[{"type":"text","text":"Встретил мужчину — сначала испугался, потом понял, что он просто хочет поговорить и выпить. Я не пил, он пил сам. Потом ушёл."}]},{"type":"paragraph","content":[{"type":"text","text":"Нашёл в снегу смартфон и игрушечные планшеты. Смартфон забрал — экран оказался зеркалом. В отражении небо и облака, но не моё лицо."}]},{"type":"paragraph","content":[{"type":"text","text":"Я представил карту местности, прикинул направление и пошёл — сначала на запад, если не выйдет, разворачиваться и идти на восток. Дорога стала широкой, я узнал очертания местности. Появилась надежда. Но путь оказался длиннее, чем я думал. Я шёл, но до дома не дошёл. Проснулся на ходу."}]}]}','2026-01-08 18:33:32','2026-01-08 18:34:05',33,'2025-06-03T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(429,2,'post-1767886456','35ый район','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, как возвращаюсь домой, побхожу к дому и зачем-то снимаю трусы. Из-за угла выруливает фура, мне становится стыдно, я отхожу за дерево и одеваю трусы, но путаю сторону и надеваю их задом на перед."}]},{"type":"paragraph","content":[{"type":"text","text":"Из-за угла выруливает комания ребят, человек 7. Идут на меня, хотят ограбить, но среди них мой друг Миша, он говори: этого не трогать и они уходят. Мне становится теплее от того, что меня защитили."}]},{"type":"paragraph","content":[{"type":"text","text":"Я иду к дому, не своему, другому. За мой привязывается один из ребят этой компании. Мы подходим к дому, это хрущёвка, но очень уютный ухоженный двор."}]},{"type":"paragraph","content":[{"type":"text","text":"Рядом с подъездом красная машина, в салоне знакомые (по сну) которые ко мне хорошо относятся. Но парня этого не любят. Водитель делает вид что наезжает на него машининой, но просто пугает. Парень уходит."}]},{"type":"paragraph","content":[{"type":"text","text":"Перед тем как зайти в подъезд, я вижу какой-то мусор, выкидываю его в урну. Поднимаюсь в квартиру. Дома на кухне 3 человека. Двое ребят из машины мужчина и женщина (муж и жена). И Георгий Дронов (из Саша и Маша)."}]},{"type":"paragraph","content":[{"type":"text","text":"Гоша говорит, что хотел купить наркотиков, но у него ненахад. Я что-то на это пошутил. Он сказал что пойдёт пить 20-30 летний коньяк к другу. Проснулся."}]},{"type":"paragraph","content":[{"type":"text","text":"Записываю этот сон для того, что бы тренировать осознанность. Мне кажется он ни о чем."}]}]}','2026-01-08 18:34:16','2026-01-08 18:35:08',32,'2025-06-06T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(430,2,'post-1767886517','Фентезийная дуэль','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилась игривая локация, с очень красивой фентезийной игровой графикой. Мой персонаж был магом и сражался против другого мага. Я строил магические ловушки, не давал противнику попасть в охраняемую зону. Негативных эмоций, адреналина, ничего такого не было. Размеренный темп, логика и удовольствие от игры. В общем очень милый, ламповый сон."}]}]}','2026-01-08 18:35:17','2026-01-08 18:35:45',31,'2025-06-08T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(431,2,'post-1767886550','Вещи, микроскоп и секс','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, как будто я в магазине покупаю вещи. У меня шапка, несколько шапок, розового и красного цветов. И еще какие-то вещи из одежды разноцветные, такие классные. Но там продавщица, молодая девушка, которая на меня смотрит и как-же стебется. Типа то, что мужики такие вещи не носят, пытаются меня как-то высмеять. Мне не очень приятно это, но мне пофиг. В общем, мне пофиг. И помимо этого там еще были какие-то оборудования. Маленькое устройство размером с ладонь, похоже на микроскоп. Я вот этот микроскоп смотрю, а там при увеличении видна поверхность металлическая, блестящая, и там какие-то машинки или что-то такое двигается. В общем, как маленький мир. Помню, что эта штука стоила 13 тысяч, а у меня было всего 23. Вот. И я решил отказаться от этой покупки из-за того, что мало денег оставалось. Вот. Интересно. Там еще какие-то вещи были, какие-то... Какой-то оборудование, какой-то пистолет, который водой стрелял, водный пистолет. Вот. А по итогу прикол был в том, что, ну, вот эта девчонка продавец, она как-то очень сильно меня высмеивала, а потом мы с ней переспали вообще. Ну, или легли, что-то такое. И это было уже классно. Вот. Интересно как-то. Интересно, кажется."}]}]}','2026-01-08 18:35:50','2026-01-08 18:36:48',30,'2025-06-11T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(432,2,'post-1767886616','Дядя Коля','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне снился родительский дом — тот, где я сейчас живу. Обычно во снах он тёмный, тревожный. А тут — всё наоборот: свет, день, зима, снежно. Люди суетятся, строят что-то, двигаются. Очень оживлённая сцена."}]},{"type":"paragraph","content":[{"type":"text","text":"Я вышел на улицу, хотел в туалет. Мимо проходил яму, что-то там ремонтировали. Подумал: «Надо бы кинуть палку, чтобы не провалиться». Прошёл дальше. Туалет был занят. Возвращаюсь — а яма уже заложена палкой. Прям как я подумал. Меня это поразило: будто кто-то услышал."}]},{"type":"paragraph","content":[{"type":"text","text":"И тут я увидел дядю Колю. Ему уже за 70, и во снах он обычно злой, неприятный. А тут — спокойный, задумчивый. Словно случилось что-то важное. Не грусть, не радость, а что-то другое. Он шёл, я за ним. Спросил: «Что ты здесь?» Он что-то отмахнулся, мол, отстань."}]},{"type":"paragraph","content":[{"type":"text","text":"Он зашёл в комнату, где я живу — это раньше была бабушкина. Я смотрю оттуда, с кухни: он обнимает моего отца. А они братья, но обычно не особо теплые. И вот обнимаются. Просто, по-человечески. В этой сцене было что-то очень тёплое, неожиданное. Меня тронуло. И тут я проснулся."}]}]}','2026-01-08 18:36:56','2026-01-08 18:37:15',29,'2025-06-17T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(433,2,'post-1767886643','Опыт с крысами','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Я участвую эксперименте с другими учёными. Мы проводим опыты, по факту издеваемся над крысами, приводим их в ярость, пытаемся довести до смерти. В какой-то момент мне становится жалко этих существ — я пытаюсь их спасти, накормить, прекратить пытки. И одна из крыс кусает меня."}]},{"type":"paragraph","content":[{"type":"text","text":"После этого всё меняется. Укус даёт мне сверх-силу, как у Человека-паука. Я оказываюсь в своей старой школе. Всё выглядит реалистично, но я уже не тот. Я сильный, мне на всё пофиг. Учителя пытаются мне что-то сказать, наехать, но я их посылаю. Я хожу по коридорам как хозяин, курю. Со мной кто-то есть, по ощущениям друг, но, я не вижу его лицо. Только чувствую что он ведёт, как если бы с ним такое уже случалось."}]}]}','2026-01-08 18:37:23','2026-01-08 18:37:41',28,'2025-07-05T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(434,2,'post-1767886665','Бегство','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы с другом на спорте, бежим и общаемся. С нами ровняется качек-гей, который все время говорит извращённую дичь про моего друга. Он приближается так близко, что начинает говорить буквально в ухо. При этом мы продолжали бежать. Меня это начинает сильно напрягать и я говорю, что это насилие, так докапывается. И тогда он ломает шею и позвоночник другу при этом что-то продолжая ему говорить. А я убегаю быстрее от них обоих.. Качек замечает, что меня нету и гонится за мной. Он бежит быстрее, начинает догонять. Когда я понимаю что вот вот мне конец, меня выбрасывает в ОС! Где я ускоряюсь так что в две секунды увеличивать отрыв в несколько раз. Теперь понимаю, что могу не бежать, могу атаковать сам! Но тут же просыпаюсь."}]}]}','2026-01-08 18:37:45','2026-01-08 18:38:11',27,'2025-07-06T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(435,2,'post-1767886699','Агент','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось что я в квартире со своей девушкой. Я знаю, что она работает под прикрытием и что в квартире множество жучков, в соседних квартирах агенты, которые в любой момент готовы ворваться к нам через двери в шкафу и другие тайные ходы. Я знаю эту и строю план, как отсюда выбраться. У меня это получается и когда агенты идут на штурм меня в квартире уже нет. Этот сон немного напоминает игру, где нужно выбраться. Потому как идеи криминала, преступления, злости, тут нет. Есть задача выбраться. Дальше телепорт в другую локацию. Что-то вроде военной базы, рядом река и на сваях дом все котором мы отдыхаем. Это база как-то связана с прошлым сном. Вероятно тут я скрываюсь. Очень красивая локация, река и холмы на горизонте. Ребята дружные, не скажешь что военные."}]}]}','2026-01-08 18:38:19','2026-01-08 18:38:43',26,'2025-07-08T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(436,2,'post-1767886733','Дом. Тень. Магия','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снился сон. Пожалуй самый мистический, красивый, пугающий, детально проработанный, магический, неповторимый!"}]},{"type":"paragraph","content":[{"type":"text","text":"Началась все с того, как я стоял по центру двора, ночью и смотрел на двери дома передо мной. Вокруг было много блуждающего холодного света. Деревья, растения, будто были живые, колыхались от невидимого ветра. Каждый раз, когда я крутил головой, за моей спиной что-то происходило, когда я возвращался вниманием туда, откуда секунду назад отвернулся, на этом месте появлялось что-то новое. Так я заметил появление третьей руки, когда осматривал своё тело. Меня это сначала пугало, эти новые элементы мира появлялся из чёрного дыма и в нем же исчезали. Будто так в этом мире проявлялась моя тень, изнанка, что-то что существует всегда параллельно. Я продолжал рассматривать себя в этом мире, крутил головой в разные стороны, пугался собственной тени и размышлял о ее природе. В какой-то момент привык, освоился, перестал боятся и пошел дальше по двору. Со мной заговорили! Как если бы у меня были наушники, а объекты на которые смотрю содержали голосовые комментарии, как то что бывает в музеях и называется аудио-гид. Справа от входа в дом был забор за которым заброшенная швейная фабрика. Т мой дом и фабрика выполнены в готическом стиле, мрачный тёмный камень, зелёная черепица на крыше. Стекла местами выбиты, местами заколочены. Но самое интересное как этот мир жил раньше. Время от времени я видел флеш-беки из прошлого. Видел очень живую сцену, день открытия фабрики, видел отражение самого себя, другого себя. Наблюдал как пью шампанское, общаюсь с людьми. У нас причудливые одежды. Пожалуй мир сна все больше напоминает игру Dishonored. Ее неповторимый стиль! Когда сцена с фуршетом закончилась, передо мной снова оказалась заброшенная фабрика, но теперь стало невыносимо грустно. Появилось чувство, что вернулся домой! Но поздно, слишком поздно и теперь здесь только воспоминания и ветер. Но и пожалуй что ещё, моя тень? Не сразу, после 3-4 флешбеков я стал замечать как мир меняется, живёт, хочет мне что-то показать, объяснить. Будто все тут живая материя. Просто очень грустная, сердитая на меня (потому что сюда не заходил) и в это же время хочет играть! В центре двора появилась елка. Я понял что это намёк на праздник и стал гулять по двору, отыскивать игрушки, что бы повесить их на ёлку. И так началось полное погружение. Каждая игрушка открывала целый мир образов, воспоминаний, как мини-сон обо мне в котором я жил какой-то время пока меня не выбрасывало обратно! Так продолжалось очень много времени, по ощущениям маленькая жизнь. Но когда я нашёл последнюю игрушку и понёс ее на ёлку, то дерева там не оказалось. Вместо этого лежал камень, а на нем был текст, что-то вроде: \"ты слишком долго смотришь в прошлое, меня больше нет.\" Так исчезла ёлка, но появились следы! Я шёл по ним, пока не увидел огромного пса! Он был очень страшный, но я чувствовал связь между нами и мы какое-то время просто смотрели друг другу в глаза. Затем было много сцен про нашу дружбу. Были сцены с людьми, множество воспоминаний другой жизни. Я буквально жил в этом сне! И не смотря на мрачные мотивы мне совсем не хотелось просыпаться."}]}]}','2026-01-08 18:38:53','2026-01-08 18:39:30',25,'2025-07-11T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(437,2,'post-1767886780','Прайд','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, как я девушкой нюхаю мефедрон. (Drooomera. Я помню эту девушку, мы общались в Telegram в 2021-22 году, когда жил в Москве. Она последняя с кем общался в Бресте перед тем как выбежал из квартиры в мае 2023...). Помню как она садится в автобус и уезжает, а я не могу отправиться с ней потому что никогда не выхожу из комнаты в трипе под веществами. От этого мне становится очень грустно. Я понимаю как терять ее снова оставаясь дома, будто на цепи. Девушка возвращается несколько раз и мы снова и снова нюхаем мефедроном и она снова и снова уходит, каждый раз столько только понюхать. В какой-то момент я решаюсь пойти с ней и когда мы нюхаем вместе очередной раз, я отправляюсь с ней и тут начинается что-то совершенно фантастическое! Я встречаю её подруг, это две очень симпатичные девушки. Я их не знаю в риальности, но тут чувствую но они давно дружат или даже состоят в какой-то группе, организации, семье, команде или что-то вроде. У одной из них большая сексуальная грудь. Мы куда-то идём. Эйфория начинает переходить в панику, когда я начинаю понимать, что нахожусь в магическом или игровом мире где все с друг другом толи воюют, то ли вообще едят друг друга, но делятся по условным прайдом. И я понимаю, что попал в чужой прайд и та первая девушка, которая впервые от меня ушла больше не вернётся. А эта, которая со мной сейчас, вроде репликанта, хамелеона, то есть только внешность ее, но уже не она. И когда я все это понимаю мы оказываемся у двери их дома и оттуда вот вот вырвется мужик, который меня побьет или убьёт... И я бегу через дорогу от этой двери и я знаю, что стоит перебежать дорогу и он не сможет ничего сделать. Я бегу, мужик выбегает из двери, он почти догоняет меня, но я успеваю коснуться рукой, доползти до противоположной стороны дороги и таким образом спасаюсь. От адреналина, эмоций попадаю в ОС. Становлюсь потоком и летаю над миром сна, исследую его что бы понять как тут все работает. Я вспоминаю множество моментов из реальной жизни, которые отражалась в этом мире, как союз трёх людей, разделенных по специальным ролям и образующим таким образом нечто вроде единого существа или скорее единого сознания. Это единое сознание и есть тот прайд или команда о котором писал вначале. Те три девушки и мужчина который за мной гнался и те кто оставался за дверью (чувствовал что ещё как минимум один мужчина), это очень древняя группа, они существуют очень давно и они наиболее опасные ребята. При чем я понимал что их можно встретить в реальности, но в других людях и возможно эти люди не осознают что есть что-то большее в них и их общее сознание как-бы защищается так в мире людей, скрывая даже от своих собственных частей (людей) свою суть. Тогда я понял что у меня тоже есть своего рода Прайд. Точнее был, я менял его множество раз, он распродался, я снова искал, снова менял. Как если бы искал сочетание \"ключ+замок\", но все не то. Это как история с половинками но не про любовь, а про свою суть вообщем, про душу или что-то такое, что проходит через все миры. Я спал очень долго, почти сутки, несколько раз вставал и засыпал снова, что бы продолжался этот сон, который мне все объяснял."}]}]}','2026-01-08 18:39:40','2026-01-08 18:40:35',24,'2025-07-15T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(438,2,'post-1767886845','Девушка-призрак','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как я сражаюсь с мёртвыми или точнее с призраками. Так начинается сон, который затем перестаёт во что-то совершенно сумасшедшее! Вообщем, я очень много ворочился, снились отрывистые кошмары, которые совсем не запомнил. Я более 5 раз вставал то попить, то в туалет и в итоге стал нормально засыпать после 3 ночи. И вот мне снится что я сражаюсь с призраками, это было несколько человек, которые жили относительно недавно и умерли молодыми. Я смотрел этот сон какое-то время, но затем совершенно неожиданным образом получил доступ к ОС. Это напомнило как передают управление игроку, когда срежиссированный ролик плавно переходит в геймплей. Тогда я перестал сражаться и начал общаться с девушкой призраком. И мы столько говорили... Как будто я сам готовился умереть и потому мне все это очень нужно знать! Но кроме шуток, это реально интересно, ведь я все осознаю и то, что сплю в комнате и то что мы в мире сна и даже когда мы пошли гулять по городу, совершенно прекрасному и незнакомому и в какой-то момент я сказал, что отойду ненадолго. Я встал и сходил в туалет и вернулся в сон! И мы продолжили идти и общаться. Ну это совершенно невообразимо и по ощущениям я прожил в этом сне несколько дней. Это вообще не похоже на сон. Это путешествие в полноценный мир! И это не мир мёртвых, девушка была мёртвая, а я был живым и говорил с ее духом, но как с живой практически. И это было волшебно!"}]}]}','2026-01-08 18:40:45','2026-01-08 18:41:11',23,'2025-07-17T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(439,2,'post-1767886877','Осознанные кино-сны','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Много много разных снов, но такие, удалённые осы. Началось как обычный сон сюжет которого не сильно запомнил, в конце было что-то вроде панорамы локации с дрона, как иногда бывает в титрах фильма, показывают как снимали это кино. Ну и когда все заканчивается я просыпаюсь, пью воду, снова ложусь и думаю, чево так быстро закончилась все. И появляется мужик какой-то, в одежде типа мага или шамана и говорит, а чево ещё хочешь посмотреть? А я ещё не сплю. Думаю о как! Щас погодь, открываю глаза, съедаю абрикос по быстрому (я ем во сне, это удобно чтоб не завтракать) и когда снова закрываю глаза прошу показать про космос. И начинается фильм про космос. Тоже короткий правда. В конце я снова ем фрукты, переодически пью воду и прошу ставить разные фильмы, про природу разных планет особенно нравится. В итоге штук 10 посмотрел, может больше. Мог больше, но уже солнце начало светить через шторку и звуки машин мешали и тогда я попрощался с этим мужиком и вот проснулся. Написал."}]}]}','2026-01-08 18:41:17','2026-01-08 18:41:47',22,'2025-07-26T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(440,2,'post-1767886912','Машина отца','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилась улица рядом с домом родителей. Во сне были ребята из детства, один из которых умер в 2022. И был отец. По сюжету я без спроса взял машину отца и катался. И ещё должен был кому-то денег. Как в юности. Смешанные чувства."}]}]}','2026-01-08 18:41:52','2026-01-08 18:42:09',21,'2025-07-27T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(441,2,'post-1767886935','Гулящий под дождём','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Прилёг послушать медитацию в наушниках. Заснул. Просыпаюсь в комнате от звука телеграм. Читаю наш чат, медитация в наушниках ещё идёт. Одеваюсь иду гулять. Прохожу пару перекрёстков и начинается сильный дождь. Думаю какой нафиг дождь, обещали солнце. И тут понимаю что сплю. Начинается ОС! И я гуляю по улице, дождь такой классный. И радостно так, что могу пойти куда угодно, сделать что хочу. И все это максимально осознанно, потому что помню, что лежу в комнате и более того продолжаю слушать музыку, медитацию эту. Но когда радость достигает пика просыпаюсь не самом деле. Вероятно сильные эмоции какие-то там гармоны активирует или что-то такое."}]}]}','2026-01-08 18:42:15','2026-01-08 18:42:40',20,'2025-07-27T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(442,2,'post-1767886967','Война с вампирами','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снова снились улицы рядом с родительским домом. В этом раз это был мир параллельной реальности. Я был сильным молодым парнем похожим на тех, что снимают в американских молодёжных комедиях. По всюду шла война. Бегали патрули. Воевали не с людьми, а с вампирами или какими-то существами, с другим видом! И я был одним из добровольцев, который воевал с ними. И вот я шёл с автоматом и встретил мужчину. Он был стильно одет, высокий, с длинными волосами и выглядел так будто ему на все абсолютно насрать. А вокруг блин война. Оказалась позже, что он чуть ли не главный среди этих существ похожих на вампиров. Но он меня не тронул. А я не понял что он мой враг. В этот раз мы разошлись. Я понял что он вампир через ролик, когда камера переключилась на него и показала как он зашёл к себе в дом и там его жена или подруга сказала, мол, что ты его не убил. А он ответил, что я безопасен. Через какое-то время я нашёл друга, твоего же молодого парня моего возраста. Мы успешно воевали вместе, пока что-то не произошло. Я не помню как именно это случилось, но мы стали вампирами. Нас толи покусали, толи завербовали, вобщем мы теперь одни из них. И это оказалось круче! И этих ребят намного более интересная и длинная история. Намного лучше воспитание, выше интеллект, мне нравится их ментальность. Они уважают друг друга, держатся друг за друга. При этом они в абсолютном меньшинстве. И вынуждены скрываться. Проходит ещё немного времени и я наблюдаю сцену, со стороны, как нас расстреливаюют из автоматов солдаты. Но к моему удивлению пули будто не ранят нас. За это время с нашими телами что-то произошло. Они местами кибернетезированы, местами идёт регенерация. Вобщем нам пофиг. Но есть ещё один интересный момент, я наблюдаю сцену рассмотрела но лица тех кто расстреливает. То есть я стал переживать сон от другого персонажа снова. Немного ранее, тот самый первый вампир который заходил к себе в дом и общался то ли с женой, то ли с девушкой. Я так же чувствовал что \"играю\" за него пока он в своём доме. Дом был наполнен магией. Когда я вошёл и закрыл ворота, что-то щёлкнуло и над нами появился защитный купол. И я сказал, что очень устал и пойду на заслуженный отдых и просплю десять лет. И никто из живых не сможет помешать. Так и случилось."}]},{"type":"paragraph","content":[{"type":"text","text":"UPD: Когда я был тем древним вампиром, то зайдя в дом и натянув над домом защитный купол я бросил якорь во двор, между домом и забором. Словно это корабль и с помощью этого якоря, было ощущение, мы никуда не пропадем."}]}]}','2026-01-08 18:42:47','2026-01-08 18:43:13',19,'2025-07-28T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(443,2,'post-1767886999','За бортом','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мы с друзьями преплывём на быстрой яхте. Открытая вода напоминает море или даже океан. Я падаю и мне очень страшно. Ребята на яхте плывут дальше, я остаюсь в открытом море. Я плохо плаваю (в реале) и в сон попадает это чувство. Но не смотря на это я плыву. Яхта останавливается, ребята спрашивают в воду пытаясь найти меня, что бы спасти. Но я вперёд них доплываю до яхты и поднимаюсь на борт. Затем они поднимаются тоже. Мы плывём дальше."}]}]}','2026-01-08 18:43:19','2026-01-08 18:43:48',18,'2025-07-28T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(444,2,'post-1767887034','Между небом и землёй','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Про сегодняшний сон, очень очень странно. Было ощущение что вообще не сплю, осознаю как ворочаюсь, как за окном проезжают машины... Но в это время я, даже не во сне, в какой-то липкой темноте. Время от времени появляться какие-то люди, предметы. Как в театре на сцене, вокруг темно и только кусочек сцены освещен и там все происходит. И это так долго тянулась, не по себе было очень. А под утро флеш-беки из воспоминаний начали мелькать и это уже было интересно и довольно чувственно. И да, я по прежнему и спал и не спал."}]},{"type":"paragraph","content":[{"type":"text","text":"UPD: Я чувствовал себя как в наркотическом трипе, то есть буквально ощущал эйфорию, эмпатию, был с Таней. Воспоминание, мм скорее собирательный образ наших совместных трипов с полным погружением. Меня не отпускало ещё около часа после пробуждения. Обычно сильные эмоции, эйфория тела пробуждает, но тут я осознанно попытался балансировать что бы не проснуться до конца и что бы не уйти в бед. Стоит сказать у меня получилось. Я намерением контролировал состояние тела. Несколько часов, потом наступило утро и пришлось просыпаться на работу."}]}]}','2026-01-08 18:43:54','2026-01-08 18:44:17',17,'2025-07-30T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(445,2,'post-1767887063','Стрижка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось что я в магазине в котором очень очень много людей. Это магазин находится на Площади Победы города Калуга. Сейчас такого уже нет, но он был раньше лет так 25 назад."}]},{"type":"paragraph","content":[{"type":"text","text":"Сон начинается с того, что я стою среди толпы и мы смотрим на парня, который говорит с молодой женщиной. Парень уверен в себе, такой весь бунтарь. Одет во все чёрное. Вобщем очень стильный, красивый, молодой. И он говорит что-то вроде \" я не поведусь на то что вы мне предлагаете, вы вообще меня случайно встретили\". Женщина продолжает уговаривать его что-то пробовать (вероятно какой-то продукт). Толпа за моей спиной наблюдает за их диалогом. Оглядываясь на толпу я обращаюсь к кому-то рядом, произношу что-то вроде – да это все постановочная сцена. Неужели вы не видите. В этом момент парень в чёрном умолкает и смотрит на меня. Я улыбаюсь и ухожу. Прохожу мимо различных отделов магазина. Дохожу до одного из них и прошу женщину выдать мне талон в очередь на стрижку. Она говорит, что это в другое окошко, другой отдел. Но перед тем как меня отпустить предлагает мне сделать химию, потому что эта услугу никто не покупает, но ей хотелось бы очень продать. Я бегло интересуюсь, скорее из вежливости и ухожу к другому окошку, беру талон на стрижку в этот же момент просыпаюсь."}]}]}','2026-01-08 18:44:23','2026-01-08 18:45:20',16,'2025-08-01T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(446,2,'post-1767887098','Мефистофель, Университет, Iris','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне сегодня снился Мефистофель. Который по Фаусту, мудрый харизматичный чёрт."}]},{"type":"paragraph","content":[{"type":"text","text":"По сюжету я гулял с кем-то по улице где стоит родительский дом. Тёмная летняя ночь без ветра. Обратил внимание на тени на земле, они не падали от кустов и деревьев, а все больше напоминали силуэты существ из других измерений. Я обратил на них внимание в момент, когда одно из существ стало проявляться в моём мире. Силуэт поднялся от земли и превратился в огромного черта, в котором я интуитивно распознал Мефистофеля и у нас произошёл диалог. Было не по себе сначало, но он оказался нормальным мужиком, поговорили и разошлись. Хотя детали диалога меня насторожили, ничего особенного за этим (по крайней мере во сне) не последовало."}]},{"type":"paragraph","content":[{"type":"text","text":"Тема существ из других измерений похоже самая популярная в моих снах."}]},{"type":"paragraph","content":[{"type":"text","text":"Сразу за этим был сон в локации школа. Но это не здание, а комплекс, с кампусом, студентами. Я условно называю это школой, потому как уже накопилось около 10 снов в этой локации и каждый раз она проявляется разными зданиями. Честно говоря я даже не сразу понял, что это одна общая локация. Но были знакомые, атмосфера места, одним словом общие ключевые моменты. Сны в этой локации всегда тёплые, насыщенные общением, очень нравится там быть."}]},{"type":"paragraph","content":[{"type":"text","text":"Ещё было несколько короткометражных снов 🔞🍓, но что-то прям коротенькие, хотелось режиссёрскую версию, но ОС выйти не удалось, штоуш. В другой раз 😎"}]}]}','2026-01-08 18:44:58','2026-01-08 18:45:38',15,'2025-08-27T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(447,2,'post-1767887144','Монастырь','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как гуляю по живописному лесу, подхожу к горной реке и проваливаюсь по колено в воду, цепляюсь за деревья которые торчат из воды по берегам. Я не один, за мной группа молодых людей. Впереди на горизонте ещё несколько рек. Их течение стремительное, не горизонте реки превращаются в одну большую и очень быструю. Я боюсь утонуть, цепляюсь за деревья, что бы не унесло течением. Так продолжается какое-то время, мне удаётся выбраться. Я выхожу к локации где много снега. Натыкаюсь на холодильник закопанный в сугроб. Открываю его, внутри тоже много снега и какие-то инструменты, небольшие, вроде карандашей, ручек, каких-то мелких ложечек. Копаюсь дальше, нахожу какие-то продукты завёрнутые в целлофановые пакеты. Что-то вроде крупы, зёрен. Я не нахожу эту нужным для себя, оставляю все на месте и ухожу. Вижу за местом где стоит холодильник продолговатое одноэтажное здание. Много окон, внутри дети, будто за партами, похоже это школа. Ко мне подходит женщина, очень красивая. Спрашивает зачем я лазил по их холодильнику. Извиняюсь, говорю не знал, что он чей-то. Она смотрит на меня, будто я вру. Смущаюсь. Спрашиваю почему его просто не подключить к сети, ведь не удобно носить продукты из него в дом, пока он на улице. Женщина улыбается и жмёт плечами. Я прохожу дальше от дома в центр локации. Вижу комплекс невысоких зданий. Это похоже на горный монастырь или школу. Тут чистый воздух, голубое небо, немного прохладно, по ощущениям ранняя весна. Из головы не выходит образ этой женщины, она очень красивая."}]}]}','2026-01-08 18:45:44','2026-01-08 18:46:07',14,'2025-09-13T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(448,2,'post-1767887172','Майбах','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снился сон, где главной ролью была машина, автомобиль. По-моему, это был Майбах. Я на нем ездил много, катался. Это была зима, канун Нового года. Катался по Калуге. В этом сне было много друзей. Моих со школы. Как будто это то время, когда еще все были со всеми общались, все были молодые. Хотя во сне вроде бы уже взрослые были. Я тогда подумал, почему я не получил права раньше на вождение. Потому что это очень классное чувство."}]}]}','2026-01-08 18:46:12','2026-01-08 18:46:28',13,'2025-09-13T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(449,2,'post-1767887194','Поцелуй','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как иду покупать торт. Со мной девушка, мы коллеги или сослуживцы, не романтические отношение. На улице зима и ночь. И вот мы останавливаемся, я что-то ищу в кармане, оборачиваюсь к ней, а она так близко стоит рядом со мной, что получается поцелуй. И такой невероятный взрыв эмоций от этого. И сам целуется и молчим. А потом продолжаем идти, на этот раз взяв друг друга за руки. В магазине я покупаю торт или даже два торта. И мне кажется что на что-то не хватает денег и как-будто я что-то не смог купить. Но мы возвращаемся домой и оказывается что денег у меня хватает и их вообщем больше чем рассчитывал. Но это не так важно, как тот поцелуй. Проснувшись я прокручиваю в памяти этот момент сна, как стартер на машине, будто пытаюсь запустить сон, как двигатель с ключа этим воспоминанием. На этот раз ничего не выходит. Просыпаюсь окончательно"}]}]}','2026-01-08 18:46:34','2026-01-08 18:46:52',12,'2025-09-14T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(450,2,'post-1767887217','Наводнение','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Школа. Мы сидим за партами на уроке и не проявляем особого интереса к предмету. Начинается дождь и я с одноклассником потихоньку прячусь за партой от учителя. Появляется колона по центру комнаты, мы прячемся за ней. Теперь как в советском мультфильме Буревестник разозлился гром и молния! …потекли реки, быстрые воды. Я промок до нитки, но не утонул и проснулся."}]}]}','2026-01-08 18:46:57','2026-01-08 18:47:10',11,'2025-09-15T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(451,2,'post-1767887235','Оболочка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сны странные, абстрактные и неземные. Последнее время все больше таких. Вроде бы помнишь, но когда дело доходит описать, вот тут начинается проблема. Например сейчас, проснулся (7 утра), снилось что я в процессе сна могу \"оборачиваться\" в белую или черную оболочку. Белая это знак (символ или что-то такое, едва уловимое как аура) что следующий отрезок пути я знаю и могу (как идти); черная нет. Цвета сами по себе ничего не значат. Нет ассоциаций что черная - тьма, зло, а белая - свет, добро. Прост так почему-то совпало. Сюжета во сне как такового нет. Все что я делал это изучал, пытался понять значение и методы этих \"оболочек\", как работает, как использовать. Пишу и удивляюсь, сон рассеивается, смыслы все больше растворяются в реальности где этого нет."}]}]}','2026-01-08 18:47:15','2026-01-08 18:47:30',10,'2025-10-15T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(452,2,'post-1767887254','Деревня у моря','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось как я гуляю по маленькому городку или скорее деревне. Очень живописные маленькие домики. Такие как бывают в частном секторе в России во времена СССР и какие раньше были в деревнях. Резные окна, разноцветные фасады. Очень узкие улочки между домов. Множество растений, цветов и деревьев. Видел как гуляют люди, идут компанией человек 7-9. Похоже к реке. А она буквально метрах в 20 от первой линии домов. Река не очень широкая но от нее волны как будто море. На обратном пути заметил дом на котором развешано множество шерстяных изделий. Сначала увидел шапки, потом свитера, детские одежки и разные халаты. Все очень живописно, красочно. На мне тоже свитер, похоже как у них покупал, только сейчас его заметил. Кроме этого большого дома, он самый красивый, с огромными вертикальными окнами, есть несколько домов тоже с шерстяными изделиями (как реклама) на фасадах. Дальше зона рынка, продают это. Сделал вывод что эта деревенька этим промышляет. Еще видел двух собак, сначала испугался, но они быстро свернули, играючи бежали. Через минуту увидел их на крыше небольшого дома, как-то туда забрались. Хотел сфотографировать как они красиво лежат, но они убежали. Выходя из деревни попадаю на дорогу. Отсюда она поднимается довольно круто вверх. Я перехожу дорогу и выхожу на побережье моря. Это уже не река прям море. Воздух тут холодный и сильный ветер. Мне страшно смотреть вдаль на воду, горизонт быстро пропадает в тумане. Кажется тут сильный северный ветер. Решаю развернуться и подняться вверх по дороге. Где-то на середине перехода просыпаюсь."}]}]}','2026-01-08 18:47:34','2026-01-08 18:48:18',9,'2025-11-13T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(453,2,'post-1767887304','Банши Инишерина','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Смотрел фильм \"Банши Инишерина\". Заснул и мне началось сниться продолжение этого фильма. Только проснулся и не знаю, чем закончился оригинальный фильм, во сне фильм приобрел характер триллера. Двое бывший друзей настолько поругались друг с другом, что по итогу Патрик убил своего бывшего друга… Было много сцен, действий на острове, я среди прочих жителей, находился рядом с гг. Последняя сцена в амбаре. Был еще какой-то ребенок… Я и ребенок играли вместе. А эти ребята сидели насупившись и смотрели друг на друга с неприкрытой ненавистью. Когда я это заметил, то взял ребенка и поспешил уйти. Через несколько минут Патрик разнес киркой голову Колму. Эту сцену смотрел как наблюдатель."}]},{"type":"paragraph","content":[{"type":"text","text":"Еще во сне мне было жалко Колма и хотелось, что бы он убил Патрика, а не наоборот. Интересно, что в этой сцене убийства Колм сидел спиной к Патрику и в руках у него было, что-то вроде серпа. А Патрик в метре-двух за спиной, достал что-то вроде мотыги но с длинной ручкой и со всех сил несколько раз ударил Колма по голове. Было очень больно, неприятно на это смотреть."}]},{"type":"paragraph","content":[{"type":"text","text":"Не помню когда еще мне снились убийства?"}]}]}','2026-01-08 18:48:24','2026-01-08 18:48:57',8,'2025-11-13T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(454,2,'post-1767887341','Лимбический маятник','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Отлично. А вот еще сон. Я лежу на кровати у себя дома. Переодически проваливаюсь в состояние ложного бодрствования, когда кажется что проснулся но продолжаю лежать в своей комнате и в полумраке вижу ее очертания. На деле я продолжаю спать и это не более чем переходы. Между ложными пробуждениями я по прежнему вижу сон где лежу на кровати, но в соседней комнате. Во сне мебель расставлена так, как было когда я тут жил в детстве. Во сне переодически появляется Таня, хотя ее образ сильно изменен, но есть общие черты, как архетипы. Я чувствую себя будто слегка упоротым, вместе с эйфорией привычное сопутствующее состояние необоснованной тревоги переходящей к паранойи. Можно сказать я мечусь между удовольствием и страхом; расслаблением и контролем; фокусом внутрь себя и на Таню и на окружение: комнату и попыткой заглянуть за ее пределы (поиск опасности). Таня тоже упорота и контакт наших тел создаёт мощную эйфорию сила которой прямо пропорциональна волнению, тревоги и паранойи. Сюжета как такового нет, нет начала, нет конца. Такие странные метания от одного состояния к другому. И это весь сон. Ложился трезвый, состояние никак не связанно с алкоголем и веществами. И я не болею, чувствую себя хорошо. Возможно сама комната в которой засыпал, находится в которой сейчас (из-за обстановки которую пока не могу изменить) мне совсем не нравится. И дождь, осень за окном. Подвешенное состояние ожидания перемен без срока. Может это како-то связанно."}]}]}','2026-01-08 18:49:01','2026-01-08 18:49:32',7,'2025-11-16T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(455,2,'post-1767887381','Гонка с негром','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сон, довольно жесткий и не привычный мне. Короч снится что я бегу по улице параллельной с той где живу. Слева маленькие частные домики, я бегу по тротуару, справа широкая полоса газона (деревья, кусты), за ней автомобильная дорога. Я бегу и позади меня бежит негр. Спортивный, сильный, хорошо бежит. Я бегу быстрее его, обгоняю его и понимаю что побеждаю. Он за моей спиной говорит что ему нужно победить. Я предлагаю ему себя обогнать, раз ему так нужно, хочу пропустить его вперед. Он злобно улыбается и говорит что он так хочет, а не то что ему нужно, типа \"я сказал\". У него в руках появляется пистолет и он вроде как готов выстрелить что бы я его толи пропустил толи он просто ебанутый. Очень агрессивный злой мужик. Я делаю резкое движение, выхватываю пистолет и наваливаю ему по жопе. Он падает я бегу дальше. Позади еще толпа людей которые его догоняют, но мне до этого уже нет дела я спокойно бегу впереди."}]}]}','2026-01-08 18:49:41','2026-01-08 18:50:29',6,'2025-11-16T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(456,2,'post-1767887434','Под дождём','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, как мы с Олегом (мой бывший одноклассник и друг, который умер в 2021) бегали по лужам под дождем в одних трусах по старой Калуге в районе бывшего рынка."}]}]}','2026-01-08 18:50:34','2026-01-08 18:50:45',5,'2025-11-17T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(457,2,'post-1767887451','Монстр в руинах','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, как я с ребятами нахожусь в готических развалинах. Мы тут будто часть чей-то злой игры. Не смотря на то, что тут сухо и солнечно, мы в плену. Главный герой этой истории древний монстр, толи вампир, толи оборотень, он очень могущественный и никто ему не может противостоять. У него на нас есть свои злые планы. Мне нужно было передать ему какую-то жидкость в маленьком пакетике похоже на целлофан от сигаретной пачки. Я подменяю содержимое на что-то другое, надеясь что так он не получит дополнительные силы. Но монстр замечает подмену и говорит, что-то немного расстроен мной, хотя и ожидал этого. И ещё говорит, что это была моя последняя оплошность. Я решаю бежать и открываю для себя, что у меня тоже есть суперспособности. Я очень высоко прыгаю и так преодолеваю несколько полуразрушенных стен, практически выбираюсь, но тут, появляется этот древний монстр и вместо того, что бы самостоятельно меня атаковать, он произносит то, что есть способ намного более изощренный и мучительный. Он призывает ещё более древнее и лишенное сознания, только инстинкты существо, которое вырастает прямо из стены. Оно похоже на огромную личинку с множеством длинных лап на концах которые острые как бритва шипы. Существо издаёт ужасные ультротонкие звуки и приближается ко мне. Я понимаю что мне не уйти и что кроме силы оно воздействует на познание и пожирает изнутри. Не смотря на все это, я будто не сильно паникую, закрываю глаза и визуализирую себя в другом пространстве, понимаю что уже началась атака, а я будто нахожусь в пути в другое место внутри себя. Я слышу как этот монстр обволакивает меня своими щупальцами и высасывает из меня жизненные силы нанося страшно болезненные повреждения. Но все это я понимаю оставаясь неприступен, с закрытыми глазами пытаюсь пережить атаку и проложить маршрут к выходу, то есть создать его. Мне это удаётся и открыв глаза я оказываюсь на траве за стенами этого ужаса места. Отсюда я немного вижу моих бывших врагов и это существо, которое увеличилось до размеров комнаты в которой я находился, где меня уже нет, но оно будто продолжает соскребать со стен мои остатки. Однако я снова ничуть не переживаю, потому как мне удалось переместиться, выбраться. И тут я вижу друзей, группы ребята которая будто все это время ждала когда я выберусь. Светит солнце и лето, я направляюсь к ним и радуюсь что все закончилось."}]}]}','2026-01-08 18:50:51','2026-01-08 18:51:40',4,'2025-11-17T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(458,2,'post-1767887506','Иголка','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снится как я договариваюсь со знакомой девушкой (в жизни ее не знаю) на обмен какими-то вещами. Жду ее на углу улице где живу (в реальности). Проходит какой-то время, она приезжает и вручает мне иголку. Иголка очень толстая, похоже что сделана из золота, на ней есть неровности и е круглые дырочки.. Вообщем она скорее похожа на маленькую флейту. Я кручу ее в руках, очень удивляюсь и говорю, что думал она будет тоньше. Не помню что бы давал что-то взамен этой девушке. Даже мы немного обсудили ее машину, возможно, даже прокатился на ней. Появились ребята и я устроился к ним на работу. Собеседование напоминало скорей мистический процессы инициации. Меня так же, ритуально пытались убить, но ничего плохого в злого в этом не было. Будто в этом мире так принято. Когда в итоге я устроился к ребятам, то вместо работы мы достаточно долго общались о том, что работа как раз таки нет. Сидя в большой уютной комнате с теплым светом и деревянной мебелью, главный в этой компании парень (который хотел меня убить на инициации) рассказал, что ему уже много месяцев не платят деньги."}]}]}','2026-01-08 18:51:46','2026-01-08 18:52:06',3,'2025-01-17T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(459,2,'post-1767887535','Крыша, Таня и вода','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Снилось, как я гуляю по незнакомому городу с Таней и её подругами — видимо, нашими общими друзьями, но я их не помню, как будто знаю их мало. Мы идём, проходим какой-то мини-рынок: множество людей, маленьких палаток, все что-то продают. Нам хочется попить, утолить жажду, что-то выпить."}]},{"type":"paragraph","content":[{"type":"text","text":"Подруги уходят немного вперёд, а мы идём с Таней чуть позади. Она суёт мне в карман 1000 ₽. Я не сразу вижу, сколько, просто понимаю, что она даёт деньги, потому что у меня как будто нет. Она уходит за подругами и говорит: «Купи что-нибудь нам и догоняй». И они уходят вперёд."}]},{"type":"paragraph","content":[{"type":"text","text":"Я начинаю искать палатку, где можно купить что-то попить. Хожу туда-сюда, но почему-то среди всех этих палаток совсем нет ничего для питья. Воды вообще нет. Помню палатку с кошачьей едой, одеждой, сладостями, но воды не было."}]},{"type":"paragraph","content":[{"type":"text","text":"В какой-то момент я гулял-гулял и заблудился. Попал в торговый центр. Потом оказался на крыше этого ТЦ, проходил через офисы, где работало много людей. Когда оказался на крыше, я понял, где нахожусь, потому что сверху было видно. Но когда спустился вниз и снова пришёл к тому месту, где начинался сон, я уже никого не нашёл. Решил вернуться домой."}]},{"type":"paragraph","content":[{"type":"text","text":"Я возвращаюсь домой — это съёмная квартира — и понимаю, что нет смысла их искать, проще подождать дома. Квартира мне не очень нравится, там три или даже четыре комнаты."}]},{"type":"paragraph","content":[{"type":"text","text":"В какой-то момент я захожу в туалет — как будто кто-то недавно вышел. Вижу, что там нагадили и не смыли. Начинаю это смывать."}]},{"type":"paragraph","content":[{"type":"text","text":"Тут приходит Таня с девчонками. Я вижу, что она расстроена. Есть ощущение, что они что-то ей наговорили про меня, будто я специально их кинул, и она поэтому со мной не разговаривает. Я пытаюсь ей сказать, оправдаться, объяснить, что я потерялся, не мог найти, решил пройти домой, потому что очень хотел в туалет. И показываю, как будто я только что сам сходил — что вот, не мог иначе. Она мне ничего не отвечает и уходит в другую комнату."}]},{"type":"paragraph","content":[{"type":"text","text":"Я ложусь где-то почти в коридоре — там стоит кровать — просто ложусь, не зная, что делать. Помню, что листал на телефоне что-то вроде тиндер-ленты: не то чтобы хотел знакомиться, просто листал картинки."}]},{"type":"paragraph","content":[{"type":"text","text":"В какой-то момент звонок в дверь. Заходят пацаны. Сначала казалось, что девчонки заказали йогу. Пришло 3 или 4 взрослых мужчины лет по 30 и один пацан лет 17. Они были как будто не совсем русские — то ли дагестанцы, то ли индусы, я не понял. Девчонки расходятся по комнатам, эти ребята начинают раздеваться. Я не понимаю, что происходит, думаю, что это какая-то йога."}]},{"type":"paragraph","content":[{"type":"text","text":"В какой-то момент вижу, что Таня уходит в комнату одна, за ней эти ребята. Я понимаю, что они то ли ебаться будут, то ли что. Как будто она пытается этим мне мстить. Я лежу ещё какое-то время, а потом понимаю, что мне невыносимо. Встаю с кровати и начинаю одеваться."}]},{"type":"paragraph","content":[{"type":"text","text":"Приходит Таня, а я просто молча беру вещи, беру свой зеркальный фотоаппарат и ухожу."}]},{"type":"paragraph","content":[{"type":"text","text":"В этот момент я уже почти проснулся: осознаю себя в комнате, где сплю. Сон как будто выключается. Я вижу отрывки — будто я лечу. Я вижу среди облаков, с высоты птичьего полёта, несколько локаций. Облака летят рядом со мной, мы летим вместе. Следующий кадр — я то же самое вижу снизу: стою где-то на улице, смотрю вверх, вижу эти облака и вижу мир сразу со всех сторон. Очень интересно."}]},{"type":"paragraph","content":[{"type":"text","text":"К этому моменту я окончательно просыпаюсь. Чувствую себя грустно, понимаю, что я ушёл и всё закончилось, и мне от этого плохо. И почему-то вижу, что Таня тоже расстроена — больше из-за того, что она повелась на то, что ей наговорили подруги, из-за чего всё так вышло. Хотя я чувствую и свою вину — что соврал ей, будто очень хотел в туалет, а на самом деле просто решил пойти домой, потому что не понял, что делать. Чувство вины осталось."}]},{"type":"paragraph","content":[{"type":"text","text":"Снилось, что я гуляю по незнакомому городу с Таней и её подругами — как будто нашими общими знакомыми, но я их толком не помню. Мы идём по улице, лето, день, людей и машин немного. Начало походило на место напротив входа в ТЦ «21 век» в Калуге, но быстро всё сменилось на небольшой уличный рынок с множеством мелких палаток. Людей стало намного больше, мы протискивались в потоке."}]},{"type":"paragraph","content":[{"type":"text","text":"Нам захотелось пить. Не воду, не конкретный напиток и не алкоголь — просто что-то, что нужно прямо сейчас. Подруги пошли вперёд, а мы с Таней чуть отстали. Она оглянулась на подруг, убедилась, что они не смотрят, подошла ко мне максимально близко и сунула мне в карман деньги. Я тогда не видел сумму. Она сказала: «Купи что-нибудь нам и догоняй». Потом ушла за подругами. Сколько денег она дала, я понял только в самом конце сна, когда уже уходил из квартиры."}]},{"type":"paragraph","content":[{"type":"text","text":"Я начал искать, где купить что-то попить. Ходил между палатками, но среди всего (кошачья еда, одежда, сладости) не было ничего питьевого. Вообще ничего. Пока искал, заблудился и оказался внутри торгового центра. Не помню, как поднялся — лестницу или эскалатор — этого не было в памяти. Рынок неожиданно “перерастал” в ТЦ, а затем в офисный опенспейс, полный людей в бледно-голубых рубашках. Сплошные офисные комнаты, стекло, очереди рабочих мест."}]},{"type":"paragraph","content":[{"type":"text","text":"В какой-то момент у меня появилось ощущение, что я здесь чужой, что меня “раскрыли” и надо уходить. Я вышел на крышу ТЦ. Она была как отдельная улица: чистая плитка, лавочки, цветы в горшках, маленькие деревья, люди спокойно гуляют. С крыши я увидел весь рынок как карту внизу и даже будто понял, куда нужно идти, чтобы найти Таню. Но не помню, как спускался, и вместо поиска просто оказался в квартире."}]},{"type":"paragraph","content":[{"type":"text","text":"Квартира была большая, съёмная, на несколько комнат — как времянка, снятая не от хорошей жизни, а чтобы сэкономить. Я зашёл в туалет — кто-то недавно вышел, нагадил и не смыл. Я начал это смывать. В этот момент пришли Таня и подруги. Таня выглядела расстроенной, будто подруги что-то ей наговорили про меня, и теперь ей кажется, что я их специально бросил. Я пытался объяснить, что потерялся, не мог найти, хотел в туалет, но она ничего не ответила и ушла в другую комнату."}]},{"type":"paragraph","content":[{"type":"text","text":"Таня была моложе, чем сейчас, и в ней была сильная тоска — как будто она уже прошла через панику и попытки вернуть, а теперь осталось только чувство, что что-то упущено невозвратимо. Где-то между сюжетами мелькала её огромная тяжёлая сумка через плечо — то ли она её несла, то ли я взял её на какое-то время. Она плохо смотрелась на мне, и мне было очень тяжело её нести. Эта деталь будто не находила места в сюжете, как отдельный кусок кода, который всё равно важен."}]},{"type":"paragraph","content":[{"type":"text","text":"Я лёг на кровать в коридоре и листал что-то вроде Тиндера — не чтобы знакомиться, просто механически перелистывал."}]},{"type":"paragraph","content":[{"type":"text","text":"Позже в дверь позвонили. Зашли мужчины — трое или четверо взрослых и один молодой парень лет 17. Не совсем понятной национальности — то ли дагестанцы, то ли индусы. Я думал, что это какие-то инструкторы по йоге. Девчонки разошлись по комнатам, мужчины начали раздеваться. Я не понимал, что происходит. В какой-то момент Таня ушла одна в комнату, и за ней кто-то из этих мужчин. Я понял, что это не йога, и что она делает это назло. Я лежал ещё немного, потом понял, что больше не могу. Встал, оделся."}]},{"type":"paragraph","content":[{"type":"text","text":"Таня вышла ко мне, но я просто молча взял вещи, зеркалку и ушёл."}]},{"type":"paragraph","content":[{"type":"text","text":"Почти проснувшись, я как будто “вылетел” из сна и видел кадры: как лечу над облаками, как улицы и места из сна пролетают подо мной. Потом видел то же снизу — стою на улице, смотрю вверх, вижу облака и ощущаю мир сразу со всех сторон. В этот момент окончательно проснулся."}]},{"type":"paragraph","content":[{"type":"text","text":"Проснулся грустным. Было чувство, что я сам всё закончил, ушёл, и теперь уже поздно. И было ощущение, что Таня тоже расстроена — потому что поверила словам подруг и сделала всё импульсивно. И я чувствовал свою вину за то, что соврал ей: что, мол, очень хотел в туалет, а на самом деле просто не понял, что делать и ушёл домой."}]}]}','2026-01-08 18:52:15','2026-01-08 18:53:18',2,'2025-11-25T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(460,2,'post-1767887607','Rai & Убийство & Rai','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Сны сегодня просто безумные!"}]},{"type":"paragraph","content":[{"type":"text","text":"Снилось много, запомнил часть. Вот что снилось. Будто я дома у порноактрисы Alina Rai, мы мило общаемся и даже как будто бы не сильно много трахаемся. И еще ребят каких-то ждем, друзей или вроде того. И все это время мне достаточно уютно и я воспринимаю себя собой. Пока внезапно со мной не случается толи флешбек, толи так бесцеремонно сменяется сцена, что я совершенно внезапно оказываюсь на улице. Это района рынка, зима, день (интересно, что вчера мне так же снился рынок, правда совершенно другой, но паттерн: палатки, много людей, продажа, сохранился). В этот раз я пробираюсь сквозь эти палатки и людей очень, очень смело, уверено и тут скорее они уворачиваются от меня. Но это не придает мне успеха в в том деле, котором нахожусь: я вижу за собой слежку. Оборачиваюсь и вижу двух молодых мужчин, которые явно палятся, идут за мной. Я ускоря шаг, пытаюсь оторвать но оказавшись на открытой местности, будто проскочив рынок вышел на безлюдное поле, мужчины тут же меня доганяют и убивают. Причем делают это чрезвычайно жесто. Сначала меня валят на землю. Затем пиздят ногами. Достают из куртки каждый по автоматическому пистолету и выпускают ленту в мое тело. Затем одевают на запястье какое-то хитрое оборудование на проводе, как ошейник у собаки на веревке. Тот кто одел это на меня дергает за провод, срабатывает механизм и рука разрывается в районе запястья. Они еще мучают мой труп какое-то время, но теперь меня интересует другое. Я уже довольно давно удалился от тела перестав рефлексировать мирское и как душа смотрю на себя и понимаю, что я это здоровенный такой накаченный мужчина средних лет. Причем накаченный не как в зале, а видно что он прям просто так жил, что мышцы выросли. Какой-то спецагент должно быть. Но я не успеваю додумать все эти дела и оказываюсь в квартире у Alina Rai снова. И тут понимаю, да это был флешбек! И тут меня накрвает: бля как я тогда выжел в тот раз? Дальше фрагментарно. Помню что-то вроде магии, силы намеренья и того, как оно действует в пространстве сна, что им можно буквально горы свернуть! И таким образом я выжил. Мы еще несолько раз потрахались с Alina Rai и что-то такое поделали и я ушел. Локаца напомнает какой-то крутой отель или зал где проводят конференции, банкеты. Очень сложно оценить когда ты только на входе. И я иду туда, я – этот все тот же огромный мужик, которого жестко убили неизвестно когда и мне это пришло флеш-беком. И тут я вижу еще более огромного мужика! И он здоровается с моим другом который идет впереди, а со мной еще и перекидывается несколькими фразами друг впереди так на это смотрит, типа это мужик какая-то легенда и с ним просто поздороваться пиздец, а загооворить так вообще… Забавно, это немножко льстит, но мое внимание быстро переключается на слова этого здоровенного мужика о том, что меня (или моего персонажа =) убили в качестве то ли какой-то проверки… хотя не скорее за какой-то косяк. А то что я выжил и вернул тело и вообще вернулся, это уже второй этап, это проверка, раз типа я смог значит все идут нахуй и мы снова работаем вместе. На этом сюжетная линия все. Дальше снился карлик который работал в крутом пристижном институте и я видел как он едет в метро. Зачем это снится? А Алины было классно в квартире. Уютно как дома. Вот это запомнилось очень хорошо."}]}]}','2026-01-08 18:53:27','2026-01-08 18:55:00',1,'2025-11-27T21:00:00.000Z','твои сны');
INSERT INTO nest_posts VALUES(461,2,'post-1767887653','Три фракции','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Мне приснился необычный игровой сон. Давно не видел снов с таким сюжетным размахом."}]},{"type":"paragraph","content":[{"type":"text","text":"В этом мире существовало несколько фракций, и нужно было выбрать, к какой из них я принадлежу."}]},{"type":"paragraph","content":[{"type":"text","text":"Первая фракция была самой сильной и многочисленной. Она позиционировалась как исследовательская: люди искали сокровища, сражались, постоянно куда-то лезли и что-то добывали. Я был частью этой фракции и, кажется, находился в её верхушке."}]},{"type":"paragraph","content":[{"type":"text","text":"Потом произошла драка. У меня был близкий товарищ — друг, коллега, кто-то близкий по духу, но детали стерлись. Мы начали сражаться без объяснений. Драка была жестокой — мы избили друг друга почти до смерти. Я оказался в госпитале. Отношение к нам обоим резко ухудшилось — мы подвели большое количество людей, сорвали какие-то важные процессы. Было ощущение, будто мы сломали планы огромной организации. Деталей я не помню, только контекст."}]},{"type":"paragraph","content":[{"type":"text","text":"В госпитале я начал изучать две другие фракции."}]},{"type":"paragraph","content":[{"type":"text","text":"Вторая — «средняя», про неё было мало информации. Она отличалась от той, где я был, но не запомнилась."}]},{"type":"paragraph","content":[{"type":"text","text":"Третья — самая маленькая и закрытая. Это была небольшая группа, почти семья. Они специализировались на скрытых действиях — чем-то вроде тайных убийц или ассасинов. Но они не занимались бессмысленным насилием и не ходили по миру ради исследований или фарма монстров."}]},{"type":"paragraph","content":[{"type":"text","text":"У фракции была собственная идея о том, как должен меняться мир. Они брали на себя самые сложные задачи — вмешательство в мировые переломы: революции, войны, возможно даже какие-то глобальные катастрофы. Если что-то шло не так, они вмешивались и «отменяли» ход событий."}]},{"type":"paragraph","content":[{"type":"text","text":"Когда-то давно эта фракция была чем-то вроде королевской стражи. Самой крутой силой в мире. Все их боялись, но никто их не видел. Они появлялись только тогда, когда происходило что-то значимое."}]},{"type":"paragraph","content":[{"type":"text","text":"В неё невозможно было вступить просто так — нельзя найти членов, нельзя узнать, как к ним присоединиться. Но, видимо, из-за той драки и какой-то идеи, которую мы с тем мужиком разделяли, ко мне пришли и взяли."}]},{"type":"paragraph","content":[{"type":"text","text":"Я вступил, хотя до конца не понял, как это произошло."}]},{"type":"paragraph","content":[{"type":"text","text":"Госпиталь запомнился ярче всего."}]},{"type":"paragraph","content":[{"type":"text","text":"Там был врач, мужчина. Мы ходили по помещению, он что-то рассказывал о госпитале и о том, что мы натворили. Я почти ничего не запомнил."}]},{"type":"paragraph","content":[{"type":"text","text":"Зашёл в душевую — грязные чужие полотенца, своих вещей не было. Кажется, я так и не помылся."}]},{"type":"paragraph","content":[{"type":"text","text":"Потом вернулся в свою палату — небольшая комната, кровать, окно. Вид был потрясающий: летний день, высокий этаж, яркий свет."}]},{"type":"paragraph","content":[{"type":"text","text":"Зашла медсестра — небольшого роста, напомнила одну знакомую, которую я видел только однажды."}]},{"type":"paragraph","content":[{"type":"text","text":"Мы пообщались, она сделала мне какие-то уколы. Относилась ко мне нейтрально-позитивно, без осуждения."}]},{"type":"paragraph","content":[{"type":"text","text":"Потом она начала собираться на какое-то мероприятие. Надела жёлтое платье и туфли на очень высоких каблуках. Я сказал что-то вроде: «Ничего себе, у тебя туфли». Она ответила пару слов и ушла."}]},{"type":"paragraph","content":[{"type":"text","text":"Я вышел в коридор и столкнулся с человеком, которого, по ощущениям, давно знаю. Он был недоволен:"}]},{"type":"paragraph","content":[{"type":"text","text":"— Ну что, подрались вы там..."}]},{"type":"paragraph","content":[{"type":"text","text":"Я подтвердил. Он вздохнул, ничего не сказал и пошёл дальше."}]},{"type":"paragraph","content":[{"type":"text","text":"Тогда я осознал масштаб — что мы сделали что-то не просто некрасивое, а невозможное для нашей фракции. Как если бы два лидера партии устроили драку в прямом эфире."}]},{"type":"paragraph","content":[{"type":"text","text":"На этом эпизод с госпиталем закончился."}]},{"type":"paragraph","content":[{"type":"text","text":"В самом начале сна был ещё эпизод от третьего лица."}]},{"type":"paragraph","content":[{"type":"text","text":"Три человека шли через лес и поля. Перед ними — огромная пропасть, ниже на километры — равнина. Спрыгнуть — разбиться. Красиво, опасно. Они убивали маленьких монстров — как в компьютерной игре. Я не помню, зачем, просто наблюдал."}]},{"type":"paragraph","content":[{"type":"text","text":"Интересно то, что я несколько раз просыпался, потому что ночью выпил вина и мучила жажда. Каждый раз, возвращаясь ко сну, я будто снова «подключался» к нему. Как если бы сон шёл автономно, а я лишь возвращался в трансляцию."}]},{"type":"paragraph","content":[{"type":"text","text":"Ощущение было таким, будто это не мой сон, а система, в которую можно войти и выйти."}]},{"type":"paragraph","content":[{"type":"text","text":"У всего сна есть странное послевкусие. Как будто душа или игрок «я» ночью отправляется куда-то далеко — в виртуальный мир или параллельную реальность. Я просыпаюсь и пытаюсь вспомнить, но многим событиям просто нет слов. В нашем мире отсутствуют понятия, чтобы это описать."}]},{"type":"paragraph","content":[{"type":"text","text":"Как если бы человек из каменного века побывал в современном мире — увидел компьютеры, машины, ИИ — и попытался рассказать об этом, не имея понятий, языка, контекста."}]},{"type":"paragraph","content":[{"type":"text","text":"Так же и я: вижу миры, но не могу их описать."}]},{"type":"paragraph","content":[{"type":"text","text":"Приходится придумывать слова и истории, чтобы хоть как-то передать то, что там происходит."}]},{"type":"paragraph","content":[{"type":"text","text":"Этот сон был длинным, насыщенным, как несколько прожитых жизней. И мне удалось запомнить лишь часть."}]}]}','2026-01-08 18:54:13','2026-01-08 18:55:28',0,'2025-12-02T21:00:00.000Z','твои сны');
